module smallest_number(
    input [3:0] A,
    input [3:0] B,
    input [3:0] C,
    output reg [3:0] smallest
);

always @(*) begin
    if (A <= B && A <= C) begin
        smallest = A;
    end else if (B <= A && B <= C) begin
        smallest = B;
    end else begin
        smallest = C;
    end
end

endmodule

sva_code:
// SVA for smallest_number
module smallest_number_sva #(parameter int W=4)
(
  input logic [W-1:0] A, B, C,
  input logic [W-1:0] smallest
);

  function automatic logic [W-1:0] f_min3 (input logic [W-1:0] a,b,c);
    if (a<=b && a<=c) f_min3 = a;
    else if (b<=a && b<=c) f_min3 = b;
    else f_min3 = c;
  endfunction

  // Correctness: output is the min when inputs are known
  property p_min_value;
    @(A or B or C or smallest) disable iff ($isunknown({A,B,C}))
      1'b1 |-> ##0 (smallest == f_min3(A,B,C));
  endproperty
  assert property (p_min_value);

  // Priority/branch checks (including tie resolution)
  property p_pick_A;
    @(A or B or C or smallest) disable iff ($isunknown({A,B,C}))
      (A<=B && A<=C) |-> ##0 (smallest == A);
  endproperty
  assert property (p_pick_A);

  property p_pick_B;
    @(A or B or C or smallest) disable iff ($isunknown({A,B,C}))
      (!(A<=B && A<=C) && (B<=A && B<=C)) |-> ##0 (smallest == B);
  endproperty
  assert property (p_pick_B);

  property p_pick_C;
    @(A or B or C or smallest) disable iff ($isunknown({A,B,C}))
      (!(A<=B && A<=C) && !(B<=A && B<=C)) |-> ##0 (smallest == C);
  endproperty
  assert property (p_pick_C);

  // X-propagation sanity: known inputs -> known output
  property p_known_out_when_known_in;
    @(A or B or C or smallest)
      (!$isunknown({A,B,C})) |-> ##0 (!$isunknown(smallest));
  endproperty
  assert property (p_known_out_when_known_in);

  // Coverage: unique minima, tie cases, and extreme
  cover property (@(A or B or C) (A<B && A<C));      // unique A min
  cover property (@(A or B or C) (B<A && B<C));      // unique B min
  cover property (@(A or B or C) (C<A && C<B));      // unique C min
  cover property (@(A or B or C) (A==B && A<C));     // A==B < C (A chosen)
  cover property (@(A or B or C) (A==C && A<B));     // A==C < B (A chosen)
  cover property (@(A or B or C) (B==C && B<A));     // B==C < A (B chosen)
  cover property (@(A or B or C) (A==B && B==C));    // all equal
  cover property (@(A or B or C) (smallest==0));     // min at 0

endmodule

// Bind to DUT
bind smallest_number smallest_number_sva sva_smallest_number(.A(A), .B(B), .C(C), .smallest(smallest));

verilog_code:
module top_module (
    input CLK,
    input UP_DOWN,
    input RESET,
    input EN,
    input select,
    input [3:0] A,
    input [3:0] B,
    output [3:0] OUT1,
    output [7:0] OUT2
);

wire [3:0] counter_out;
wire [7:0] multiplier_out;

up_down_counter udc (
    .CLK(CLK),
    .UP_DOWN(UP_DOWN),
    .RESET(RESET),
    .EN(EN),
    .OUT(counter_out)
);

binary_multiplier bm (
    .A(select ? A : B),
    .B(select ? B : A),
    .OUT(multiplier_out)
);

assign OUT1 = counter_out;
assign OUT2 = multiplier_out;

endmodule

module up_down_counter (
    input CLK,
    input UP_DOWN,
    input RESET,
    input EN,
    output [3:0] OUT
);

reg [3:0] count;

always @(posedge CLK or posedge RESET) begin
    if (RESET) begin
        count <= 4'b0;
    end else if (EN) begin
        count <= UP_DOWN ? count + 4'b1 : count - 4'b1;
    end
end

assign OUT = count;

endmodule

module binary_multiplier (
    input [3:0] A,
    input [3:0] B,
    output [7:0] OUT
);

assign OUT = A * B;

endmodule

sva_code:
// SVA for up_down_counter
module udc_sva(input CLK, input UP_DOWN, input RESET, input EN, input [3:0] OUT);
  default clocking cb @ (posedge CLK); endclocking

  // Reset/hold/update semantics
  a_reset_sync: assert property (RESET |-> OUT==4'h0) else $error("UDC: OUT not 0 during RESET");
  a_hold:       assert property (!RESET && !EN |-> OUT == $past(OUT)) else $error("UDC: OUT changed while EN=0");
  a_inc:        assert property (!RESET && EN &&  UP_DOWN |-> OUT == $past(OUT)+4'd1) else $error("UDC: INC wrong");
  a_dec:        assert property (!RESET && EN && !UP_DOWN |-> OUT == $past(OUT)-4'd1) else $error("UDC: DEC wrong");
  a_change_en:  assert property (!RESET && !$isunknown($past(OUT)) && (OUT != $past(OUT)) |-> EN) else $error("UDC: OUT changed without EN");

  // Async reset edge
  always @(posedge RESET) assert (OUT==4'h0) else $error("UDC: OUT not 0 on RESET edge");

  // Coverage
  c_inc:       cover property (!RESET && EN &&  UP_DOWN);
  c_dec:       cover property (!RESET && EN && !UP_DOWN);
  c_wrap_up:   cover property (!RESET && EN &&  UP_DOWN && $past(OUT)==4'hF |-> OUT==4'h0);
  c_wrap_down: cover property (!RESET && EN && !UP_DOWN && $past(OUT)==4'h0 |-> OUT==4'hF);
  c_hold:      cover property (!RESET && !EN |-> OUT==$past(OUT));
  c_reset:     cover property (RESET);
endmodule

// SVA for top: mux/connectivity and multiplier
module top_sva(
  input CLK,
  input select,
  input [3:0] A,
  input [3:0] B,
  input [3:0] OUT1,
  input [7:0] OUT2,
  input [3:0] udc_OUT,
  input [3:0] bm_A,
  input [3:0] bm_B,
  input [7:0] bm_OUT
);
  default clocking cb @ (posedge CLK); endclocking

  // Connectivity
  a_out1_conn: assert property (OUT1 == udc_OUT) else $error("TOP: OUT1 not from UDC");
  a_out2_conn: assert property (OUT2 == bm_OUT)  else $error("TOP: OUT2 not from BM");

  // Mux into multiplier
  a_mux_sel1: assert property (select  |-> (bm_A==A && bm_B==B)) else $error("TOP: select=1 mapping wrong");
  a_mux_sel0: assert property (!select |-> (bm_A==B && bm_B==A)) else $error("TOP: select=0 mapping wrong");

  // Multiplier correctness and end-to-end product
  a_mul_correct:  assert property (bm_OUT == (bm_A * bm_B)) else $error("BM: OUT != A*B");
  a_e2e_product:  assert property (OUT2   == (A * B))       else $error("TOP: OUT2 != A*B");

  // Coverage
  c_sel1:        cover property (select);
  c_sel0:        cover property (!select);
  c_sel_rise:    cover property ($rose(select));
  c_sel_fall:    cover property ($fell(select));
  c_mul_zero:    cover property (bm_A==4'h0 || bm_B==4'h0);
  c_mul_max:     cover property (bm_A==4'hF && bm_B==4'hF);
endmodule

// Bind assertions
bind up_down_counter udc_sva u_udc_sva(
  .CLK(CLK),
  .UP_DOWN(UP_DOWN),
  .RESET(RESET),
  .EN(EN),
  .OUT(OUT)
);

bind top_module top_sva u_top_sva(
  .CLK(CLK),
  .select(select),
  .A(A),
  .B(B),
  .OUT1(OUT1),
  .OUT2(OUT2),
  .udc_OUT(udc.OUT),
  .bm_A(bm.A),
  .bm_B(bm.B),
  .bm_OUT(bm.OUT)
);

