module binary_counter(
    input clk, reset, enable,
    output reg [3:0] q
);

always @(posedge clk or posedge reset) begin
    if(reset) begin
        q <= 4'b0000;
    end
    else if(enable) begin
        q <= q + 1;
    end
end

endmodule

sva_code:
// SVA for binary_counter
// Concise, high-quality checks + useful coverage

module binary_counter_sva #(parameter WIDTH=4) (
  input logic                 clk,
  input logic                 reset,
  input logic                 enable,
  input logic [WIDTH-1:0]     q
);

  // Asynchronous reset drives q to 0 immediately (post-NBA in same timestep)
  ap_async_reset_zero: assert property (@(posedge reset) ##0 (q == '0));

  // When reset is high at a clock edge, q must be 0 (post-NBA at that edge)
  ap_sync_observe_reset_zero: assert property (@(posedge clk) reset |-> ##0 (q == '0));

  // q must never be X/Z at clock edges and after reset assertion
  ap_q_known_clk:   assert property (@(posedge clk)  !$isunknown(q));
  ap_q_known_reset: assert property (@(posedge reset) ##0 !$isunknown(q));

  // Functional behavior on clock edges when not in reset
  // Hold when disabled
  ap_hold_when_disabled: assert property (@(posedge clk) disable iff (reset)
                                          !enable |=> q == $past(q));
  // Increment by 1 (mod 2^WIDTH) when enabled
  ap_inc_when_enabled:   assert property (@(posedge clk) disable iff (reset)
                                          enable |=> q == ($past(q) + WIDTH'(1)));

  // Minimal coverage
  // See a reset event
  cp_reset:     cover property (@(posedge reset) 1);
  // See a hold cycle
  cp_hold:      cover property (@(posedge clk) disable iff (reset)
                                !enable |=> q == $past(q));
  // See an increment
  cp_inc:       cover property (@(posedge clk) disable iff (reset)
                                enable |=> q == ($past(q) + WIDTH'(1)));
  // See wrap-around from max to zero
  cp_wrap:      cover property (@(posedge clk) disable iff (reset)
                                $past(q) == {WIDTH{1'b1}} && enable |=> q == '0);
  // See enable toggle around counting
  cp_en_toggle: cover property (@(posedge clk) disable iff (reset)
                                !enable ##1 enable ##1 !enable);

endmodule

// Bind into the DUT
bind binary_counter binary_counter_sva #(.WIDTH(4)) u_binary_counter_sva (
  .clk(clk),
  .reset(reset),
  .enable(enable),
  .q(q)
);

verilog_code:
module four_bit_adder (
    A,
    B,
    CI,
    SUM,
    COUT
);

    input [3:0] A;
    input [3:0] B;
    input CI;
    output [3:0] SUM;
    output COUT;

    wire [3:0] a_xor_b;
    wire [3:0] a_xor_b_xor_ci;
    wire [3:0] a_and_b;
    wire [3:0] a_and_b_and_ci;
    wire [3:0] a_or_b;
    wire [3:0] a_or_b_or_ci;
    wire a_xor_b_xor_ci_xor_cout;

    // Implement the adder logic using only the allowed gates and the named wires
    xor xor0 (a_xor_b[0], A[0], B[0]);
    xor xor1 (a_xor_b[1], A[1], B[1]);
    xor xor2 (a_xor_b[2], A[2], B[2]);
    xor xor3 (a_xor_b[3], A[3], B[3]);

    xor xor4 (a_xor_b_xor_ci[0], a_xor_b[0], CI);
    xor xor5 (a_xor_b_xor_ci[1], a_xor_b[1], CI);
    xor xor6 (a_xor_b_xor_ci[2], a_xor_b[2], CI);
    xor xor7 (a_xor_b_xor_ci[3], a_xor_b[3], CI);

    and and0 (a_and_b[0], A[0], B[0]);
    and and1 (a_and_b[1], A[1], B[1]);
    and and2 (a_and_b[2], A[2], B[2]);
    and and3 (a_and_b[3], A[3], B[3]);

    and and4 (a_and_b_and_ci[0], a_and_b[0], CI);
    and and5 (a_and_b_and_ci[1], a_and_b[1], CI);
    and and6 (a_and_b_and_ci[2], a_and_b[2], CI);
    and and7 (a_and_b_and_ci[3], a_and_b[3], CI);

    or or0 (a_or_b[0], A[0], B[0]);
    or or1 (a_or_b[1], A[1], B[1]);
    or or2 (a_or_b[2], A[2], B[2]);
    or or3 (a_or_b[3], A[3], B[3]);

    or or4 (a_or_b_or_ci[0], a_or_b[0], CI);
    or or5 (a_or_b_or_ci[1], a_or_b[1], CI);
    or or6 (a_or_b_or_ci[2], a_or_b[2], CI);
    or or7 (a_or_b_or_ci[3], a_or_b[3], CI);

    xor xor8 (a_xor_b_xor_ci_xor_cout, a_xor_b_xor_ci[3], a_and_b_and_ci[3]);

    // Assign the output ports
    assign SUM = a_xor_b_xor_ci;
    assign COUT = a_xor_b_xor_ci_xor_cout;

endmodule

