sva_code:
// SVA for Deco_Round_Mult
module Deco_Round_Mult_sva (
  input logic [1:0] round_mode,
  input logic or_info,
  input logic xor_info,
  input logic ctrl
);

  // Knownness: if inputs are known, output must be known
  assert property (@(round_mode or or_info or xor_info or ctrl)
                   !$isunknown({round_mode,or_info,xor_info}) |-> !$isunknown(ctrl))
    else $error("ctrl is X/Z with known inputs");

  // Functional equivalence (when inputs are known)
  assert property (@(round_mode or or_info or xor_info or ctrl)
                   !$isunknown({round_mode,or_info,xor_info})
                   |-> (ctrl === (or_info &&
                                   ((round_mode==2'b01 && xor_info) ||
                                    (round_mode==2'b10 && !xor_info)))))
    else $error("ctrl decode mismatch");

  // Sanity: if or_info is 0, ctrl must be 0 (regardless of round_mode/xor_info if known)
  assert property (@(round_mode or or_info or xor_info or ctrl)
                   !$isunknown(or_info) && (or_info==1'b0) |-> (ctrl===1'b0))
    else $error("ctrl not 0 when or_info=0");

  // Coverage: exercise all meaningful decode combinations
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b01) && !xor_info && (ctrl==1'b0));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b01) &&  xor_info && (ctrl==1'b1));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b10) && !xor_info && (ctrl==1'b1));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b10) &&  xor_info && (ctrl==1'b0));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b00) && (ctrl==1'b0));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  or_info && (round_mode==2'b11) && (ctrl==1'b0));
  cover property (@(round_mode or or_info or xor_info or ctrl)
                  !or_info && (ctrl==1'b0));

endmodule

bind Deco_Round_Mult Deco_Round_Mult_sva sva_i (.*);

verilog_code:
module shift_register (Clock, ALOAD, D, SO);
  input [8:0] D;
  input Clock, ALOAD;
  output reg SO;
  reg [8:0] tmp;
  wire n22;

  // D flip-flops to store the input data
  always@(posedge Clock)
  begin
    tmp[8] <= tmp[7];
    tmp[7] <= tmp[6];
    tmp[6] <= tmp[5];
    tmp[5] <= tmp[4];
    tmp[4] <= tmp[3];
    tmp[3] <= tmp[2];
    tmp[2] <= tmp[1];
    tmp[1] <= tmp[0];
    tmp[0] <= D[0];
  end

  // Perform the shift operation
  always@(posedge Clock)
  begin  
    SO <= (ALOAD)? D[0] : tmp[1];
    tmp[8] <= (ALOAD)? D[0] : tmp[1];
  end

  // Combinational logic to generate n22
  assign n22 = ALOAD & tmp[8];
endmodule

sva_code:
// SVA checker bound to the DUT
module shift_register_sva (
  input logic        Clock,
  input logic        ALOAD,
  input logic [8:0]  D,
  input logic        SO,
  input logic [8:0]  tmp,
  input logic        n22
);
  default clocking cb @(posedge Clock); endclocking

  // Guard for $past()
  logic past_valid;
  always_ff @(posedge Clock) past_valid <= 1'b1;

  // Sanity: no X on key signals (sampled)
  assert property (disable iff (!past_valid) !$isunknown(ALOAD) && !$isunknown(D[0]));
  assert property (!$isunknown(SO));
  assert property (!$isunknown(n22));

  // Combinational equivalence
  assert property (n22 === (ALOAD & tmp[8]));

  // Sequential next-state checks
  assert property (disable iff (!past_valid) tmp[0] == $past(D[0]));
  genvar i;
  generate
    for (i = 1; i <= 7; i++) begin : g_shifts
      assert property (disable iff (!past_valid) tmp[i] == $past(tmp[i-1]));
      cover  property (disable iff (!past_valid) tmp[i] == $past(tmp[i-1]));
    end
  endgenerate

  // SO and tmp[8] next-state behavior
  assert property (disable iff (!past_valid)
                   SO == ($past(ALOAD) ? $past(D[0]) : $past(tmp[1])));
  assert property (disable iff (!past_valid)
                   tmp[8] == ($past(ALOAD) ? $past(D[0]) : $past(tmp[1])));
  // Optional same-cycle consistency (checked at next clock)
  assert property (disable iff (!past_valid) 1 |-> (tmp[8] == SO));

  // Detect multiple-driver conflict on tmp[8] across the two always blocks
  // If ALOAD=1, both blocks would assign D[0] vs tmp[7]
  // If ALOAD=0, both blocks would assign tmp[1] vs tmp[7]
  assert property (disable iff (!past_valid)
                   ($past(ALOAD)  && ($past(D[0])   == $past(tmp[7]))) ||
                   (!$past(ALOAD) && ($past(tmp[1]) == $past(tmp[7]))))
    else $error("tmp[8] next-state has conflicting drivers (race between always blocks)");

  // Functional coverage of both SO paths
  cover property (disable iff (!past_valid)  ALOAD  && (SO == $past(D[0])));
  cover property (disable iff (!past_valid) !ALOAD && (SO == $past(tmp[1])));
endmodule

// Bind into DUT
bind shift_register shift_register_sva sva_i (.*);

