verilog_code:
module shift_mux (
    input [3:0] data_in,
    input [3:0] in_0,
    input [3:0] in_1,
    input [3:0] in_2,
    input [3:0] in_3,
    input [1:0] sel,
    input shift,
    output reg [3:0] out
);

reg [3:0] shift_reg;

always @ (posedge shift) begin
    shift_reg <= {shift_reg[2:0], data_in[3]};
end

always @ (*) begin
    case (sel)
        2'b00: out <= in_0;
        2'b01: out <= in_1;
        2'b10: out <= in_2;
        2'b11: out <= in_3;
        default: out <= shift_reg;
    endcase
end

endmodule

sva_code:
// SVA for shift_mux
module shift_mux_sva (
  input logic [3:0] data_in,
  input logic [3:0] in_0, in_1, in_2, in_3,
  input logic [1:0]  sel,
  input logic        shift,
  input logic [3:0]  out,
  input logic [3:0]  shift_reg
);

  // Combinational mux correctness (4-state accurate)
  assert property ( (sel === 2'b00) -> (out == in_0) );
  assert property ( (sel === 2'b01) -> (out == in_1) );
  assert property ( (sel === 2'b10) -> (out == in_2) );
  assert property ( (sel === 2'b11) -> (out == in_3) );

  // If sel is X/Z, default branch to shift_reg
  assert property ( $isunknown(sel) -> (out == shift_reg) );

  // Out known when selected input is known
  assert property ( (sel===2'b00 && !$isunknown(in_0)) -> !$isunknown(out) );
  assert property ( (sel===2'b01 && !$isunknown(in_1)) -> !$isunknown(out) );
  assert property ( (sel===2'b10 && !$isunknown(in_2)) -> !$isunknown(out) );
  assert property ( (sel===2'b11 && !$isunknown(in_3)) -> !$isunknown(out) );

  // Shift register updates on posedge(shift)
  assert property (@(posedge shift)
    (!$isunknown($past(shift_reg))) |-> (shift_reg == {$past(shift_reg[2:0]), $past(data_in[3])})
  );

  // Shift register changes only on posedge(shift)
  assert property ( !$changed(shift_reg) or $rose(shift) );

  // Coverage
  cover property (sel===2'b00 && out==in_0);
  cover property (sel===2'b01 && out==in_1);
  cover property (sel===2'b10 && out==in_2);
  cover property (sel===2'b11 && out==in_3);
  cover property (@(posedge shift) 1);
  cover property (@(posedge shift) shift_reg == {$past(shift_reg[2:0]), $past(data_in[3])});
  cover property ($isunknown(sel) && out==shift_reg); // exercises default path

endmodule

// Bind into DUT
bind shift_mux shift_mux_sva sva_inst (.*);

verilog_code:
module binary_counter(
   input clk,
   input rst,
   input [15:0] max_count,
   output reg [15:0] count,
   output reg done
   );

   always @(posedge clk or posedge rst) begin
      if (rst) begin
         count <= 0;
         done <= 0;
      end
      else begin
         if (count == max_count) begin
            count <= 0;
            done <= 1;
         end
         else begin
            count <= count + 1;
            done <= 0;
         end
      end
   end

endmodule

sva_code:
// SVA for binary_counter
module binary_counter_sva #(parameter WIDTH=16) (
  input  logic                clk,
  input  logic                rst,
  input  logic [WIDTH-1:0]    max_count,
  input  logic [WIDTH-1:0]    count,
  input  logic                done
);

  // Asynchronous reset: immediate and hold behavior
  assert property (@(posedge rst) (count=='0 && done==1'b0))
    else $error("Async reset did not drive count/done to 0 immediately");
  assert property (@(posedge clk) rst |-> (count=='0 && done==1'b0))
    else $error("While rst=1, count/done must hold at 0");

  // Next-state functional correctness (gated off reset entry)
  assert property (@(posedge clk) disable iff (rst)
                   !$past(rst) |-> count == ( ($past(count)==$past(max_count)) ? '0 : ($past(count)+1) ))
    else $error("count next-state mismatch");
  assert property (@(posedge clk) disable iff (rst)
                   !$past(rst) |-> done == ($past(count)==$past(max_count)))
    else $error("done must reflect prior equality of count==max_count");

  // When done is asserted, count must be 0 in the same cycle
  assert property (@(posedge clk) disable iff (rst) done |-> (count=='0))
    else $error("done asserted without count==0");

  // Basic X checks on outputs (outside of reset)
  assert property (@(posedge clk) disable iff (rst) !$isunknown({count,done}))
    else $error("X/Z detected on outputs");

  // Coverage
  // - Observe a normal increment step
  cover property (@(posedge clk) disable iff (rst)
                  !$past(rst) && ($past(count)!= $past(max_count)) && (count==$past(count)+1) && !done);
  // - Observe a wrap event (equality -> reset to 0 with done=1)
  cover property (@(posedge clk) disable iff (rst)
                  !$past(rst) && ($past(count)==$past(max_count)) && (count=='0) && done);
  // - Observe a done rising edge
  cover property (@(posedge clk) disable iff (rst) $rose(done));
  // - Corner: max_count==0 leading to consecutive done assertions
  cover property (@(posedge clk) disable iff (rst) (max_count=='0) ##1 done ##1 done);

endmodule

// Bind into DUT
bind binary_counter binary_counter_sva #(.WIDTH(16)) u_binary_counter_sva (
  .clk(clk),
  .rst(rst),
  .max_count(max_count),
  .count(count),
  .done(done)
);

