  always_comb begin
    assert (!$isunknown({A,B,cin})) else $error("adder4bit_carry: X/Z on inputs A/B/cin");
    if (!$isunknown({A,B,cin})) begin
      assert (!$isunknown({S,cout})) else $error("adder4bit_carry: X/Z on outputs S/cout with clean inputs");
