    assert (#0 {cout,S} == ({1'b0,A} + {1'b0,B} + {1'b0,cin}))
      else $error("adder4bit_carry mismatch: A=%0h B=%0h cin=%0b -> S=%0h cout=%0b", A, B, cin, S, cout);
