barrel_shifter bs (
    .A(A),
    .shift_amount(shift_amount),
    .shift_dir(shift_dir),
    .Y(shifted_A)
);

wire [15:0] decoder_out;
decoder d (
    .enable(enable),
    .select(select),
    .out(decoder_out)
);

assign out = {16'b0, decoder_out[3:0]} | {shifted_A, 12'b0};

