verilog_code:
module barrel_shifter_16bit (
    input [15:0] D,
    input [3:0] shift_ctrl,
    output reg [15:0] Q
);
    always @(*) begin
        case(shift_ctrl)
            4'b0000: Q = D << 1;
            4'b0001: Q = D << 2;
            4'b0010: Q = D << 4;
            4'b0011: Q = D << 8;
            4'b0100: Q = D >> 1;
            4'b0101: Q = D >> 2;
            4'b0110: Q = D >> 4;
            4'b0111: Q = D >> 8;
            default: Q = D;
        endcase
    end
endmodule

module alu_32bit (
    input [31:0] a,
    input [31:0] b,
    input [3:0] ctrl,
    output reg [31:0] result
);
    always @(*) begin
        case(ctrl)
            4'b0000: result = a + b;
            4'b0001: result = a - b;
            4'b0010: result = a & b;
            4'b0011: result = a | b;
            4'b0100: result = a ^ b;
            default: result = a;
        endcase
    end
endmodule

module top_module (
    input [15:0] D,
    input [3:0] shift_ctrl,
    input [31:0] a,
    input [31:0] b,
    input [3:0] alu_ctrl,
    output reg [31:0] result
);

    // 16-bit barrel shifter
    wire [15:0] shifted_D;
    barrel_shifter_16bit bs16 (
        .D(D),
        .shift_ctrl(shift_ctrl),
        .Q(shifted_D)
    );

    // 32-bit ALU
    wire [31:0] alu_result;
    alu_32bit alu32 (
        .a(a),
        .b(b),
        .ctrl(alu_ctrl),
        .result(alu_result)
    );

    // Bitwise OR module
    wire [31:0] or_result;
    assign or_result = shifted_D | alu_result;

    // Output
    always @* begin
        result = or_result;
    end

endmodule

sva_code:
// SVA for barrel_shifter_16bit
module barrel_shifter_16bit_sva(
  input logic               clk,
  input logic               rst_n,
  input logic [15:0]        D,
  input logic [3:0]         shift_ctrl,
  input logic [15:0]        Q
);
  default clocking cb @(posedge clk); endclocking

  function automatic [15:0] f_shift(input [15:0] d, input [3:0] c);
    unique case (c)
      4'b0000: f_shift = d << 1;
      4'b0001: f_shift = d << 2;
      4'b0010: f_shift = d << 4;
      4'b0011: f_shift = d << 8;
      4'b0100: f_shift = d >> 1;
      4'b0101: f_shift = d >> 2;
      4'b0110: f_shift = d >> 4;
      4'b0111: f_shift = d >> 8;
      default: f_shift = d;
    endcase
  endfunction

  // Functional equivalence and no-X on output when inputs known
  assert property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl}) |-> (Q == f_shift(D,shift_ctrl) && !$isunknown(Q))
  );

  // Decode coverage (each implemented op + default range)
  genvar i;
  generate for (i=0; i<8; i++) begin : g_cov_bs
    cover property (disable iff (!rst_n) !$isunknown({D,shift_ctrl}) && shift_ctrl == i[3:0]);
  end endgenerate
  cover property (disable iff (!rst_n) !$isunknown({D,shift_ctrl}) && (shift_ctrl inside {[4'h8:4'hF]}));
endmodule

// SVA for alu_32bit
module alu_32bit_sva(
  input logic               clk,
  input logic               rst_n,
  input logic [31:0]        a,
  input logic [31:0]        b,
  input logic [3:0]         ctrl,
  input logic [31:0]        result
);
  default clocking cb @(posedge clk); endclocking

  function automatic [31:0] f_alu(input [31:0] aa, input [31:0] bb, input [3:0] c);
    unique case (c)
      4'b0000: f_alu = aa + bb;
      4'b0001: f_alu = aa - bb;
      4'b0010: f_alu = aa & bb;
      4'b0011: f_alu = aa | bb;
      4'b0100: f_alu = aa ^ bb;
      default: f_alu = aa;
    endcase
  endfunction

  // Functional equivalence and no-X on output when inputs known
  assert property (disable iff (!rst_n)
    !$isunknown({a,b,ctrl}) |-> (result == f_alu(a,b,ctrl) && !$isunknown(result))
  );

  // Operation coverage (implemented ops + default range)
  genvar j;
  generate for (j=0; j<5; j++) begin : g_cov_alu
    cover property (disable iff (!rst_n) !$isunknown({a,b,ctrl}) && ctrl == j[3:0]);
  end endgenerate
  cover property (disable iff (!rst_n) !$isunknown({a,b,ctrl}) && (ctrl inside {[4'h5:4'hF]}));

  // Interesting arithmetic scenarios
  cover property (disable iff (!rst_n) !$isunknown({a,b}) && ctrl==4'b0000 && (f_alu(a,b,ctrl) < a)); // unsigned add overflow
  cover property (disable iff (!rst_n) !$isunknown({a,b}) && ctrl==4'b0001 && (f_alu(a,b,ctrl) > a)); // unsigned sub underflow
endmodule

// SVA for top_module (end-to-end)
module top_module_sva(
  input logic               clk,
  input logic               rst_n,
  input logic [15:0]        D,
  input logic [3:0]         shift_ctrl,
  input logic [31:0]        a,
  input logic [31:0]        b,
  input logic [3:0]         alu_ctrl,
  input logic [31:0]        result
);
  default clocking cb @(posedge clk); endclocking

  function automatic [15:0] f_shift(input [15:0] d, input [3:0] c);
    unique case (c)
      4'b0000: f_shift = d << 1;
      4'b0001: f_shift = d << 2;
      4'b0010: f_shift = d << 4;
      4'b0011: f_shift = d << 8;
      4'b0100: f_shift = d >> 1;
      4'b0101: f_shift = d >> 2;
      4'b0110: f_shift = d >> 4;
      4'b0111: f_shift = d >> 8;
      default: f_shift = d;
    endcase
  endfunction

  function automatic [31:0] f_alu(input [31:0] aa, input [31:0] bb, input [3:0] c);
    unique case (c)
      4'b0000: f_alu = aa + bb;
      4'b0001: f_alu = aa - bb;
      4'b0010: f_alu = aa & bb;
      4'b0011: f_alu = aa | bb;
      4'b0100: f_alu = aa ^ bb;
      default: f_alu = aa;
    endcase
  endfunction

  function automatic [31:0] f_top(
    input [15:0] d, input [3:0] sc,
    input [31:0] aa, input [31:0] bb, input [3:0] ac
  );
    automatic logic [15:0] sd = f_shift(d,sc);
    automatic logic [31:0] ar = f_alu(aa,bb,ac);
    f_top = ar | {16'b0, sd};
  endfunction

  // End-to-end functional equivalence and no-X on output when inputs known
  assert property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl,a,b,alu_ctrl}) |-> (result == f_top(D,shift_ctrl,a,b,alu_ctrl) && !$isunknown(result))
  );

  // Sanity: upper/lower OR structure preserved
  assert property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl,a,b,alu_ctrl}) |->
      (result[31:16] == f_alu(a,b,alu_ctrl)[31:16]) &&
      (result[15:0]  == (f_alu(a,b,alu_ctrl)[15:0] | f_shift(D,shift_ctrl)))
  );

  // Coverage: both defaults simultaneously exercised
  cover property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl,a,b,alu_ctrl}) &&
    (shift_ctrl inside {[4'h8:4'hF]}) && (alu_ctrl inside {[4'h5:4'hF]})
  );

  // Coverage: OR effect changes lower 16b due to shifter bits only
  cover property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl,a,b,alu_ctrl}) &&
    ((f_shift(D,shift_ctrl) & ~f_alu(a,b,alu_ctrl)[15:0]) != 16'b0)
  );

  // Coverage: OR effect masked by ALU lower bits already 1s
  cover property (disable iff (!rst_n)
    !$isunknown({D,shift_ctrl,a,b,alu_ctrl}) &&
    ((~f_shift(D,shift_ctrl) & f_alu(a,b,alu_ctrl)[15:0]) != 16'b0)
  );
endmodule

// Example binds (connect clk/rst from your TB)
bind barrel_shifter_16bit barrel_shifter_16bit_sva u_bs_sva(
  .clk(tb_clk), .rst_n(tb_rst_n), .D(D), .shift_ctrl(shift_ctrl), .Q(Q)
);
bind alu_32bit alu_32bit_sva u_alu_sva(
  .clk(tb_clk), .rst_n(tb_rst_n), .a(a), .b(b), .ctrl(ctrl), .result(result)
);
bind top_module top_module_sva u_top_sva(
  .clk(tb_clk), .rst_n(tb_rst_n),
  .D(D), .shift_ctrl(shift_ctrl), .a(a), .b(b), .alu_ctrl(alu_ctrl), .result(result)
);

// SVA for binary_counter
module binary_counter_sva (
  input clk,
  input reset,       // active-low in RTL
  input load,
  input [3:0] load_value,
  input [3:0] q,
  input carry_out,
  input led
);
  default clocking cb @ (posedge clk); endclocking

  // Reset behavior (active-low): while reset=0, q must be 5
  assert property (!reset |-> q == 4'h5);

  // Load takes effect next cycle if still out of reset
  assert property ( (reset && load) ##1 reset |-> (q == $past(load_value)) );

  // Increment/rollover when idle (no load) for two consecutive cycles
  assert property ( (reset && !load) ##1 (reset && !load)
                    |-> (q == (($past(q,1)==4'hF) ? 4'h0 : $past(q,1)+1)) );

  // Output relationships
  assert property ( carry_out == (q == 4'hF) );
  assert property ( led == carry_out );

  // Coverage
  cover property ( !reset && q == 4'h5 ); // reset value observed
  cover property ( (reset && load) ##1 (reset && q == $past(load_value)) ); // load used
  cover property ( (reset && !load && q==4'hE)
                   ##1 (reset && !load && q==4'hF)
                   ##1 (reset && !load && q==4'h0) ); // rollover
  cover property ( q==4'hF && carry_out && led ); // carry/LED high at 15
endmodule

bind binary_counter binary_counter_sva bcounter_sva (.*);

