module mux4to1 (
    output reg [7:0] out,
    input [7:0] in0,
    input [7:0] in1,
    input [7:0] in2,
    input [7:0] in3,
    input sel0,
    input sel1
);

    // Local signals
    reg [7:0] selected;

    // Select the input based on the select lines
    always @*
    begin
        case ({sel1, sel0})
            2'b00: selected = in0;
            2'b01: selected = in1;
            2'b10: selected = in2;
            2'b11: selected = in3;
        endcase
    end

    // Assign the selected input to the output
    always @*
    begin
        out = selected;
    end

endmodule

sva_code:
// SVA checker for mux4to1. Bind this to the DUT.
// Focus: correctness, X/Z guarding on selects, and functional coverage.

module mux4to1_sva
(
  input  logic [7:0] out,
  input  logic [7:0] in0,
  input  logic [7:0] in1,
  input  logic [7:0] in2,
  input  logic [7:0] in3,
  input  logic       sel0,
  input  logic       sel1
);

  // Guard: selects must be 0/1 only (no X/Z)
  always @* begin
    assert (!$isunknown({sel1, sel0}))
      else $error("mux4to1: sel has X/Z: sel1=%b sel0=%b", sel1, sel0);
  end

  // Functional equivalence to a 4:1 mux at all times
  always @* begin
    logic [7:0] exp;
    exp = sel1 ? (sel0 ? in3 : in2)
               : (sel0 ? in1 : in0);
    assert (out === exp)
      else $error("mux4to1: mismatch sel=%b%b exp=0x%0h got=0x%0h", sel1, sel0, exp, out);
  end

  // Basic functional coverage: hit all select paths with correct output
  always @* begin
    cover (!$isunknown({sel1, sel0}) && {sel1, sel0}==2'b00 && out === in0);
    cover (!$isunknown({sel1, sel0}) && {sel1, sel0}==2'b01 && out === in1);
    cover (!$isunknown({sel1, sel0}) && {sel1, sel0}==2'b10 && out === in2);
    cover (!$isunknown({sel1, sel0}) && {sel1, sel0}==2'b11 && out === in3);
  end

  // Transition coverage across all select states (on any select edge)
  sequence s00; !$isunknown({sel1,sel0}) && {sel1,sel0}==2'b00; endsequence
  sequence s01; !$isunknown({sel1,sel0}) && {sel1,sel0}==2'b01; endsequence
  sequence s10; !$isunknown({sel1,sel0}) && {sel1,sel0}==2'b10; endsequence
  sequence s11; !$isunknown({sel1,sel0}) && {sel1,sel0}==2'b11; endsequence

  cover property (@(posedge sel0 or negedge sel0 or posedge sel1 or negedge sel1)
                  s00 ##1 s01 ##1 s10 ##1 s11);

endmodule

// Bind into the DUT
bind mux4to1 mux4to1_sva mux4to1_sva_i (
  .out(out), .in0(in0), .in1(in1), .in2(in2), .in3(in3), .sel0(sel0), .sel1(sel1)
);

// SVA for up_down_counter
module up_down_counter_sva (
  input logic        clk,
  input logic        reset,
  input logic        enable,
  input logic        up_down,
  input logic [3:0]  count
);

  default clocking cb @(posedge clk); endclocking

  // Synchronous reset: if reset is 1 on a clock, next cycle count must be 0
  a_sync_reset_next: assert property (reset |=> count == 4'h0);

  // All other properties disabled during reset
  default disable iff (reset);

  // No X on key signals (during active operation)
  a_no_x_count: assert property (!$isunknown(count));
  a_no_x_ctrl:  assert property (!$isunknown({enable, up_down}));

  // Hold when disabled
  a_hold_when_disabled: assert property (!enable |=> count == $past(count));

  // Enable causes a change (never hold when enabled)
  a_enable_changes: assert property (enable |=> count != $past(count));

  // Any change (not due to reset) must be because enable was 1
  a_change_requires_enable: assert property ((count != $past(count)) && !$past(reset) |-> $past(enable));

  // Up-counting (no wrap)
  a_up_incr: assert property (enable && up_down && count != 4'hF |=> count == $past(count) + 4'd1);
  // Up-counting (wrap 15 -> 0)
  a_up_wrap: assert property (enable && up_down && count == 4'hF |=> count == 4'h0);

  // Down-counting (no wrap)
  a_down_decr: assert property (enable && !up_down && count != 4'h0 |=> count == $past(count) - 4'd1);
  // Down-counting (wrap 0 -> 15)
  a_down_wrap: assert property (enable && !up_down && count == 4'h0 |=> count == 4'hF);

  // Coverage
  c_reset:         cover property (reset ##1 (count == 4'h0));
  c_hold:          cover property (!enable ##1 count == $past(count));
  c_up_step:       cover property (enable && up_down && count inside {[4'h0:4'hE]} ##1 count == $past(count) + 1);
  c_down_step:     cover property (enable && !up_down && count inside {[4'h1:4'hF]} ##1 count == $past(count) - 1);
  c_up_wrap:       cover property (enable && up_down && count == 4'hF ##1 count == 4'h0);
  c_down_wrap:     cover property (enable && !up_down && count == 4'h0 ##1 count == 4'hF);

endmodule

// Bind into DUT
bind up_down_counter up_down_counter_sva sva_i (
  .clk    (clk),
  .reset  (reset),
  .enable (enable),
  .up_down(up_down),
  .count  (count)
);

verilog_code:
module AdderSubtractor (
    input [3:0] A,
    input [3:0] B,
    input Sub,
    output [3:0] S,
    output Cout
);

wire [3:0] A_comp;
wire [3:0] B_comp;

assign A_comp = ~A + 1;
assign B_comp = ~B + 1;

wire [4:0] temp_sum;
assign temp_sum = (Sub == 1) ? A + B_comp : A + B;

assign Cout = (Sub == 1) ? (A >= B) : (temp_sum[4] == 1);
assign S = (Sub == 1) ? temp_sum : temp_sum[3:0];

endmodule

sva_code:
// SVA bind module for AdderSubtractor
module AdderSubtractor_sva (
  input  logic [3:0] A,
  input  logic [3:0] B,
  input  logic       Sub,
  input  logic [3:0] S,
  input  logic       Cout,
  input  logic [3:0] A_comp,
  input  logic [3:0] B_comp,
  input  logic [4:0] temp_sum
);

  // helper lets
  let add_sum = {1'b0, A} + {1'b0, B};
  let sub_sum = {1'b0, A} + {1'b0, (~B + 4'd1)};
  let exp_sum = Sub ? sub_sum : add_sum;

  // no X/Z on outputs when inputs are known
  assert property ( $isunknown({A,B,Sub}) || !$isunknown({S,Cout,temp_sum}) );

  // internal two's-complement generators
  assert property ( A_comp == (~A + 4'd1) );
  assert property ( B_comp == (~B + 4'd1) );

  // temp_sum correct for add/sub selection
  assert property ( temp_sum == exp_sum );

  // S is always low 4 bits of temp_sum (catch truncation/width issues)
  assert property ( S == temp_sum[3:0] );

  // Cout correctness
  assert property ( (!Sub) || (Cout == (A >= B)) );     // subtraction: Cout == no-borrow
  assert property ( ( Sub) || (Cout == temp_sum[4]) );  // addition: Cout == carry out
  // cross-check subtraction carry-out equals no-borrow
  assert property ( (!Sub) || (sub_sum[4] == (A >= B)) );

  // functional equivalence
  assert property ( S == exp_sum[3:0] );
  assert property ( (!Sub) || ((S + B) & 4'hF) == (A & 4'hF) ); // modulo-16 identity for subtract

  // concise coverage
  cover property ( Sub == 0 );                           // add mode seen
  cover property ( Sub == 1 );                           // sub mode seen
  cover property ( (Sub==0) && (temp_sum[4]==0) );       // add, no carry
  cover property ( (Sub==0) && (temp_sum[4]==1) );       // add, carry
  cover property ( (Sub==1) && (A >= B) );               // sub, no borrow
  cover property ( (Sub==1) && (A <  B) );               // sub, borrow
  cover property ( (Sub==1) && (A == B) );               // sub, equality
  cover property ( (A==4'h0) && (B==4'h0) );             // boundary: zeros
  cover property ( (A==4'hF) && (B==4'hF) && (Sub==0) ); // boundary: max+max
  cover property ( (A==4'h0) && (B==4'hF) && (Sub==1) ); // boundary: max borrow

endmodule

// Bind into DUT (accesses internal wires via port connections)
bind AdderSubtractor AdderSubtractor_sva sva (
  .A(A),
  .B(B),
  .Sub(Sub),
  .S(S),
  .Cout(Cout),
  .A_comp(A_comp),
  .B_comp(B_comp),
  .temp_sum(temp_sum)
);

