  // Compact coverage: hit every legal input->output mapping observed
  genvar i;
  generate
    for (i = 0; i < 64; i++) begin : COV_I
      always @(stage1_input or stage1_output)
        cover (stage1_input == i && stage1_output == LUT[i]);
    end
  endgenerate

