                    |-> (! $isunknown(and0_out_Y) &&
                         (and0_out_Y == (nand0_out & nand1_out & nand2_out))) )
    else $error("and0_out_Y mismatch");

  assert property ( !$isunknown(and0_out_Y)
                    |-> (! $isunknown(Y) && (Y == and0_out_Y)) )
    else $error("buf/Y mismatch");

