  assert property ( all_known6({A1,A2,B1,B2,C1,C2}) &&
                    ((A1 & A2) || (B1 & B2) || (C1 & C2))
                    |-> (Y == 1'b0) )
    else $error("Y should be 0 when any pair is 11");

  // Coverage
  cover property ( all_known6({A1,A2,B1,B2,C1,C2}) && (Y == 1) );
  cover property ( all_known6({A1,A2,B1,B2,C1,C2}) && (Y == 0) );

