module comparator (
    input [7:0] A,
    input [7:0] B,
    output reg EQ,
    output reg GT,
    input clk
);

reg [7:0] A_reg, B_reg;
reg [2:0] stage;

always @(posedge clk) begin
    case(stage)
        0: begin
            A_reg <= A;
            B_reg <= B;
            stage <= 1;
        end
        1: begin
            if(A_reg == B_reg) begin
                EQ <= 1;
                GT <= 0;
            end
            else if(A_reg > B_reg) begin
                EQ <= 0;
                GT <= 1;
            end
            else begin
                EQ <= 0;
                GT <= 0;
            end
            stage <= 2;
        end
        2: begin
            EQ <= 0;
            GT <= 0;
            stage <= 0;
        end
    endcase
end

endmodule

sva_code:
// SVA for comparator — bind into DUT to check/cover pipeline, capture, compare, and outputs

module comparator_sva (
  input logic        clk,
  input logic [7:0]  A, B,
  input logic        EQ, GT,
  input logic [7:0]  A_reg, B_reg,
  input logic [2:0]  stage
);

  default clocking cb @(posedge clk); endclocking

  // $past guard
  logic past_valid;
  always_ff @(posedge clk) past_valid <= 1'b1;

  // State validity and progression
  assert property (cb, ! $isunknown(stage) |-> stage inside {3'd0,3'd1,3'd2});
  assert property (cb, disable iff ($isunknown(stage)) (stage==3'd0) |=> stage==3'd1);
  assert property (cb, disable iff ($isunknown(stage)) (stage==3'd1) |=> stage==3'd2);
  assert property (cb, disable iff ($isunknown(stage)) (stage==3'd2) |=> stage==3'd0);

  // Register capture correctness (stage0 captures inputs for use in stage1)
  assert property (cb, disable iff (!past_valid || $isunknown(stage))
                   (stage==3'd0) |=> (stage==3'd1 && A_reg==$past(A) && B_reg==$past(B)));

  // A_reg/B_reg may only change when stage was 0
  assert property (cb, disable iff (!past_valid)
                   (A_reg != $past(A_reg)) |-> $past(stage==3'd0));
  assert property (cb, disable iff (!past_valid)
                   (B_reg != $past(B_reg)) |-> $past(stage==3'd0));

  // Outputs mapping: results appear one cycle after stage1 (during stage2 sample)
  assert property (cb, disable iff ($isunknown(stage))
                   (stage==3'd1) |=> ((A_reg==B_reg) -> ( EQ && !GT)) &&
                                      ((A_reg> B_reg) -> (!EQ &&  GT)) &&
                                      ((A_reg< B_reg) -> (!EQ && !GT)));

  // Outputs are 0 in stage0 and stage1; any nonzero only during stage2
  assert property (cb, disable iff ($isunknown(stage))
                   (stage inside {3'd0,3'd1}) |-> (!EQ && !GT));
  assert property (cb, disable iff ($isunknown(stage))
                   (EQ || GT) |-> stage==3'd2);

  // Outputs cleared after stage2
  assert property (cb, disable iff ($isunknown(stage)) (stage==3'd2) |=> (!EQ && !GT));

  // Output mutual exclusion and no X when stage known
  assert property (cb, !(EQ && GT));
  assert property (cb, ! $isunknown(stage) |-> ! $isunknown({EQ,GT}));

  // Output changes only due to stage1 or stage2 assignments
  assert property (cb, disable iff (!past_valid)
                   ((EQ!=$past(EQ)) || (GT!=$past(GT))) |-> $past(stage inside {3'd1,3'd2}));

  // One-cycle pulses on EQ/GT when they rise
  assert property (cb, disable iff (!past_valid) $rose(EQ) |-> $past(stage==3'd1) ##1 !EQ);
  assert property (cb, disable iff (!past_valid) $rose(GT) |-> $past(stage==3'd1) ##1 !GT);

  // Coverage
  cover property (cb (stage==3'd0) ##1 (stage==3'd1) ##1 (stage==3'd2) ##1 (stage==3'd0));
  cover property (cb (stage==3'd1 && A_reg==B_reg) ##1 (stage==3'd2 &&  EQ && !GT));
  cover property (cb (stage==3'd1 && A_reg> B_reg) ##1 (stage==3'd2 && !EQ &&  GT));
  cover property (cb (stage==3'd1 && A_reg< B_reg) ##1 (stage==3'd2 && !EQ && !GT));
  cover property (cb $rose(EQ));
  cover property (cb $rose(GT));

endmodule

// Bind into DUT (connects to internals A_reg/B_reg/stage)
bind comparator comparator_sva u_comparator_sva (.*);

// SVA for data_converter
// Bind this module to the DUT and connect a sampling clock from the TB.
module data_converter_sva (
  input logic        clk,
  input logic [15:0] data_in,
  input logic [3:0]  data_out
);
  default clocking cb @(posedge clk); endclocking

  // Helpers that are 4-state aware
  function automatic bit any_known1_low (input logic [3:0] a);
    return (a[0]===1'b1) || (a[1]===1'b1) || (a[2]===1'b1) || (a[3]===1'b1);
  endfunction
  function automatic bit all_known0_low (input logic [3:0] a);
    return (a[0]===1'b0) && (a[1]===1'b0) && (a[2]===1'b0) && (a[3]===1'b0);
  endfunction

  // Core functional equivalence (when low nibble is known)
  assert property ( !$isunknown(data_in[3:0])
                    |-> ( data_out == ((data_in[3:0] != 4'h0) ? 4'hF : data_in[15:12]) ) );

  // If any low-nibble bit is definitively 1, output must be 4'hF
  assert property ( any_known1_low(data_in[3:0]) |-> (data_out == 4'hF) );

  // If low nibble is definitively all 0, output mirrors the high nibble (and is known)
  assert property ( all_known0_low(data_in[3:0]) |-> ((data_out === data_in[15:12]) && !$isunknown(data_out)) );

  // Output should never go X/Z
  assert property ( !$isunknown(data_out) );

  // X-optimism guard on control nibble
  assert property ( !$isunknown(data_in[3:0]) )
    else $warning("data_converter: data_in[3:0] has X/Z; 'if (data_in[3:0]!=0)' is X-optimistic");

  // Combinational stability: if input holds, output holds
  assert property ( $stable(data_in) |-> $stable(data_out) );

  // Coverage
  cover property ( any_known1_low(data_in[3:0]) && data_out == 4'hF );            // took '!=0' branch
  cover property ( all_known0_low(data_in[3:0]) && data_out === data_in[15:12] ); // took '==0' branch
  cover property ( all_known0_low(data_in[3:0]) ##1 any_known1_low(data_in[3:0]) && data_out == 4'hF ); // 0->non0
  cover property ( any_known1_low(data_in[3:0]) ##1 all_known0_low(data_in[3:0]) );                      // non0->0
endmodule

