module up_counter(
    input clk, // clock signal
    input reset, // reset signal
    output reg [2:0] count // output count
);

    always @(posedge clk) begin
        if (reset) begin // reset counter to 0
            count <= 3'b0;
        end else begin // increment counter
            count <= count + 1;
        end
    end

endmodule

sva_code:
// SVA for up_counter
module up_counter_sva (
  input logic        clk,
  input logic        reset,
  input logic [2:0]  count
);
  default clocking @(posedge clk); endclocking

  // Sanity: no X/Z on key signals at sampling
  assert property (!$isunknown({reset, count}));

  // Golden next-state relation (covers reset and increment, incl. wrap)
  assert property ($past_valid |-> count == ($past(reset) ? 3'd0 : $past(count) + 3'd1));

  // While reset is held, counter output stays 0 (after first cycle of reset)
  assert property (reset && $past(reset) |-> count == 3'd0);

  // Cover: single-cycle reset pulse forces next count to 0
  cover property ($rose(reset) ##1 (count == 3'd0));

  // Cover: wrap-around 7 -> 0 with no reset
  cover property ($past_valid && !$past(reset) && !reset && $past(count) == 3'd7 && count == 3'd0);

  // Cover: full 8-count cycle after reset deassertion
  sequence step; !reset && (count == $past(count) + 3'd1); endsequence
  cover property ($fell(reset) ##1 step[*7] ##1 (!reset && count == 3'd0));
endmodule

// Bind into all instances of up_counter
bind up_counter up_counter_sva u_up_counter_sva (.clk(clk), .reset(reset), .count(count));

// SVA for up_down_counter
module up_down_counter_sva (
  input logic clk,
  input logic reset,
  input logic control,
  input logic [3:0] count
);
  default clocking cb @(posedge clk); endclocking

  // Helpers (mod-16 arithmetic)
  function automatic [3:0] inc4(input logic [3:0] a); inc4 = a + 4'd1; endfunction
  function automatic [3:0] dec4(input logic [3:0] a); dec4 = a - 4'd1; endfunction

  // Sanity/knownness
  assert property (!$isunknown({reset, control}));
  assert property (!reset |-> !$isunknown(count)));

  // Synchronous reset
  assert property (reset |-> count == 4'h0);

  // Next-state correctness (single concise check)
  assert property (disable iff (reset)
                   1'b1 |=> count == (control ? inc4($past(count))
                                              : dec4($past(count))));

  // Must change every active cycle
  assert property (disable iff (reset) 1'b1 |=> count != $past(count));

  // Explicit wrap checks
  assert property (disable iff (reset) (control && $past(count)==4'hF) |=> count==4'h0);
  assert property (disable iff (reset) (!control && $past(count)==4'h0) |=> count==4'hF);

  // Coverage
  cover property (reset);
  cover property (disable iff (reset) control ##1 !control);                 // dir change
  cover property (disable iff (reset) (control && $past(count)==4'hF) |=> count==4'h0); // up-wrap
  cover property (disable iff (reset) (!control && $past(count)==4'h0) |=> count==4'hF); // down-wrap
endmodule

bind up_down_counter up_down_counter_sva sva_i (.*);

