module complement_module (
    input [3:0] in_vec,
    input sel_comp,
    output [3:0] outv,
    output [3:0] complement
);

    assign outv = in_vec;

    assign complement = (sel_comp == 1) ? ~in_vec + 1 : ~in_vec;

endmodule

sva_code:
// SVA checker for complement_module
module complement_module_sva (
  input  logic [3:0] in_vec,
  input  logic       sel_comp,
  input  logic [3:0] outv,
  input  logic [3:0] complement
);

  // Functional correctness (delta-cycle settle with ##0)
  property p_func_direct;
    @(in_vec or sel_comp)
      !$isunknown({in_vec, sel_comp})
      |-> ##0 ( outv == in_vec
             && complement == (sel_comp ? (~in_vec + 4'b0001) : ~in_vec) );
  endproperty
  assert property (p_func_direct)
    else $error("Functional mismatch: outv/complement incorrect for inputs");

  // Independent arithmetic invariants
  property p_sum_mode0;
    @(in_vec or sel_comp)
      (!$isunknown({in_vec, sel_comp}) && !sel_comp)
      |-> ##0 ((in_vec + complement) == 4'hF);
  endproperty
  assert property (p_sum_mode0)
    else $error("Mode0: in_vec + complement != 0xF");

  property p_sum_mode1;
    @(in_vec or sel_comp)
      (!$isunknown({in_vec, sel_comp}) && sel_comp)
      |-> ##0 ((in_vec + complement) == 4'h0);
  endproperty
  assert property (p_sum_mode1)
    else $error("Mode1: in_vec + complement != 0x0 (mod 16)");

  // No X/Z on outputs when inputs are known
  property p_no_x_out_when_inputs_known;
    @(in_vec or sel_comp)
      !$isunknown({in_vec, sel_comp})
      |-> ##0 (! $isunknown({outv, complement}));
  endproperty
  assert property (p_no_x_out_when_inputs_known)
    else $error("Outputs contain X/Z while inputs are known");

  // Coverage
  // - Full cross coverage of sel_comp and all in_vec values
  covergroup cg_complements @(in_vec or sel_comp);
    c_sel: coverpoint sel_comp { bins b0 = {0}; bins b1 = {1}; }
    c_in : coverpoint in_vec   { bins all[] = {[4'h0:4'hF]}; }
    cross c_sel, c_in;
  endgroup
  cg_complements cg_inst = new();

  // - Toggle coverage on sel_comp
  cover property (@(sel_comp) (sel_comp==0) ##1 (sel_comp==1));
  cover property (@(sel_comp) (sel_comp==1) ##1 (sel_comp==0));

  // - Corner value coverage with functional result observed
  cover property (@(in_vec or sel_comp)
                  (!sel_comp && in_vec inside {4'h0,4'hF}) ##0 ((in_vec + complement)==4'hF));
  cover property (@(in_vec or sel_comp)
                  ( sel_comp && in_vec inside {4'h0,4'h1,4'h8,4'hF}) ##0 ((in_vec + complement)==4'h0));

endmodule

// Bind into the DUT
bind complement_module complement_module_sva sva_i (
  .in_vec(in_vec),
  .sel_comp(sel_comp),
  .outv(outv),
  .complement(complement)
);

verilog_code:
module state_machine (
    input clk,
    input rst_,
    output reg [2:0] state_r
);

    // Define the states as enumerated types
    parameter [2:0] IDLE = 3'b000;
    parameter [2:0] SEND = 3'b001;
    parameter [2:0] WAIT1 = 3'b010;
    parameter [2:0] UPDATE1 = 3'b011;
    parameter [2:0] WAIT2 = 3'b100;
    parameter [2:0] UPDATE2 = 3'b101;

    // Define the next state variable
    reg [2:0] next_state;

    // Define the state transition logic
    always @(*) begin
        case (state_r)
            IDLE: next_state = SEND;
            SEND: next_state = WAIT1;
            WAIT1: next_state = UPDATE1;
            UPDATE1: next_state = WAIT2;
            WAIT2: next_state = UPDATE2;
            UPDATE2: next_state = IDLE;
            default: next_state = IDLE;
        endcase
    end

    // Define the state update logic
    always @(posedge clk or negedge rst_) begin
        if (~rst_) begin
            state_r <= IDLE;
        end else begin
            state_r <= next_state;
        end
    end

endmodule

sva_code:
// SVA checker for state_machine
module sm_sva
  #(parameter logic [2:0] IDLE    = 3'b000,
                          SEND    = 3'b001,
                          WAIT1   = 3'b010,
                          UPDATE1 = 3'b011,
                          WAIT2   = 3'b100,
                          UPDATE2 = 3'b101)
(
  input  logic        clk,
  input  logic        rst_,
  input  logic [2:0]  state_r
);

  function automatic bit legal_state (logic [2:0] s);
    case (s)
      IDLE, SEND, WAIT1, UPDATE1, WAIT2, UPDATE2: return 1'b1;
      default: return 1'b0;
    endcase
  endfunction

  // Sanity
  assert property (@(posedge clk) !$isunknown(rst_));
  assert property (@(posedge clk) disable iff (!rst_) !$isunknown(state_r));
  assert property (@(posedge clk) disable iff (!rst_) legal_state(state_r));

  // Reset behavior
  assert property (@(posedge clk) (!rst_) |-> (state_r == IDLE));
  assert property (@(posedge clk) $fell(rst_) |=> (state_r == IDLE));
  assert property (@(posedge clk) $rose(rst_) |=> (state_r == IDLE) ##1 (state_r == SEND));

  // One-step transition helper
  property p_step (logic [2:0] from, logic [2:0] to);
    @(posedge clk) disable iff (!rst_) (state_r == from) |=> (state_r == to);
  endproperty

  // Legal transitions
  assert property (p_step(IDLE,    SEND));
  assert property (p_step(SEND,    WAIT1));
  assert property (p_step(WAIT1,   UPDATE1));
  assert property (p_step(UPDATE1, WAIT2));
  assert property (p_step(WAIT2,   UPDATE2));
  assert property (p_step(UPDATE2, IDLE));

  // Recovery from illegal encodings (should be vacuous)
  assert property (@(posedge clk) disable iff (!rst_)
                   (!legal_state(state_r)) |=> (state_r == IDLE));

  // End-to-end 6-step cycle from IDLE
  assert property (@(posedge clk) disable iff (!rst_)
                   (state_r == IDLE)
                   |-> ##1 (state_r == SEND)
                   ##1 (state_r == WAIT1)
                   ##1 (state_r == UPDATE1)
                   ##1 (state_r == WAIT2)
                   ##1 (state_r == UPDATE2)
                   ##1 (state_r == IDLE));

  // Coverage
  cover property (@(posedge clk) disable iff (!rst_)
                  (state_r == IDLE)
                  ##1 (state_r == SEND)
                  ##1 (state_r == WAIT1)
                  ##1 (state_r == UPDATE1)
                  ##1 (state_r == WAIT2)
                  ##1 (state_r == UPDATE2)
                  ##1 (state_r == IDLE));

  cover property (@(posedge clk) disable iff (!rst_) state_r == IDLE);
  cover property (@(posedge clk) disable iff (!rst_) state_r == SEND);
  cover property (@(posedge clk) disable iff (!rst_) state_r == WAIT1);
  cover property (@(posedge clk) disable iff (!rst_) state_r == UPDATE1);
  cover property (@(posedge clk) disable iff (!rst_) state_r == WAIT2);
  cover property (@(posedge clk) disable iff (!rst_) state_r == UPDATE2);

endmodule

// Bind into the DUT
bind state_machine sm_sva u_sm_sva (.*);

verilog_code:
module shift_register (
    input CLK,
    input LOAD,
    input [3:0] DATA,
    output reg [3:0] Q
);

reg [3:0] reg_out;

always @(posedge CLK) begin
    if (LOAD) begin
        reg_out <= DATA;
    end else begin
        reg_out <= {reg_out[2:0], 1'b0};
    end
end

always @(*) begin
    Q = reg_out;
end

endmodule

sva_code:
// SVA checker for shift_register
module shift_register_sva #(
  parameter int WIDTH = 4
)(
  input  logic               CLK,
  input  logic               LOAD,
  input  logic [WIDTH-1:0]   DATA,
  input  logic [WIDTH-1:0]   Q,
  input  logic [WIDTH-1:0]   reg_out
);

  default clocking cb @(posedge CLK); endclocking

  // Guard for $past()
  logic past_valid;
  initial past_valid = 1'b0;
  always @(posedge CLK) past_valid <= 1'b1;

  // Q mirrors internal reg_out (observability)
  assert property (cb Q === reg_out)
    else $error("Q must mirror reg_out");

  // Exact next-state function (one concise assertion covers both branches)
  assert property (cb past_valid |-> Q == ($past(LOAD) ? $past(DATA)
                                                      : { $past(Q)[WIDTH-2:0], 1'b0 }))
    else $error("Next-state mismatch: LOAD vs shift behavior");

  // After WIDTH consecutive shifts (no LOAD), register must flush to zero
  sequence no_load_width; !LOAD[*WIDTH]; endsequence
  assert property (cb no_load_width |=> Q == '0)
    else $error("Did not flush to zero after WIDTH shifts");

  // Coverage
  cover property (cb LOAD);                         // took load path
  cover property (cb !LOAD);                        // took shift path
  cover property (cb LOAD ##1 !LOAD);               // load then shift
  cover property (cb LOAD[*2]);                     // back-to-back loads
  cover property (cb LOAD ##1 !LOAD[*WIDTH] ##1 Q == '0); // load then flush to zero
  cover property (cb (LOAD && DATA == {{(WIDTH-1){1'b0}},1'b1})
                      ##1 !LOAD[* (WIDTH-1) ] ##1
