// SVA for up_counter
module up_counter_sva #(parameter int SIZE=4)
(
  input logic              Clock,
  input logic              Reset,
  input logic              Enable,
  input logic              Load,
  input logic [SIZE-1:0]   Data,
  input logic [SIZE-1:0]   Q
);

  localparam logic [SIZE-1:0] MAX = {SIZE{1'b1}};

  default clocking cb @(posedge Clock); endclocking

  // Asynchronous reset checks (not disabled)
  a_async_reset_zero: assert property (@(posedge Reset) Q == '0);
  a_reset_hold_zero:  assert property (@(posedge Clock) Reset |-> Q == '0);
  a_no_x_rst:         assert property (@(posedge Reset) !$isunknown(Q));

  // Normal operation checks (ignore cycles with Reset=1)
  default disable iff (Reset);

  a_load:  assert property (Load |=> Q == $past(Data,1,Reset));
  a_inc:   assert property ((!Load && Enable) |=> Q == $past(Q,1,Reset) + 1);
  a_hold:  assert property ((!Load && !Enable) |=> Q == $past(Q,1,Reset));
  a_only_changes_on_ops: assert property ($changed(Q) |-> (Load || Enable));
  a_no_x_clk: assert property (!$isunknown(Q));

  // Coverage
  c_reset:  cover property (@(posedge Reset) Q=='0);
  c_load:   cover property (Load |=> Q == $past(Data,1,Reset));
  c_enable: cover property ((!Load && Enable) |=> Q == $past(Q,1,Reset)+1);
  c_hold:   cover property ((!Load && !Enable) |=> Q == $past(Q,1,Reset));
  c_wrap:   cover property ((!Load && Enable && $past(Q,1,Reset)==MAX) |=> Q=='0);
  c_both:   cover property ((Load && Enable) |=> Q == $past(Data,1,Reset));

endmodule

// Bind into DUT
bind up_counter up_counter_sva #(.SIZE(SIZE)) up_counter_sva_i (.*);

// SVA for shift_register
// Focused, high-quality checks + concise coverage

`ifndef SHIFT_REGISTER_SVA
`define SHIFT_REGISTER_SVA

module shift_register_sva(
  input logic clk,
  input logic load,
  input logic serial_in,
  input logic [2:0] out
);

  default clocking cb @(posedge clk); endclocking

  // history valid qualifiers for $past depth
  bit pv1, pv2, pv3;
  initial begin pv1=0; pv2=0; pv3=0; end
  always_ff @(posedge clk) begin
    pv1 <= 1'b1;
    pv2 <= pv1;
    pv3 <= pv2;
  end

  // Sanity: no X/Z on key signals
  assert property (!$isunknown({load, serial_in}))) else $error("X/Z on inputs");
  assert property (!$isunknown(out)) else $error("X/Z on out");

  // Functional correctness
  // On load: out <= zero-extended serial_in
  assert property (disable iff (!pv1) load |=> out == {2'b00, $past(serial_in)})
    else $error("Load behavior mismatch");

  // On shift: out <= {out[1:0], serial_in}
  assert property (disable iff (!pv1) !load |=> out == {$past(out[1:0]), $past(serial_in)})
    else $error("Shift behavior mismatch");

  // After three consecutive shifts, out equals last three serial_in samples
  assert property (disable iff (!pv3) (!load ##1 !load ##1 !load)
                   |=> out == {$past(serial_in,3), $past(serial_in,2), $past(serial_in,1)})
    else $error("3-shift streaming mismatch");

  // Load then one shift: MSB forced 0, lower bits are serial_in history
  assert property (disable iff (!pv2) (load ##1 !load)
                   |=> out == {1'b0, $past(serial_in,2), $past(serial_in,1)})
    else $error("Load->shift compose mismatch");

  // Minimal but meaningful coverage
  cover property (load);
  cover property (!load);
  cover property (!load ##1 !load ##1 !load);     // 3 consecutive shifts
  cover property (load ##1 !load ##1 !load);       // load then shift twice
  cover property (out == 3'b000);
  cover property (out == 3'b111);

endmodule

bind shift_register shift_register_sva sva_i (
  .clk(clk),
  .load(load),
  .serial_in(serial_in),
  .out(out)
);

`endif

