// SVA for dff: concise, full behavioral checks and coverage
module dff_sva #(parameter INIT = 1'b0) (
  input logic Q, D, C, E, R, S
);

  default clocking cb @(posedge C); endclocking

  // Make $past safe
  logic past_valid;
  initial past_valid = 1'b0;
  always @(posedge C) past_valid <= 1'b1;

  // Q must never be X/Z at clock edges
  a_q_known: assert property ( !$isunknown(Q) );

  // Synchronous priority and behavior (use previous-cycle controls)
  a_reset: assert property ( disable iff (!past_valid)
                             !$past(R) |-> (Q == INIT) );

  a_set:   assert property ( disable iff (!past_valid)
                             ($past(R) && !$past(S)) |-> (Q == 1'b1) );

  a_en:    assert property ( disable iff (!past_valid)
                             ($past(R) && $past(S) && $past(E)) |-> (Q == $past(D)) );

  a_hold:  assert property ( disable iff (!past_valid)
                             ($past(R) && $past(S) && !$past(E)) |-> (Q == $past(Q)) );

  // When both R and S are low, reset has priority (explicitly checked)
  a_rs_both_low_pri: assert property ( disable iff (!past_valid)
                                       (!$past(R) && !$past(S)) |-> (Q == INIT) );

  // Q may only change coincident with C posedge (no glitches)
  a_q_only_changes_on_c: assert property (@(posedge Q or negedge Q) $rose(C));

  // Coverage: hit all key behaviors
  c_reset:   cover property ( disable iff (!past_valid)
                              !$past(R) ##1 (Q == INIT) );

  c_set:     cover property ( disable iff (!past_valid)
                              ($past(R) && !$past(S)) ##1 (Q == 1'b1) );

  c_hold:    cover property ( disable iff (!past_valid)
                              ($past(R) && $past(S) && !$past(E)) ##1 (Q == $past(Q)) );

  // Enable-driven 0->1 and 1->0 updates
  c_en_01:   cover property ( disable iff (!past_valid)
                              ($past(R) && $past(S) && $past(E) &&
                               ($past(Q)==1'b0) && ($past(D)==1'b1)) ##1 (Q==1'b1) );

  c_en_10:   cover property ( disable iff (!past_valid)
                              ($past(R) && $past(S) && $past(E) &&
                               ($past(Q)==1'b1) && ($past(D)==1'b0)) ##1 (Q==1'b0) );

  // Both controls low in same cycle (priority exercised)
  c_rs_both_low: cover property ( disable iff (!past_valid)
                                  (!$past(R) && !$past(S)) ##1 (Q == INIT) );

endmodule

// Bind example:
// bind dff dff_sva #(.INIT(INIT)) dff_sva_i (.Q(Q), .D(D), .C(C), .E(E), .R(R), .S(S));

// SVA for sync_resettable_latch
// Concise, high-quality checks and coverage

module sync_resettable_latch_sva #(parameter WIDTH=4)
(
  input logic                 CLK,
  input logic                 EN,
  input logic                 RST,
  input logic [WIDTH-1:0]     D,
  input logic [WIDTH-1:0]     Q
);

  // Clocking and past-valid guard
  default clocking cb @(posedge CLK); endclocking
  logic past_valid;
  always_ff @(posedge CLK) past_valid <= 1'b1;
  default disable iff (!past_valid);

  // Sanity/cleanliness
  a_ctrl_known:       assert property (!$isunknown({EN,RST}));
  a_d_known_when_en:  assert property (EN |-> !$isunknown(D));
  a_q_known:          assert property (!$isunknown(Q));

  // Functional behavior
  a_load:      assert property (EN              |=> Q == $past(D));
  a_reset:     assert property (!EN && RST      |=> Q == '0);
  a_hold:      assert property (!EN && !RST     |=> $stable(Q));
  a_priority:  assert property (EN && RST       |=> Q == $past(D)); // EN wins over RST
  a_change_gated: assert property ($changed(Q)  |-> $past(EN || RST));

  // No glitches between clocks (spot-check at opposite edge)
  a_no_glitch: assert property (@(negedge CLK) $stable(Q));

  // Coverage (all key branches and priority)
  c_load_change:         cover property ( $past(EN && !RST) ##1 (Q == $past(D) && Q != $past(Q)) );
  c_reset_from_nonzero:  cover property ( ($past(!EN && RST) && ($past(Q) != '0)) ##1 (Q == '0) );
  c_hold:                cover property ( $past(!EN && !RST) ##1 (Q == $past(Q)) );
  c_both_high:           cover property ( $past(EN && RST)   ##1 (Q == $past(D)) );

endmodule

bind sync_resettable_latch sync_resettable_latch_sva #(.WIDTH(4))
  u_sva (.CLK(CLK), .EN(EN), .RST(RST), .D(D), .Q(Q));

// SVA for up_down_counter
module up_down_counter_sva (
  input logic        clk,
  input logic        reset,
  input logic        up,
  input logic        down,
  input logic [2:0]  count
);

  default clocking cb @(posedge clk); endclocking

  // Basic sanity
  assert property (cb !$isunknown({reset,up,down,count}));

  // Asynchronous reset: immediate and hold while asserted
  assert property (@(posedge reset) count == 3'd0);
  assert property (cb reset |-> count == 3'd0);

  // Functional next-state checks (ignore cycles touching reset)
  // Up has priority over down (including when both are 1)
  assert property (cb (!reset && !$past(reset) && up)
                   |=> count == (($past(count)==3'd7) ? 3'd0 : $past(count)+3'd1));

  // Down only when up is 0
  assert property (cb (!reset && !$past(reset) && !up && down)
                   |=> count == (($past(count)==3'd0) ? 3'd7 : $past(count)-3'd1));

  // Hold when neither up nor down
  assert property (cb (!reset && !$past(reset) && !up && !down)
                   |=> count == $past(count));

  // Explicitly check both-high behaves like up (priority)
  assert property (cb (!reset && !$past(reset) && up && down)
                   |=> count == (($past(count)==3'd7) ? 3'd0 : $past(count)+3'd1));

  // Coverage: hit all states (out of reset)
  cover property (cb !reset && count==3'd0);
  cover property (cb !reset && count==3'd1);
  cover property (cb !reset && count==3'd2);
  cover property (cb !reset && count==3'd3);
  cover property (cb !reset && count==3'd4);
  cover property (cb !reset && count==3'd5);
  cover property (cb !reset && count==3'd6);
  cover property (cb !reset && count==3'd7);

  // Coverage: key behaviors
  cover property (cb (!reset && !$past(reset) && $past(count)==3'd7 && up) |=> count==3'd0); // up wrap
  cover property (cb (!reset && !$past(reset) && $past(count)==3'd0 && !up && down) |=> count==3'd7); // down wrap
  cover property (cb (!reset && !$past(reset) && !up && !down) |=> count==$past(count)); // idle hold
  cover property (cb (!reset && !$past(reset) && up && down)); // both-high seen

endmodule

// Bind to DUT
bind up_down_counter up_down_counter_sva sva_i (.*);

