module ad_datafmt #(
  parameter DATA_WIDTH = 16,
  parameter DISABLE = 0
) (
  input clk,
  input valid,
  input [(DATA_WIDTH-1):0] data,
  output valid_out,
  output [15:0] data_out,
  input dfmt_enable,
  input dfmt_type,
  input dfmt_se
);

  reg valid_int = 'd0;
  reg [15:0] data_int = 'd0;

  wire type_s;
  wire [15:0] data_out_s;

  generate
    if (DISABLE == 1) begin
      assign valid_out = valid;
      assign data_out = data;
    end else begin
      assign valid_out = valid_int;
      assign data_out = data_int;
    end
  endgenerate

  generate
    if (DATA_WIDTH < 16) begin
      wire signext_s;
      wire sign_s;

      assign signext_s = dfmt_enable & dfmt_se;
      assign sign_s = signext_s & (type_s ^ data[(DATA_WIDTH-1)]);
      assign data_out_s[15:DATA_WIDTH] = {(16-DATA_WIDTH){sign_s}};
    end
  endgenerate

  assign type_s = dfmt_enable & dfmt_type;
  assign data_out_s[(DATA_WIDTH-1)] = type_s ^ data[(DATA_WIDTH-1)];
  assign data_out_s[(DATA_WIDTH-2):0] = data[(DATA_WIDTH-2):0];

  always @(posedge clk) begin
    valid_int <= valid;
    data_int <= data_out_s[15:0];
  end

endmodule

sva_code:
// SVA for ad_datafmt: concise, high-quality checks and key coverage
// Bind as: bind ad_datafmt ad_datafmt_sva #(.DATA_WIDTH(DATA_WIDTH), .DISABLE(DISABLE)) sva_i(.*);

module ad_datafmt_sva #(
  parameter int DATA_WIDTH = 16,
  parameter int DISABLE    = 0
) (ad_datafmt dut);

  // Basic parameter sanity (static)
  initial begin
    assert (DATA_WIDTH >= 1 && DATA_WIDTH <= 16)
      else $error("ad_datafmt: DATA_WIDTH must be 1..16 (got %0d)", DATA_WIDTH);
  end

  default clocking cb @(posedge dut.clk); endclocking

  // Golden model of combinational formatter (16-bit)
  function automatic logic [15:0] fmt16(input logic [DATA_WIDTH-1:0] d,
                                        input logic en, t, se);
    logic type_s, msb, upper;
    logic [15:0] r;
    type_s = en & t;
    msb    = d[DATA_WIDTH-1] ^ type_s;
    r      = '0;
    if (DATA_WIDTH > 1) r[DATA_WIDTH-2:0] = d[DATA_WIDTH-2:0];
    r[DATA_WIDTH-1] = msb;
    if (DATA_WIDTH < 16) begin
      upper = (en & se) & msb;
      r[15:DATA_WIDTH] = {(16-DATA_WIDTH){upper}};
    end
    return r;
  endfunction

  // Behavior checks
  if (DISABLE) begin : g_disable_checks
    // Pure passthrough (combinational) — sampled on clk for SVA
    ap_ps_v: assert property (dut.valid_out == dut.valid)
      else $error("DISABLE: valid_out != valid");
    ap_ps_d: assert property (dut.data_out == { {(16-DATA_WIDTH){1'b0}}, dut.data })
      else $error("DISABLE: data_out != zero-extended data");
  end else begin : g_pipe_checks
    // 1-cycle pipeline
    ap_p_v: assert property (dut.valid_out == $past(dut.valid,1,1'b0))
      else $error("PIPE: valid_out not 1-cycle delayed");
    ap_p_d: assert property (
               dut.data_out ==
               $past(fmt16(dut.data, dut.dfmt_enable, dut.dfmt_type, dut.dfmt_se), 1, 16'h0)
             )
      else $error("PIPE: data_out not equal to formatted $past(data,ctrl)");
  end

  // Key functional coverage
  if (!DISABLE) begin : g_cov
    // Pipeline activity
    cp_v_pipe:    cover property (dut.valid ##1 dut.valid_out);

    // Pass-through mode (dfmt_enable=0)
    cp_passthru:  cover property (!dut.dfmt_enable);

    // Invert MSB only (enable & type, no sign-extend), both MSB polarities
    cp_inv_msb0:  cover property (dut.dfmt_enable && dut.dfmt_type && !dut.dfmt_se && (dut.data[DATA_WIDTH-1]==1'b0));
    cp_inv_msb1:  cover property (dut.dfmt_enable && dut.dfmt_type && !dut.dfmt_se && (dut.data[DATA_WIDTH-1]==1'b1));

    // Sign-extend path exercised for both MSB polarities
    if (DATA_WIDTH < 16) begin
      cp_se_msb0: cover property (dut.dfmt_enable && dut.dfmt_se && (dut.data[DATA_WIDTH-1]==1'b0));
      cp_se_msb1: cover property (dut.dfmt_enable && dut.dfmt_se && (dut.data[DATA_WIDTH-1]==1'b1));
    end
  end else begin : g_cov_disable
    // Passthrough path toggles
    cp_ps_dchg: cover property ($changed(dut.data) |-> $changed(dut.data_out));
    cp_ps_vchg: cover property ($changed(dut.valid) |-> $changed(dut.valid_out));
  end

endmodule

// SVA for shift_register: concise, high-quality checks and coverage
module shift_register_sva (
  input logic        clk,
  input logic        reset,      // async active-high
  input logic        shift,
  input logic        shift_in,
  input logic [7:0]  data_out
);
  default clocking cb @(posedge clk); endclocking

  // Basic sanity/X checks
  ap_inputs_known:   assert property (!$isunknown({reset,shift,shift_in}));
  ap_out_known:      assert property (disable iff (reset) !$isunknown(data_out));

  // Asynchronous reset must drive zeros immediately
  ap_async_reset:    assert property (@(posedge reset) data_out == 8'b0);

  // While reset is sampled high at clk, output is 0 in the same cycle
  ap_sync_reset:     assert property (reset |=> data_out == 8'b0);

  // Core shift behavior (all cycles out of reset):
  // Upper bits move up by one every cycle (independent of shift/shift_in)
  ap_shift_move:     assert property (disable iff (reset)
                                      1'b1 |-> ##1 data_out[7:1] == $past(data_out[6:0]));

  // LSB insert rules
  ap_lsb_zero_ins:   assert property (disable iff (reset)
                                      shift |-> ##1 data_out[0] == 1'b0);

  ap_lsb_data_ins:   assert property (disable iff (reset)
                                      !shift |-> ##1 data_out[0] == $past(shift_in));

  // Optional full-vector equivalence (redundant but strong)
  ap_vec_zero_ins:   assert property (disable iff (reset)
                                      shift |-> ##1 data_out == {$past(data_out[6:0]),1'b0});
  ap_vec_data_ins:   assert property (disable iff (reset)
                                      !shift |-> ##1 data_out == {$past(data_out[6:0]),$past(shift_in)});

  // Coverage: exercise both insertion paths
  cv_zero_insert:    cover  property (disable iff (reset)
                                      shift ##1 (data_out[0] == 1'b0));

  cv_data_insert:    cover  property (disable iff (reset)
                                      (!shift && shift_in) ##1 (data_out[0] == 1'b1));

endmodule

// Bind into DUT
bind shift_register shift_register_sva u_shift_register_sva (.*);

