verilog_code:
module absolute_counter (
    input clk,
    input rst,
    input en,
    input ld,
    input signed [31:0] in,
    input [3:0] load_data,
    output [35:0] out
);

    // Absolute value module
    wire [31:0] abs_val;
    assign abs_val = (in < 0) ? -in : in;

    // Binary counter module
    reg [3:0] counter;
    always @(posedge clk) begin
        if (rst) begin
            counter <= 4'b0000;
        end else if (en) begin
            counter <= counter + 1;
        end else if (ld) begin
            counter <= load_data;
        end
    end

    // Output module
    assign out = abs_val + {32'b0, counter};

endmodule

sva_code:
// SVA for absolute_counter. Bind this to the DUT.
module absolute_counter_sva;

  // Bound into absolute_counter scope; direct access to DUT signals.
  default clocking cb @(posedge clk); endclocking

  // Helper expression for absolute value of input
  let abs32 = in[31] ? -$signed(in) : $signed(in);

  // Combinational functional correctness (continuous checks)
  always_comb begin
    assert (abs_val == abs32)
      else $error("absolute_counter: abs_val mismatch");
    assert (out == ({4'd0, abs32} + {32'd0, counter}))
      else $error("absolute_counter: out mismatch");
    assert (!$isunknown(out)) else $error("absolute_counter: out has X/Z");
  end

  // Synchronous reset: counter clears next cycle
  assert property (rst |=> counter == 4'h0);

  // Increment when en (priority over ld), modulo-16
  assert property (!rst && en |=> counter == ($past(counter)+4'd1)[3:0]);

  // Load when ld and !en
  assert property (!rst && !en && ld |=> counter == $past(load_data));

  // Hold when neither en nor ld
  assert property (!rst && !en && !ld |=> counter == $past(counter));

  // Explicit priority case (en && ld): still increments
  assert property (!rst && en && ld |=> counter == ($past(counter)+4'd1)[3:0]);

  // No X on state after reset deasserted
  assert property (disable iff (rst) !$isunknown(counter));

  // Coverage
  cover property (rst);
  cover property (!rst && en);                        // increment activity
  cover property (!rst && !en && ld);                 // load activity
  cover property (!rst && en && ld);                  // priority case seen
  cover property (!rst && $past(counter)==4'hF && en && counter==4'h0); // wrap-around
  cover property (in[31]);                            // negative input seen
  cover property (!in[31]);                           // non-negative input seen
  cover property (in == 32'h8000_0000);               // INT_MIN corner
endmodule

bind absolute_counter absolute_counter_sva sva_absolute_counter();

verilog_code:
module four_to_one (
    input A1,
    input A2,
    input B1,
    input B2,
    output X
);

    wire A_low, A_high, B_low, B_high;

    assign A_low = ~(A1 | A2);
    assign A_high = A1 & A2;
    assign B_low = ~(B1 | B2);
    assign B_high = B1 & B2;

    assign X = (A_low & B_low) | (A_high & B_high);

endmodule

sva_code:
// SVA checker for four_to_one
module four_to_one_sva (
  input logic A1, A2, B1, B2, X,
  input logic A_low, A_high, B_low, B_high
);
  default clocking cb @(*); endclocking

  // No X/Z on key signals
  a_known:  assert property (!$isunknown({A1,A2,B1,B2,X,A_low,A_high,B_low,B_high}));

  // Internal wire definitions
  a_low_def:   assert property (A_low  == ~(A1 | A2));
  a_high_def:  assert property (A_high ==  (A1 & A2));
  b_low_def:   assert property (B_low  == ~(B1 | B2));
  b_high_def:  assert property (B_high ==  (B1 & B2));

  // Mutual exclusion of low/high detects
  a_mutex: assert property (!(A_low  && A_high));
  b_mutex: assert property (!(B_low  && B_high));

  // Uniformity relations
  a_uniform: assert property ((A_low || A_high) == ~(A1 ^ A2));
  b_uniform: assert property ((B_low || B_high) == ~(B1 ^ B2));

  // Output function equivalence (both internal-wire and input-only forms)
  x_func_wires: assert property (X == ((A_low & B_low) | (A_high & B_high)));
  x_func_inputs: assert property (X == (~(A1 ^ A2) & ~(B1 ^ B2) & ~(A1 ^ B1)));

  // Strong implications for key cases
  x_when_both_low:  assert property ((A_low  && B_low)  |-> X);
  x_when_both_high: assert property ((A_high && B_high) |-> X);
  x_when_mixed:     assert property (((A_low && B_high) || (A_high && B_low)) |-> !X);

  // Minimal output stability: if inputs stable, X stable
  x_stable: assert property ($stable({A1,A2,B1,B2}) |-> $stable(X));

  // Coverage
  cover_X1: cover property (X);
  cover_X0: cover property (!X);
  cover_X_r: cover property (@(posedge X) 1'b1);
  cover_X_f: cover property (@(negedge X) 1'b1);

  // Cover all 16 input combinations
  generate
    for (genvar i = 0; i < 16; i++) begin : CMB
      localparam logic [3:0] V = i[3:0];
      cover_all_inputs: cover property ({A1,A2,B1,B2} == V);
    end
  endgenerate
endmodule

// Bind into DUT (connects to internals by name)
bind four_to_one four_to_one_sva four_to_one_sva_i (.*)

