module binary_counter_sva #(parameter WIDTH=4)
(
  input logic              clk,
  input logic              rst,
  input logic              en,
  input logic [WIDTH-1:0]  out
);

  bit started;
  initial started = 1'b0;
  always @(posedge clk) started <= 1'b1;

