  // Core next-state functional equivalence (covers reset, hold, increment, wrap)
  assert property (disable iff (!started)
    out == ( $past(rst) ? {WIDTH{1'b0}}
           : ($past(en) ? $past(out) + 1'b1
                        : $past(out) ) )
  );

  // Optional sanity: output never X/Z once running
  assert property (disable iff (!started) !$isunknown(out));

  // Coverage: exercise all branches and wrap
  cover property (disable iff (!started) $past(rst) && (out == {WIDTH{1'b0}}));                      // reset branch
  cover property (disable iff (!started) !$past(rst) && !$past(en) && (out == $past(out)));          // hold branch
  cover property (disable iff (!started) !$past(rst) && $past(en) &&
                                   ($past(out) != {WIDTH{1'b1}}) && (out == $past(out) + 1'b1));     // increment (no wrap)
  cover property (disable iff (!started) !$past(rst) && $past(en) &&
                                   ($past(out) == {WIDTH{1'b1}}) && (out == {WIDTH{1'b0}}));         // wrap 15->0
  cover property (disable iff (!started) $past(rst) && $past(en) && (out == {WIDTH{1'b0}}));         // rst wins over en

endmodule

// Bind into DUT
bind binary_counter binary_counter_sva #(.WIDTH(4)) i_binary_counter_sva
(
  .clk(clk),
  .rst(rst),
  .en(en),
  .out(out)
);

verilog_code:
module binary_counter
(
    input clk,
    input reset,
    output reg [3:0] count
);

    always @(posedge clk or posedge reset)
    begin
        if (reset)
            count <= 4'b0000;
        else
            count <= count + 1;
    end

endmodule

sva_code:
// SVA for binary_counter
module binary_counter_sva (
  input logic        clk,
  input logic        reset,
  input logic [3:0]  count
);

  default clocking cb @(posedge clk); endclocking

  // Async reset clears immediately
  assert property (@(posedge reset) ##0 (count == 4'd0));

  // While reset is asserted at a clk edge, count is 0
  assert property (reset |-> (count == 4'd0));

  // No X/Z on key signals at clk edge
  assert property (!$isunknown({reset, count}));

  // Increment by 1 each cycle when not in reset (mod-16)
  assert property (disable iff (reset)
                   (!$isunknown($past(count))) |-> (count == $past(count) + 4'd1));

  // Explicit wrap check F -> 0
  assert property (disable iff (reset)
                   ($past(count) == 4'hF) |-> (count == 4'd0));

  // Coverage: full 16-count wrap (0 -> 0 in exactly 16 cycles) without reset
  cover property (disable iff (reset) (count == 4'd0) ##16 (count == 4'd0));

  // Coverage: reset release leads to 1 on next clk
  cover property ($past(reset) && !reset && (count == 4'd1));

endmodule

bind binary_counter binary_counter_sva sva_i(.clk(clk), .reset(reset), .count(count));

verilog_code:
module pipelined_xor_gate (
    input clk, // Clock signal
    input a,
    input b,
    output reg out // Output should be a reg if driven by an always block
);

// Pipeline registers
reg a_reg, b_reg;

// Clocked always block for pipeline
always @(posedge clk) begin
    a_reg <= a;
    b_reg <= b;
    out <= a_reg ^ b_reg; // Perform XOR in the sequential logic
end

endmodule

sva_code:
// SVA checker + bind for pipelined_xor_gate
module pipelined_xor_gate_sva
(
  input logic clk,
  input logic a, b,
  input logic out,
  input logic a_reg, b_reg
);

  // Track $past validity
  logic past1, past2;
  always_ff @(posedge clk) begin
    past1 <= 1'b1;
    past2 <= past1;
  end

  default clocking cb @(posedge clk); endclocking

  // Pipeline registers capture inputs (when previous inputs are known)
  property p_regs_capture;
    disable iff (!past1)
      !$isunknown($past({a,b})) |-> {a_reg,b_reg} == $past({a,b});
  endproperty
  assert property (p_regs_capture);

  // Out equals prior a_reg ^ b_reg (1-cycle relation)
  property p_out_from_regs;
    disable iff (!past1)
      !$isunknown($past({a_reg,b_reg})) |-> out == $past(a_reg ^ b_reg);
  endproperty
  assert property (p_out_from_regs);

  // End-to-end: out equals inputs from 2 cycles ago
  property p_out_from_inputs;
    disable iff (!past2)
      !$isunknown($past({a,b},2)) |-> out == ($past(a,2) ^ $past(b,2));
  endproperty
  assert property (p_out_from_inputs);

  // Functional coverage: all 4 input combinations propagate through pipeline
  cover property ( (a==0 && b==0) |=> out==0 );
  cover property ( (a==0 && b==1) |=> out==1 );
  cover property ( (a==1 && b==0) |=> out==1 );
  cover property ( (a==1 && b==1) |=> out==0 );

endmodule

bind pipelined_xor_gate pipelined_xor_gate_sva
  (.clk(clk), .a(a), .b(b), .out(out), .a_reg(a_reg), .b_reg(b_reg));

verilog_code:
module two_bit_sat_counter (
    input [1:0] count_i,
    input op,
    output reg [1:0] count
);

    always @*
    begin
        case (count_i)
            2'b00: count = op ? 2'b01 : 2'b00;
            2'b01: count = op ? 2'b10 : 2'b00;
            2'b10: count = op ? 2'b10 : 2'b01;
            2'b11: count = op ? 2'b11 : 2'b10;
        endcase
    end

endmodule

sva_code:
// SVA for two_bit_sat_counter
module two_bit_sat_counter_sva (
  input  [1:0] count_i,
  input        op,
  input  [1:0] count
);

  // Functional correctness (increment direction)
  property p_inc;
    op && !$isunknown(count_i) |->
      count ==
        (count_i==2'b00 ? 2'b01 :
         count_i==2'b01 ? 2'b10 :
         count_i==2'b10 ? 2'b10 :
                          2'b11);
  endproperty
  assert property (@(*) p_inc);

  // Functional correctness (decrement direction)
  property p_dec;
    !op && !$isunknown(count_i) |->
      count ==
        (count_i==2'b00 ? 2'b00 :
         count_i==2'b01 ? 2'b00 :
         count_i==2'b10 ? 2'b01 :
                          2'b10);
  endproperty
  assert property (@(*) p_dec);

  // Monotonicity (saturating behavior)
  assert property (@(*) (op  && !$isunknown(count_i)) |->
                           (count >= count_i));
  assert property (@(*) (!op && !$isunknown(count_i)) |->
                           (count <= count_i));

  // No X on output when inputs are known
  assert property (@(*) (!$isunknown({op,count_i})) |->
                           !$isunknown(count));

  // Functional coverage: all input/output combinations
  cover property (@(*) (count_i==2'b00 &&  op && count==2'b01));
  cover property (@(*) (count_i==2'b01 &&  op && count==2'b10));
  cover property (@(*) (count_i==2'b10 &&  op && count==2'b10));
  cover property (@(*) (count_i==2'b11 &&  op && count==2'b11));

  cover property (@(*) (count_i==2'b00 && !op && count==2'b00));
  cover property (@(*) (count_i==2'b01 && !op && count==2'b00));
  cover property (@(*) (count_i==2'b10 && !op && count==2'b01));
  cover property (@(*) (count_i==2'b11 && !op && count==2'b10));

endmodule

bind two_bit_sat_counter two_bit_sat_counter_sva sva_i (
  .count_i(count_i),
  .op(op),
  .count(count)
);

verilog_code:
module addition_module (
  input [7:0] A,
  input [7:0] B,
  output reg [8:0] Sum
);

  always @(*) begin
    Sum = A + B;
  end

endmodule

sva_code:
// SVA for addition_module
module addition_module_sva (
  input logic [7:0] A,
  input logic [7:0] B,
  input logic [8:0] Sum
);

  // Functional correctness: 9-bit sum must equal zero-extended A+B when inputs are known
  a_sum_correct: assert property ( $isunknown({A,B}) or
                                   (Sum == ({1'b0, A} + {1'b0, B})) )
    else $error("Sum mismatch: expected %0d, got %0d", ({1'b0,A}+{1'b0,B}), Sum);

  // No spurious output toggles without input change
  a_no_spurious_toggle: assert property ( $changed(Sum) |-> ($changed(A) || $changed(B)) )
    else $error("Sum changed without A or B changing");

  // Coverage: hit both carry/no-carry and key edge cases
  c_no_carry:  cover property ( !$isunknown({A,B,Sum}) && (Sum[8] == 1'b0) );
  c_with_carry:cover property ( !$isunknown({A,B,Sum}) && (Sum[8] == 1'b1) );
  c_zero:      cover property ( A==8'h00 && B==8'h00 && Sum==9'h000 );
  c_max:       cover property ( A==8'hFF && B==8'hFF && Sum==9'h1FE );
  c_boundary1: cover property ( A==8'hFF && B==8'h01 && Sum==9'h100 );

endmodule

// Bind into DUT
bind addition_module addition_module_sva dut_sva (.A(A), .B(B), .Sum(Sum));

verilog_code:
module comparator (
    input [1:0] in_0,
    input [1:0] in_1,
    output reg [1:0] out
);

    always @(*) begin
        if (in_0 > in_1) begin
            out = 2'b01;
        end else if (in_0 == in_1) begin
            out = 2'b10;
        end else begin
            out = 2'b00;
        end
    end

endmodule

sva_code:
// SVA checker for comparator (binds to DUT; no DUT changes needed)
module comparator_sva (
  input logic [1:0] in_0,
  input logic [1:0] in_1,
  input logic [1:0] out
);

  function automatic logic [1:0] exp (input logic [1:0] a, input logic [1:0] b);
    exp = (a > b) ? 2'b01 : ((a == b) ? 2'b10 : 2'b00);
  endfunction

  // Functional correctness when inputs are known
  property p_func_ok;
    @(in_0 or in_1) !$isunknown({in_0,in_1}) |-> ##0 (out == exp(in_0,in_1));
  endproperty
  assert property(p_func_ok);

  // Output is 2-state when inputs are 2-state
  property p_no_x_out_when_inputs_known;
    @(in_0 or in_1) !$isunknown({in_0,in_1}) |-> ##0 !$isunknown(out);
  endproperty
  assert property(p_no_x_out_when_inputs_known);

  // Output always a legal code (00,01,10)
  property p_legal_code;
    @(out) 1 |-> ##0 (out inside {2'b00,2'b01,2'b10});
  endproperty
  assert property(p_legal_code);

  // No output toggle without an input toggle
  property p_no_spurious_toggle;
    @(out) 1 |-> ##0 ($changed(in_0) || $changed(in_1));
  endproperty
  assert property(p_no_spurious_toggle);

  // Coverage: hit all three outcomes (with known inputs)
  cover property (@(in_0 or in_1) !$isunknown({in_0,in_1}) ##0 (out == 2'b01)); // in_0 > in_1
  cover property (@(in_0 or in_1) !$isunknown({in_0,in_1}) ##0 (out == 2'b10)); // in_0 == in_1
  cover property (@(in_0 or in_1) !$isunknown({in_0,in_1}) ##0 (out == 2'b00)); // in_0 < in_1

endmodule

bind comparator comparator_sva i_comparator_sva (.in_0(in_0), .in_1(in_1), .out(out));

verilog_code:
module module_name (
    input  A1,
    input  A2,
    input  A3,
    input  B1,
    output Y
);

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    assign Y = ((A1 & A2 & A3 & ~B1) | (~A1 & ~A2 & ~A3 & B1)) ? 1'b1 : 1'b0;

endmodule

sva_code:
// SVA for module_name
// Bind-in assertions; no DUT changes required.

module module_name_sva (
  input logic A1,
  input logic A2,
  input logic A3,
  input logic B1,
  input logic Y,
  input logic VPWR,
  input logic VGND,
  input logic VPB,
  input logic VNB
);

  // Sample on any activity of relevant nets
  default clocking cb @(
    posedge A1 or negedge A1 or
    posedge A2 or negedge A2 or
    posedge A3 or negedge A3 or
    posedge B1 or negedge B1 or
    posedge Y  or negedge Y  or
    posedge VPWR or negedge VPWR or
    posedge VGND or negedge VGND or
    posedge VPB  or negedge VPB  or
    posedge VNB  or negedge VNB
  ); endclocking

  // Convenience lets
  let pgood = (VPWR===1'b1 && VGND===1'b0 && VPB===1'b1 && VNB===1'b0);
  let t1   = (A1 & A2 & A3 & ~B1);
  let t2   = (~A1 & ~A2 & ~A3 & B1);

  // Rails must be correct whenever they change
  assert property (pgood)
    else $error("module_name: Power rails not at expected values");

  // Inputs should be known (optional: tighten or turn to assume in formal)
  assert property (disable iff (!pgood) !$isunknown({A1,A2,A3,B1}))
    else $error("module_name: Unknown on inputs");

  // If inputs are known, output must be known
  assert property (disable iff (!pgood) (!$isunknown({A1,A2,A3,B1}) |-> !$isunknown(Y)))
    else $error("module_name: Output unknown with known inputs");

  // Functional correctness: Y == (t1 || t2)
  assert property (disable iff (!pgood) (!$isunknown({A1,A2,A3,B1}) |-> (Y == (t1 || t2))))
    else $error("module_name: Functional mismatch Y vs A*,B1");

  // No spurious 1s: if Y==1 then exactly one cube is true
  assert property (disable iff (!pgood) (Y |-> (t1 || t2)))
    else $error("module_name: Y asserted without a valid cause");

  // Cubes are mutually exclusive
  assert property (disable iff (!pgood) !(t1 && t2))
    else $error("module_name: Mutually exclusive terms both true");

  // Coverage: exercise both 1-cases and a 0-case; also toggle Y
  cover property (disable iff (!pgood) (t1 && Y));
  cover property (disable iff (!pgood) (t2 && Y));
  cover property (disable iff (!pgood) (!$isunknown({A1,A2,A3,B1}) && !(t1||t2) && (Y==1'b0)));
  cover property (disable iff (!pgood) $rose(Y));
  cover property (disable iff (!pgood) $fell(Y));

endmodule

bind module_name module_name_sva sva_module_name (.*);

verilog_code:
module ripple_carry_adder(
    input [3:0] A, B,
    input CIN,
    output [3:0] SUM,
    output COUT
);

    wire [3:0] carry;
    full_adder fa0(A[0], B[0], CIN, SUM[0], carry[0]);
    full_adder fa1(A[1], B[1], carry[0], SUM[1], carry[1]);
    full_adder fa2(A[2], B[2], carry[1], SUM[2], carry[2]);
    full_adder fa3(A[3], B[3], carry[2], SUM[3], COUT);

endmodule

module full_adder(
    input A, B, CIN,
    output SUM, COUT
);
    assign SUM = A ^ B ^ CIN;
    assign COUT = ((A & B) | (B & CIN) | (CIN & A));
endmodule

sva_code:
// SVA for ripple_carry_adder
// Bind into DUT to access internal carry chain
checker rca_checker (
    input logic [3:0] A, B, SUM,
    input logic       CIN, COUT,
    input logic [3:0] carry
);
    // Functional equivalence of the whole adder
    property p_total_correct;
        @(A or B or CIN)
        !$isunknown({A,B,CIN}) |-> ##0 {COUT,SUM} == (A + B + CIN);
    endproperty
    assert property (p_total_correct);

    // X-propagation: clean outputs when inputs are clean
    property p_no_x_out;
        @(A or B or CIN)
        !$isunknown({A,B,CIN}) |-> ##0 !$isunknown({SUM,COUT,carry[2:0]});
    endproperty
    assert property (p_no_x_out);

    // Bit-slice correctness and carry chain linking
    // Stage 0
    property p_s0;
        @(A or B or CIN)
        !$isunknown({A[0],B[0],CIN}) |-> ##0
            (SUM[0] == (A[0]^B[0]^CIN)) &&
            (carry[0] == ((A[0]&B[0]) | (B[0]&CIN) | (CIN&A[0])));
    endproperty
    assert property (p_s0);

    // Stage 1
    property p_s1;
        @(A or B or CIN or carry[0])
        !$isunknown({A[1],B[1],carry[0]}) |-> ##0
            (SUM[1] == (A[1]^B[1]^carry[0])) &&
            (carry[1] == ((A[1]&B[1]) | (B[1]&carry[0]) | (carry[0]&A[1])));
    endproperty
    assert property (p_s1);

    // Stage 2
    property p_s2;
        @(A or B or CIN or carry[1])
        !$isunknown({A[2],B[2],carry[1]}) |-> ##0
            (SUM[2] == (A[2]^B[2]^carry[1])) &&
            (carry[2] == ((A[2]&B[2]) | (B[2]&carry[1]) | (carry[1]&A[2])));
    endproperty
    assert property (p_s2);

    // Stage 3 (final)
    property p_s3;
        @(A or B or CIN or carry[2])
        !$isunknown({A[3],B[3],carry[2]}) |-> ##0
            (SUM[3] == (A[3]^B[3]^carry[2])) &&
            (COUT   == ((A[3]&B[3]) | (B[3]&carry[2]) | (carry[2]&A[3])));
    endproperty
    assert property (p_s3);

    // Concise functional coverage
    // Zero add, no carry
    cover property (@(A or B or CIN) ##0 (A==4'h0 && B==4'h0 && CIN==0 && SUM==4'h0 && COUT==0));
    // Max add with carry-out
    cover property (@(A or B or CIN) ##0 (A==4'hF && B==4'hF && CIN==1 && SUM==4'hF && COUT==1));
    // Full propagate chain (all P=1) with carry-in=1 causes carry-out
    cover property (@(A or B or CIN) ##0 ((A^B)==4'hF && CIN==1 && COUT==1));
    // Observe carries through the chain at least once
    cover property (@(A or B or CIN) ##0 (carry[0]));
    cover property (@(A or B or CIN) ##0 (carry[1]));
    cover property (@(A or B or CIN) ##0 (carry[2]));
    cover property (@(A or B or CIN) ##0 (COUT));
endchecker

bind ripple_carry_adder rca_checker rca_chk (
    .A(A), .B(B), .SUM(SUM), .CIN(CIN), .COUT(COUT), .carry(carry)
);

verilog_code:
module logic_expression(
    input A,
    input B,
    input C,
    input D,
    input E,
    output X
    );

    wire w1, w2, w3, w4, w5, w6, w7, w8, w9, w10, w11, w12;

    assign w1 = ~A & ~B & ~C & D & ~E;
    assign w2 = ~A & ~B & ~C & D & E;
    assign w3 = ~A & ~B & C & ~D & E;
    assign w4 = ~A & ~B & C & D & E;
    assign w5 = ~A & B & ~C & ~D & E;
    assign w6 = ~A & B & ~C & D & E;
    assign w7 = ~A & B & C & ~D & E;
    assign w8 = A & ~B & ~C & ~D & E;
    assign w9 = A & ~B & ~C & D & E;
    assign w10 = A & ~B & C & D & E;
    assign w11 = A & B & C & ~D & E;
    assign w12 = A & B & C & D & E;

    assign X = w1 | w2 | w3 | w4 | w5 | w6 | w7 | w8 | w9 | w10 | w11 | w12;

endmodule

sva_code:
// SVA checker for logic_expression
// Binds to DUT, recomputes expected X, asserts equivalence, and provides full input coverage.

module logic_expression_sva_chk (
  input logic A, B, C, D, E,
  input logic X
);

  // Minterms from spec (w1..w12)
  logic [11:0] m;
  assign m[0]  = (~A & ~B & ~C &  D & ~E);
  assign m[1]  = (~A & ~B & ~C &  D &  E);
  assign m[2]  = (~A & ~B &  C & ~D &  E);
  assign m[3]  = (~A & ~B &  C &  D &  E);
  assign m[4]  = (~A &  B & ~C & ~D &  E);
  assign m[5]  = (~A &  B & ~C &  D &  E);
  assign m[6]  = (~A &  B &  C & ~D &  E);
  assign m[7]  = ( A & ~B & ~C & ~D &  E);
  assign m[8]  = ( A & ~B & ~C &  D &  E);
  assign m[9]  = ( A & ~B &  C &  D &  E);
  assign m[10] = ( A &  B &  C & ~D &  E);
  assign m[11] = ( A &  B &  C &  D &  E);

  logic expX;
  assign expX = |m;

  function automatic bit inputs_known();
    return !$isunknown({A,B,C,D,E});
  endfunction

  // Combinational assertions (no clock needed)
  always_comb begin
    if (inputs_known()) begin
      assert (!$isunknown(X))
        else $error("X is X/Z with known inputs A=%0b B=%0b C=%0b D=%0b E=%0b", A,B,C,D,E);

      assert (X == expX)
        else $error("X mismatch. A=%0b B=%0b C=%0b D=%0b E=%0b expX=%0b got=%0b", A,B,C,D,E,expX,X);

      // Sanity: minterms are mutually exclusive
      assert ($onehot0(m))
        else $error("Overlapping minterms detected for A=%0b B=%0b C=%0b D=%0b E=%0b (m=%0h)", A,B,C,D,E,m);

      // Key special-case check: when E==0, only one way to get X==1
      if (!E)
        assert (X == (~A & ~B & ~C & D))
          else $error("E=0 gating violated. A=%0b B=%0b C=%0b D=%0b X=%0b", A,B,C,D,X);
    end
  end

  // Functional coverage: all 32 input combinations and their X
  event ev; always @* -> ev;
  covergroup cg_inputs @(ev);
    cp_inputs: coverpoint {A,B,C,D,E} { bins all[] = {[0:31]}; }
    x_by_inputs: cross cp_inputs, X;
  endgroup
  cg_inputs cg = new();

endmodule

bind logic_expression logic_expression_sva_chk sva (.A(A), .B(B), .C(C), .D(D), .E(E), .X(X));

verilog_code:
module mux8to1 (
    output reg y,
    input s2,
    input s1,
    input s0,
    input d4,
    input d3,
    input d2,
    input d1,
    input d0
);

always @(*) begin
    case ({s2, s1, s0})
        3'b000: y = d0;
        3'b001: y = d1;
        3'b010: y = d2;
        3'b011: y = d3;
        3'b100: y = d4;
        default: y = 1'b0;
    endcase
end

endmodule

sva_code:
// SVA checker for mux8to1
module mux8to1_sva (
  input logic y,
  input logic s2, s1, s0,
  input logic d4, d3, d2, d1, d0
);

  logic [2:0] sel = {s2,s1,s0};
  logic expected_y;
  assign expected_y = (sel==3'b000) ? d0 :
                      (sel==3'b001) ? d1 :
                      (sel==3'b010) ? d2 :
                      (sel==3'b011) ? d3 :
                      (sel==3'b100) ? d4 : 1'b0;

  // Functional equivalence on any relevant change
  property p_func;
    @(s0 or s1 or s2 or d0 or d1 or d2 or d3 or d4 or y) (y === expected_y);
  endproperty
  assert property (p_func)
    else $error("mux8to1: y mismatch sel=%b d={%b%b%b%b%b} y=%b exp=%b", sel,d4,d3,d2,d1,d0,y,expected_y);

  // If sel and selected input are known, y must be known
  function automatic logic selected_known;
    case (sel)
      3'b000: selected_known = !$isunknown(d0);
      3'b001: selected_known = !$isunknown(d1);
      3'b010: selected_known = !$isunknown(d2);
      3'b011: selected_known = !$isunknown(d3);
      3'b100: selected_known = !$isunknown(d4);
      default: selected_known = 1'b1; // default path is constant 0
    endcase
  endfunction

  property p_no_x_when_known;
    @(s0 or s1 or s2 or d0 or d1 or d2 or d3 or d4)
      (!$isunknown(sel) && selected_known()) |-> !$isunknown(y);
  endproperty
  assert property (p_no_x_when_known)
