module barrel_shifter (
    input [3:0] A,
    input [1:0] B,
    output reg [3:0] shifted
);

always @(*) begin
    case (B)
        2'b00: shifted = A;
        2'b01: shifted = {A[2:0], A[3]};
        2'b10: shifted = {A[1:0], A[3:2]};
        2'b11: shifted = {A[0], A[3:1]};
    endcase
end

endmodule

module up_down_counter (
    input clk,
    input UP,
    input DOWN,
    input reset,
    output reg [2:0] Q
);

always @(posedge clk) begin
    if (reset) begin
        Q <= 3'b000;
    end else if (UP && !DOWN) begin
        Q <= Q + 1;
    end else if (!UP && DOWN) begin
        Q <= Q - 1;
    end
end

endmodule

module functional_module (
    input [3:0] shifted,
    input [2:0] Q,
    output reg [7:0] q
);

always @(*) begin
    q = {4'b0000, shifted} + {3'b000, Q};
end

endmodule

module top_module (
    input clk,
    input reset,
    input [3:0] A,
    input [1:0] B,
    input UP,
    input DOWN,
    output [7:0] q
);

wire [3:0] shifted;
wire [2:0] Q;

barrel_shifter bs (
    .A(A),
    .B(B),
    .shifted(shifted)
);

up_down_counter udc (
    .clk(clk),
    .UP(UP),
    .DOWN(DOWN),
    .reset(reset),
    .Q(Q)
);

functional_module fm (
    .shifted(shifted),
    .Q(Q),
    .q(q)
);

endmodule

sva_code:
// SVA for top_module and sub-blocks
module top_module_sva (
  input clk, input reset,
  input [3:0] A, input [1:0] B,
  input UP, input DOWN,
  input [3:0] shifted, input [2:0] Q,
  input [7:0] q
);

  default clocking cb @(posedge clk); endclocking

  // ---------------- Barrel shifter correctness ----------------
  assert property (disable iff ($isunknown({A,B,shifted})))
    shifted == ((B==2'b00)? A :
                (B==2'b01)? {A[2:0],A[3]} :
                (B==2'b10)? {A[1:0],A[3:2]} :
                            {A[0],A[3:1]});

  // Coverage of all shift selections
  cover property (B==2'b00);
  cover property (B==2'b01);
  cover property (B==2'b10);
  cover property (B==2'b11);

  // ---------------- Up/Down counter correctness ----------------
  // Synchronous reset behavior
  assert property (reset |=> Q==3'b000);
  cover  property (reset |=> Q==3'b000);

  // Increment, decrement, and hold behaviors
  assert property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    (UP && !DOWN) |=> Q == $past(Q)+3'd1;

  assert property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    (!UP && DOWN) |=> Q == $past(Q)-3'd1;

  assert property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    (UP && DOWN) |=> Q == $past(Q);

  assert property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    (!UP && !DOWN) |=> Q == $past(Q);

  // Wrap-around coverage
  cover property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    ($past(Q)==3'd7 && UP && !DOWN) |=> (Q==3'd0);

  cover property (disable iff (reset || $isunknown({UP,DOWN,Q})))
    ($past(Q)==3'd0 && !UP && DOWN) |=> (Q==3'd7);

  // Exercise all control cases
  cover property (disable iff (reset)) (UP && !DOWN);
  cover property (disable iff (reset)) (!UP && DOWN);
  cover property (disable iff (reset)) (UP && DOWN);
  cover property (disable iff (reset)) (!UP && !DOWN);

  // ---------------- Functional module correctness ----------------
  // Exact arithmetic result
  assert property (disable iff ($isunknown({shifted,Q,q})))
    q == ({4'b0000, shifted} + {3'b000, Q});

  // Carry-out/nibble-crossing coverage
  cover property (({4'b0000, shifted} + {3'b000, Q})[7:4] != 4'b0000);

  // ---------------- Sanity: no Xs on key outputs after reset ----------------
  assert property (disable iff (reset)) !$isunknown({shifted,Q,q});

endmodule

// Bind into the DUT
bind top_module top_module_sva sva_i (
  .clk   (clk),
  .reset (reset),
  .A     (A),
  .B     (B),
  .UP    (UP),
  .DOWN  (DOWN),
  .shifted (shifted),
  .Q     (Q),
  .q     (q)
);

// SVA for up_down_counter
module up_down_counter_sva (
  input clk,
  input reset,
  input direction,
  input [3:0] count
);

  // Sample after NBA so we can compare next-state with current inputs
  default clocking cb @(posedge clk);
    input #1step reset, direction, count;
  endclocking

  // Track that at least one sample has occurred for safe $past usage
  bit past_valid;
  always @(posedge clk) past_valid <= 1'b1;

  // Synchronous reset drives zero in the same cycle
  a_reset_zero: assert property (@cb reset |-> (count == 4'h0));

  // Next-state function (increment/decrement with wrap), out of reset
  a_next_state: assert property (@cb disable iff (reset)
    past_valid |-> count ==
      (direction
        ? (($past(count) == 4'hF) ? 4'h0 : $past(count) + 1)
        : (($past(count) == 4'h0) ? 4'hF : $past(count) - 1))
  );

  // Count must change every cycle out of reset
  a_change: assert property (@cb disable iff (reset) past_valid |-> (count != $past(count)));

  // No X/Z on output out of reset
  a_no_x: assert property (@cb disable iff (reset) !$isunknown(count));

  // Coverage
  c_wrap_up:   cover property (@cb disable iff (reset)  direction && ($past(count) == 4'hF) && (count == 4'h0));
  c_wrap_down: cover property (@cb disable iff (reset) !direction && ($past(count) == 4'h0) && (count == 4'hF));
  c_dir_up:    cover property (@cb disable iff (reset) $rose(direction));
  c_dir_down:  cover property (@cb disable iff (reset) $fell(direction));
  c_hit_zero:  cover property (@cb disable iff (reset) (count == 4'h0));
  c_hit_max:   cover property (@cb disable iff (reset) (count == 4'hF));

endmodule

// Bind into the DUT
bind up_down_counter up_down_counter_sva u_up_down_counter_sva (
  .clk(clk), .reset(reset), .direction(direction), .count(count)
);

