// SVA for d_ff_reset: async active-low reset, posedge clocked DFF
module d_ff_reset_sva #(parameter int unsigned RECOVERY_CYCLES = 1) (
  input logic D,
  input logic RESET_B,
  input logic CLK,
  input logic Q
);

  // Q goes low immediately on async reset assert; stays low while in reset
  ap_async_reset_immediate: assert property ( $fell(RESET_B) |-> ##0 (Q==1'b0) );
  ap_reset_holds_Q_low:    assert property ( !RESET_B |-> (Q==1'b0) );

  // After reset deassert, Q must remain 0 until the next clock edge
  ap_q_zero_until_clk_after_release: assert property ( $rose(RESET_B) |-> (Q==1'b0 until_with $rose(CLK)) );

  // On posedge CLK with reset deasserted, Q captures D (check in NBA/postponed with ##0)
  ap_capture_on_clk: assert property ( @(posedge CLK) RESET_B |-> ##0 (Q == $past(D)) );

  // Data must be known when sampled; Q changes only on allowed events
  ap_d_known_at_sample:         assert property ( @(posedge CLK) RESET_B |-> !$isunknown(D) );
  ap_q_changes_only_on_events:  assert property ( $changed(Q) |-> ($rose(CLK) || $fell(RESET_B)) );

  // Optional recovery: require RESET_B high for RECOVERY_CYCLES prior clocks before sampling
  ap_recovery_cycles: assert property ( @(posedge CLK) disable iff (!RESET_B)
                                       $past(RESET_B, RECOVERY_CYCLES) );

  // Coverage
  cv_reset_assert:   cover property ( $fell(RESET_B) );
  cv_reset_deassert: cover property ( $rose(RESET_B) );
  cv_capture_any:    cover property ( @(posedge CLK) RESET_B ##0 (Q==D) );
  cv_q_rise:         cover property ( @(posedge CLK) RESET_B ##0 $rose(Q) );
  cv_q_fall:         cover property ( @(posedge CLK) RESET_B ##0 $fell(Q) );
  cv_cap_one:        cover property ( @(posedge CLK) RESET_B && (D==1) ##0 (Q==1) );
  cv_cap_zero:       cover property ( @(posedge CLK) RESET_B && (D==0) ##0 (Q==0) );

endmodule

bind d_ff_reset d_ff_reset_sva sva_i (.*);

// SVA for counter
module counter_sva #(parameter int WIDTH=4)
(
  input logic              CLK,
  input logic              RST,
  input logic              enable,
  input logic [WIDTH-1:0]  count_out
);

  default clocking cb @(posedge CLK); endclocking

  // Control sanity
  assert property (!$isunknown(RST) && !$isunknown(enable))
    else $error("counter: control inputs have X/Z");

  // Synchronous reset dominates and drives zero
  assert property (RST |-> (count_out == '0))
    else $error("counter: count_out not zero during RST");

  // When not in reset: increment on enable
  assert property (disable iff (RST) (enable |-> (count_out == $past(count_out) + 1'b1)))
    else $error("counter: increment mismatch");

  // When not in reset: hold when disabled
  assert property (disable iff (RST) (!enable |-> (count_out == $past(count_out))))
    else $error("counter: held value changed without enable");

  // Explicit wrap-around check (redundant with increment, but makes intent clear)
  assert property (disable iff (RST) (enable && ($past(count_out) == {WIDTH{1'b1}}) |-> (count_out == '0)))
    else $error("counter: wrap-around failed");

  // Output known when active (no X/Z after reset deasserted)
  assert property (!RST |-> !$isunknown(count_out))
    else $error("counter: count_out has X/Z when not in reset");

  // Coverage
  cover property (RST);                                            // saw reset
  cover property (disable iff (RST) enable);                       // saw increment opportunity
  cover property (disable iff (RST) !enable);                      // saw hold opportunity
  cover property (disable iff (RST) (enable && $past(count_out)=={WIDTH{1'b1}} && count_out=='0)); // wrap event
  cover property (RST && enable && count_out=='0);                 // simultaneous RST & enable

endmodule

bind counter counter_sva #(.WIDTH(4)) counter_sva_i (.*);

