  // First 2-to-1 MUX
  mux2to1 mux1(.a(a), .b(b), .sel(sel[0]), .y(mux1_out));

  // Second 2-to-1 MUX
  mux2to1 mux2(.a(c), .b(d), .sel(sel[0]), .y(mux2_out));

  // Final 2-to-1 MUX
  mux2to1 mux3(.a(mux1_out), .b(mux2_out), .sel(sel[1]), .y(y));

