module complement (
    input D,
    output reg Q,
    input CLK
);

    reg reg1 = 0;
    reg reg2 = 1;

    always @(posedge CLK) begin
        reg1 <= D;
    end

    always @(posedge CLK) begin
        reg2 <= reg1;
    end

    always @(posedge CLK) begin
        Q <= reg1;
        reg2 <= ~reg2;
    end

endmodule

sva_code:
// SVA for module complement
// Bind this checker to the DUT to verify timing/functional intent concisely.

module complement_sva (
  input  logic CLK,
  input  logic D,
  input  logic Q,
  input  logic reg1,
  input  logic reg2
);
  default clocking cb @(posedge CLK); endclocking

  // Guard for $past
  logic past1, past2;
  always_ff @(posedge CLK) begin
    past1 <= 1'b1;
    past2 <= past1;
  end

  // reg1 must capture D each cycle
  assert property (disable iff (!past1) reg1 == $past(D))
    else $error("reg1 did not capture D");

  // Q must follow prior reg1 each cycle
  assert property (disable iff (!past1) Q == $past(reg1))
    else $error("Q did not follow reg1 (1-cycle)");

  // Optional direct D->Q 1-cycle latency check (enabled after 2 clocks)
  assert property (disable iff (!past2) Q == $past(D))
    else $error("Q did not reflect prior D (1-cycle)");

  // Knownness (catch X/Z) after pipeline fills
  assert property (disable iff (!past1) !$isunknown(reg1))
    else $error("reg1 is X/Z");
  assert property (disable iff (!past2) !$isunknown(Q))
    else $error("Q is X/Z after latency");

  // reg2 consistency: due to multiple synchronous drivers, reg2 can become either
  // the toggle of its prior value or the prior reg1 value. It must be one of them.
  // This both documents and constrains the ambiguous behavior.
  assert property (disable iff (!past1)
                   (reg2 == ~$past(reg2)) || (reg2 == $past(reg1)))
    else $error("reg2 inconsistent with either toggle or reg1");

  // Coverage: exercise 0->1 and 1->0 on D and observe Q next cycle
  cover property (disable iff (!past2) $rose(D) |=> Q == 1'b1);
  cover property (disable iff (!past2) $fell(D) |=> Q == 1'b0);

  // Coverage: observe both possible reg2 resolutions (if they occur)
  cover property (disable iff (!past1) reg2 == ~$past(reg2));   // toggle won
  cover property (disable iff (!past1) reg2 == $past(reg1));    // reg1 assignment won
endmodule

// Bind to the DUT (place in a separate bind file or testbench)
bind complement complement_sva u_complement_sva (
  .CLK (CLK),
  .D   (D),
  .Q   (Q),
  .reg1(reg1),
  .reg2(reg2)
);

verilog_code:
module dff_preset_clear (
    input wire D,
    input wire CLK,
    input wire PRE,  // Preset
    input wire CLR,  // Clear
    output wire Q,
    output wire Q_N
);

    reg [0:0] _Q;
    assign Q = _Q[0];
    assign Q_N = ~_Q[0];

    always @(posedge CLK) begin
        if (CLR) begin // Clear
            _Q[0] <= 0;
        end else if (PRE) begin // Preset
            _Q[0] <= 1;
        end else begin // Normal Operation
            _Q[0] <= D;
        end
    end

endmodule

sva_code:
// SVA for dff_preset_clear
module dff_preset_clear_sva (
  input logic D,
  input logic CLK,
  input logic PRE,
  input logic CLR,
  input logic Q,
  input logic Q_N
);
  default clocking cb @(posedge CLK); endclocking

  // Track availability of $past()
  logic past_valid;
  initial past_valid = 1'b0;
  always @(posedge CLK) past_valid <= 1'b1;

  // Core next-state function (priority: CLR > PRE > D)
  assert property (
    past_valid |-> Q == ( $past(CLR) ? 1'b0
                       : $past(PRE) ? 1'b1
                       : $past(D) )
  );

  // Complementary outputs
  assert property (Q_N === ~Q);

  // Glitch-free outputs: change only on clock edge
  assert property (@(posedge Q  or negedge Q ) $rose(CLK));
  assert property (@(posedge Q_N or negedge Q_N) $rose(CLK));

  // Coverage: exercise all behaviors
  cover property (past_valid && $past(CLR)                            && Q==1'b0); // clear
  cover property (past_valid && !$past(CLR) && $past(PRE)             && Q==1'b1); // preset
  cover property (past_valid && !$past(CLR) && !$past(PRE) && $past(D)   && Q==1'b1); // normal set
  cover property (past_valid && !$past(CLR) && !$past(PRE) && !$past(D)  && Q==1'b0); // normal reset
  cover property (past_valid && $past(CLR) && $past(PRE)              && Q==1'b0); // both asserted, CLR wins
  cover property (past_valid && $past(Q)==1'b0 && Q==1'b1); // Q 0->1
  cover property (past_valid && $past(Q)==1'b1 && Q==1'b0); // Q 1->0
endmodule

bind dff_preset_clear dff_preset_clear_sva u_dff_preset_clear_sva (
  .D(D), .CLK(CLK), .PRE(PRE), .CLR(CLR), .Q(Q), .Q_N(Q_N)
);

verilog_code:
module mem_soft_ecc
  #(
    parameter C_DATA_WIDTH          = 32,
    parameter C_ADDRB_WIDTH         = 10,
    parameter C_HAS_SOFTECC_OUTPUT_REGS_B= 1,
    parameter C_USE_SOFTECC         = 0,
    parameter FLOP_DELAY            = 100
  )
  (
   input                         CLK,
   input      [C_DATA_WIDTH-1:0] DIN,
   output reg [C_DATA_WIDTH-1:0] DOUT,
   input                         SBITERR_IN,
   input                         DBITERR_IN,
   output reg                    SBITERR,
   output reg                    DBITERR,
   input      [C_ADDRB_WIDTH-1:0] RDADDRECC_IN,
   output reg [C_ADDRB_WIDTH-1:0] RDADDRECC
);

  //******************************
  // Port and Generic Definitions
  //******************************
  // C_DATA_WIDTH                  : Memory write/read width
  // C_ADDRB_WIDTH                 : Width of the ADDRB input port
  // C_HAS_SOFTECC_OUTPUT_REGS_B   : Designates the use of a register at the output 
  //                                 of the RAM primitive
  // C_USE_SOFTECC                 : Determines if the Soft ECC feature is used or
  //                                 not. Only applicable Spartan-6
  // FLOP_DELAY                    : Constant delay for register assignments
  //////////////////////////////////////////////////////////////////////////
  // Port Definitions
  //////////////////////////////////////////////////////////////////////////
  // CLK    : Clock to synchronize all read and write operations
  // DIN    : Data input to the Output stage.
  // DOUT   : Final Data output
  // SBITERR_IN    : SBITERR input signal to the Output stage.
  // SBITERR       : Final SBITERR Output signal.
  // DBITERR_IN    : DBITERR input signal to the Output stage.
  // DBITERR       : Final DBITERR Output signal.
  // RDADDRECC_IN  : RDADDRECC input signal to the Output stage.
  // RDADDRECC     : Final RDADDRECC Output signal.
  //////////////////////////////////////////////////////////////////////////

  reg [C_DATA_WIDTH-1:0] dout_i = 0;
  reg sbiterr_i = 0;
  reg dbiterr_i = 0;
  reg [C_ADDRB_WIDTH-1:0] rdaddrecc_i = 0;

  //***********************************************
  // NO OUTPUT REGISTERS.
  //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==0) begin : no_output_stage
    always @* begin
      DOUT = DIN;
      RDADDRECC = RDADDRECC_IN;
      SBITERR = SBITERR_IN;
      DBITERR = DBITERR_IN;
    end
  end
  endgenerate

  //***********************************************
  // WITH OUTPUT REGISTERS.
  //***********************************************
  generate if (C_HAS_SOFTECC_OUTPUT_REGS_B==1) begin : has_output_stage
      always @(posedge CLK) begin
      dout_i <= #FLOP_DELAY DIN;
      rdaddrecc_i <= #FLOP_DELAY RDADDRECC_IN;
      sbiterr_i <= #FLOP_DELAY SBITERR_IN;
      dbiterr_i <= #FLOP_DELAY DBITERR_IN;
      end

      always @* begin
      DOUT = dout_i;
      RDADDRECC = rdaddrecc_i;
      SBITERR = sbiterr_i;
      DBITERR = dbiterr_i;
      end //end always
  end //end in_or_out_stage generate statement
  endgenerate

endmodule

sva_code:
// SVA for mem_soft_ecc
// Bindable, concise, and parameter-aware

module mem_soft_ecc_sva #(
  parameter int C_DATA_WIDTH  = 32,
  parameter int C_ADDRB_WIDTH = 10,
  parameter int C_HAS_SOFTECC_OUTPUT_REGS_B = 1,
  parameter int FLOP_DELAY = 100
)(
  input  logic                         CLK,
  input  logic [C_DATA_WIDTH-1:0]      DIN,
  input  logic [C_ADDRB_WIDTH-1:0]     RDADDRECC_IN,
  input  logic                         SBITERR_IN,
  input  logic                         DBITERR_IN,
  input  logic [C_DATA_WIDTH-1:0]      DOUT,
  input  logic [C_ADDRB_WIDTH-1:0]     RDADDRECC,
  input  logic                         SBITERR,
  input  logic                         DBITERR
);

  default clocking cb @(posedge CLK); endclocking

  // past_valid to avoid first-sample $past hazards
  logic past_valid;
  always_ff @(posedge CLK) past_valid <= 1'b1;

  // Basic X-prop sanity (outputs should not be X when corresponding inputs are known)
  // Combinational path: same-cycle; Registered path: one-cycle
  generate
    if (C_HAS_SOFTECC_OUTPUT_REGS_B==0) begin : comb_checks
      // Functional passthrough
      assert property (DOUT == DIN
                    && RDADDRECC == RDADDRECC_IN
                    && SBITERR == SBITERR_IN
                    && DBITERR == DBITERR_IN)
        else $error("mem_soft_ecc comb mismatch");

      // X-clean when inputs known
      assert property ((!$isunknown(DIN))        |-> (!$isunknown(DOUT)));
      assert property ((!$isunknown(RDADDRECC_IN)) |-> (!$isunknown(RDADDRECC)));
      assert property ((!$isunknown(SBITERR_IN)) |-> (!$isunknown(SBITERR)));
      assert property ((!$isunknown(DBITERR_IN)) |-> (!$isunknown(DBITERR)));

      // Coverage: observe propagation on change/pulse
      cover property ($changed(DIN)         && (DOUT==DIN));
      cover property ($changed(RDADDRECC_IN) && (RDADDRECC==RDADDRECC_IN));
      cover property ($rose(SBITERR_IN)     && SBITERR);
      cover property ($fell(SBITERR_IN)     && !SBITERR);
      cover property ($rose(DBITERR_IN)     && DBITERR);
      cover property ($fell(DBITERR_IN)     && !DBITERR);
    end
    else begin : reg_checks
      // One-cycle registered delay (assumes FLOP_DELAY < clock period)
      assert property (past_valid |-> (
                         DOUT      == $past(DIN)         &&
                         RDADDRECC == $past(RDADDRECC_IN) &&
                         SBITERR   == $past(SBITERR_IN)  &&
                         DBITERR   == $past(DBITERR_IN)))
        else $error("mem_soft_ecc reg mismatch");

      // X-clean one-cycle later when prior inputs known
      assert property (past_valid && (!$isunknown($past(DIN)))          |-> (!$isunknown(DOUT)));
      assert property (past_valid && (!$isunknown($past(RDADDRECC_IN))) |-> (!$isunknown(RDADDRECC)));
      assert property (past_valid && (!$isunknown($past(SBITERR_IN)))   |-> (!$isunknown(SBITERR)));
      assert property (past_valid && (!$isunknown($past(DBITERR_IN)))   |-> (!$isunknown(DBITERR)));

      // Coverage: observe 1-cycle propagation
      cover property ($changed(DIN)          ##1 (DOUT==$past(DIN)));
      cover property ($changed(RDADDRECC_IN) ##1 (RDADDRECC==$past(RDADDRECC_IN)));
      cover property ($rose(SBITERR_IN)      ##1 $rose(SBITERR));
      cover property ($fell(SBITERR_IN)      ##1 $fell(SBITERR));
      cover property ($rose(DBITERR_IN)      ##1 $rose(DBITERR));
      cover property ($fell(DBITERR_IN)      ##1 $fell(DBITERR));
    end
  endgenerate

endmodule

// Bind into the DUT
bind mem_soft_ecc mem_soft_ecc_sva #(
  .C_DATA_WIDTH(C_DATA_WIDTH),
  .C_ADDRB_WIDTH(C_ADDRB_WIDTH),
  .C_HAS_SOFTECC_OUTPUT_REGS_B(C_HAS_SOFTECC_OUTPUT_REGS_B),
  .FLOP_DELAY(FLOP_DELAY)
) mem_soft_ecc_sva_b (
  .CLK(CLK),
  .DIN(DIN),
  .RDADDRECC_IN(RDADDRECC_IN),
  .SBITERR_IN(SBITERR_IN),
  .DBITERR_IN(DBITERR_IN),
  .DOUT(DOUT),
  .RDADDRECC(RDADDRECC),
  .SBITERR(SBITERR),
  .DBITERR(DBITERR)
);

