module top_module (
    input  [31:0] a,
    input  [31:0] b,
    input         select, //Select input to choose between adder and multiplexer
    output [31:0] result
);

wire [1:0] sub_out;
wire [0:0] mux_out;
wire [31:0] final_out;

subtractor sub(
    .a(a),
    .b(b),
    .result(sub_out)
);

mux mux_inst(
    .a(a[0]),
    .b(b[0]),
    .c(a[1]),
    .d(b[1]),
    .out(mux_out) //Selecting only the LSBs of a and b
);

final_output final_inst(
    .sub_out(sub_out),
    .select(select),
    .a(a[0]),
    .b(b[0]),
    .c(32'h0),
    .d(32'h0),
    .final_out(final_out)
);

assign result = select ? {31'b0, mux_out} : final_out;

endmodule
module subtractor (
    input  [31:0] a,
    input  [31:0] b,
    output [1:0] result
);

wire [31:0] a_inv;
wire [31:0] b_inv;
wire [31:0] carry_in;
wire [31:0] carry_out;
wire [31:0] sum;

assign a_inv = ~a;
assign b_inv = ~b;

//Generate carry select signals
assign carry_in[0] = 1'b0;
genvar i;
generate
    for (i = 1; i < 32; i = i + 1) begin : carry_select
        assign carry_in[i] = (a[i-1] & b[i-1]) | (a[i-1] & carry_out[i-1]) | (b[i-1] & carry_out[i-1]);
    end
endgenerate

//Generate sum signals
assign sum[0] = a[0] ^ b[0] ^ carry_in[0];
generate
    for (i = 1; i < 32; i = i + 1) begin : sum_gen
        assign sum[i] = a[i] ^ b[i] ^ carry_in[i];
    end
endgenerate

//Generate carry out signal
assign carry_out[0] = (a[0] & b[0]) | (a[0] & carry_in[0]) | (b[0] & carry_in[0]);
generate
    for (i = 1; i < 32; i = i + 1) begin : carry_out_gen
        assign carry_out[i] = (a[i] & b[i]) | (a[i] & carry_out[i-1]) | (b[i] & carry_out[i-1]);
    end
endgenerate

assign result = sum[1:0];

endmodule
module mux (
    input  a,
    input  b,
    input  c,
    input  d,
    output out
);

assign out = (a & ~b & ~c & ~d) | (~a & b & ~c & ~d);

endmodule
module final_output (
    input  [1:0] sub_out,
    input         select,
    input  a,
    input  b,
    input  c,
    input  d,
    output [31:0] final_out
);

assign final_out = select ? {31'b0, (a & ~b & ~c & ~d) | (~a & b & ~c & ~d)} : {31'b0, sub_out};

endmodule

sva_code:
// SVA checkers and binds for the provided design

// Top-level behavior checker
module top_module_sva (
  input  logic [31:0] a,
  input  logic [31:0] b,
  input  logic        select,
  input  logic [31:0] result
);
  default clocking cb @(a or b or select); endclocking

  // Select=1: result = {31'b0, (a0^b0) & ~a1 & ~b1}
  assert property ( !$isunknown({a[1:0], b[1:0], select}) && select
                    |-> result == {31'b0, ((a[0]^b[0]) & ~a[1] & ~b[1])} );

  // Select=0: result = {30'b0, (a+b)[1:0]}
  assert property ( !$isunknown({a, b, select}) && !select
                    |-> result == {30'b0, (a + b)[1:0]} );

  // Structural zeros on upper bits
  assert property ( !$isunknown({a, b, select})
                    |-> (select ? (result[31:1] == 31'b0)
                                : (result[31:2] == 30'b0)) );

  // Coverage: both modes and LSB=1 in each mode
  cover property (select);
  cover property (!select);
  cover property ( select && (a[1]==0) && (b[1]==0) && (a[0]^b[0]) && result[0] );
  cover property ( !select && ((a + b)[0]) && result[0] );
endmodule

// Subtractor checker (actually adds a+b, returns sum[1:0])
module subtractor_sva (
  input  logic [31:0] a,
  input  logic [31:0] b,
  input  logic [1:0]  result
);
  default clocking cb @(a or b); endclocking

  assert property ( !$isunknown({a, b}) |-> result == (a + b)[1:0] );

  // Coverage of all 2-bit sum outcomes
  cover property (result == 2'b00);
  cover property (result == 2'b01);
  cover property (result == 2'b10);
  cover property (result == 2'b11);
endmodule

// Mux checker (out == (a^b) & ~c & ~d)
module mux_sva (
  input  logic a,
  input  logic b,
  input  logic c,
  input  logic d,
  input  logic out
);
  default clocking cb @(a or b or c or d); endclocking

  assert property ( !$isunknown({a,b,c,d}) |-> out == ((a ^ b) & ~c & ~d) );

  // Coverage
  cover property (out == 1'b1);
  cover property (out == 1'b0);
endmodule

// final_output checker
module final_output_sva (
  input  logic [1:0]  sub_out,
  input  logic        select,
  input  logic        a,
  input  logic        b,
  input  logic        c,
  input  logic        d,
  input  logic [31:0] final_out
);
  default clocking cb @(sub_out or select or a or b or c or d); endclocking

  // Select=0: {30'b0, sub_out}
  assert property ( !$isunknown({sub_out, select}) && !select
                    |-> (final_out[31:2] == 30'b0 && final_out[1:0] == sub_out) );

  // Select=1: {31'b0, (a^b)&~c&~d}
  assert property ( !$isunknown({select, a, b, c, d}) && select
                    |-> final_out == {31'b0, ((a ^ b) & ~c & ~d)} );

  // Coverage
  cover property (!select);
  cover property ( select && ((a ^ b) & ~c & ~d) && final_out[0] );
endmodule

// Bind the SVA to the DUT instances
bind top_module     top_module_sva     top_module_sva_i     (.*);
bind subtractor     subtractor_sva     subtractor_sva_i     (.*);
bind mux            mux_sva            mux_sva_i            (.*);
bind final_output   final_output_sva   final_output_sva_i   (.*);

// SVA for binary_counter
module binary_counter_sva (
  input clk,
  input reset,
  input enable,
  input [3:0] count
);
  default clocking cb @(posedge clk); endclocking

  // Reset behavior
  a_reset_clears_next:    assert property (reset |=> count == 4'd0);
  a_reset_holds_zero:     assert property (reset && $past(reset) |-> count == 4'd0);

  // Functional behavior
  a_hold_when_disabled:   assert property (disable iff (reset) (!enable) |=> count == $past(count));
  a_inc_when_enabled:     assert property (disable iff (reset) (enable)   |=> count == (($past(count)+4'd1) & 4'hF));
  a_change_requires_en:   assert property ((!reset && !$past(reset) && $changed(count)) |-> $past(enable));

  // Sanity
  a_count_known:          assert property (disable iff (reset) !$isunknown(count));

  // Coverage
  c_reset_clear:          cover  property (reset ##1 count == 4'd0);
  c_inc_after_reset:      cover  property (reset ##1 !reset ##1 enable ##1 count == 4'd1);
  c_wraparound:           cover  property (disable iff (reset) ($past(count)==4'hF && enable) ##1 (count==4'h0));
  c_hold_case:            cover  property (disable iff (reset) (!enable && $past(!enable) && count==$past(count)));
endmodule

// Bind into DUT
bind binary_counter binary_counter_sva sva_i (.*);

