module up_counter(
    input clk,
    input reset,
    output reg [3:0] count,
    output reg out
);

always @(posedge clk) begin
    if(reset) begin
        count <= 4'b0;
        out <= 1'b0;
    end
    else begin
        count <= count + 1;
        out <= ~out;
    end
end

endmodule

sva_code:
// SVA for up_counter
module up_counter_sva (
  input logic        clk,
  input logic        reset,
  input logic [3:0]  count,
  input logic        out
);
  default clocking cb @(posedge clk); endclocking

  // Synchronous reset drives zeros (visible next sample)
  a_reset_next: assert property (reset |=> (count == 4'h0 && out == 1'b0));

  // Free-run behavior: modulo-16 increment and out toggles each non-reset cycle
  a_next_update: assert property (
    !reset |=> (
      ( ($past(count) == 4'hF) ? (count == 4'h0) : (count == $past(count) + 4'h1) )
      && (out == ~ $past(out))
    )
  );

  // No X/Z when not in reset
  a_no_x: assert property (!reset |-> !($isunknown(count) || $isunknown(out)));

  // Coverage
  c_wrap:      cover property (!reset && $past(!reset) && $past(count) == 4'hF && count == 4'h0);
  c_toggle:    cover property (!reset && $past(!reset) && (out == ~ $past(out)));
  c_16_cycle:  cover property ((!reset)[*16] ##1 (count == $past(count,16) && out == $past(out,16)));
  c_rst_rise:  cover property ($rose(reset));
  c_rst_fall:  cover property ($fell(reset));
endmodule

// Bind to DUT
bind up_counter up_counter_sva u_up_counter_sva (.clk(clk), .reset(reset), .count(count), .out(out));

// SVA for binary_counter
module binary_counter_sva #(parameter N=4)(
  input  logic              clk,
  input  logic              reset,
  input  logic [N-1:0]      count
);

  // establish a safe $past window
  logic past_valid;
  always_ff @(posedge clk) past_valid <= 1'b1;

  // default clock
  default clocking cb @(posedge clk); endclocking

  // 1) Synchronous reset clears count on the next clock
  assert property (reset |=> count == '0);

  // 2) When previous cycle was not reset, counter increments by 1 (mod 2^N)
  assert property (past_valid && !$past(reset) |-> count == $past(count) + 1);

  // 3) Explicitly check wrap from max -> 0 on increment
  assert property (past_valid && !$past(reset) && ($past(count) == {N{1'b1}}) |-> count == '0);

  // 4) No unknowns on count once we have at least one sample
  assert property (past_valid |-> !$isunknown(count));

  // Coverage
  cover property (reset);                               // saw reset asserted
  cover property ($rose(reset));                        // reset rise
  cover property ($fell(reset));                        // reset deassert
  cover property (past_valid && !$past(reset) &&       // observed a wrap event
                  ($past(count) == {N{1'b1}}) && (count == '0));
  // From a reset, observe first increment 0 -> 1
  cover property ($past(reset) && !reset && (count == $past(count) + 1));

endmodule

// Bind into DUT
bind binary_counter binary_counter_sva #(.N(N))
  binary_counter_sva_i (.clk(clk), .reset(reset), .count(count));

