module RCA_4bit (
  input [3:0] A,
  input [3:0] B,
  output [3:0] S,
  input Ci,
  output Co
);

  wire [3:1] CTMP;

  FA_1 FAI_1 ( .A(A[0]), .B(B[0]), .Ci(Ci), .S(S[0]), .Co(CTMP[1]) );
  FA_1 FAI_2 ( .A(A[1]), .B(B[1]), .Ci(CTMP[1]), .S(S[1]), .Co(CTMP[2]) );
  FA_1 FAI_3 ( .A(A[2]), .B(B[2]), .Ci(CTMP[2]), .S(S[2]), .Co(CTMP[3]) );
  FA_1 FAI_4 ( .A(A[3]), .B(B[3]), .Ci(CTMP[3]), .S(S[3]), .Co(Co) );

endmodule

module FA_1 (
  input A,
  input B,
  input Ci,
  output S,
  output Co
);

  assign {Co, S} = A + B + Ci;

endmodule

sva_code:
// SystemVerilog Assertions for RCA_4bit and FA_1
// Focused, concise, full functional checks and coverage.
// Bind as shown at bottom.

module fa_1_sva (input A, input B, input Ci, input S, input Co);
  // Functional check
  always_comb begin
    if (!$isunknown({A,B,Ci,S,Co})) begin
      assert ({Co,S} === A + B + Ci)
        else $error("FA_1 mismatch: A=%0b B=%0b Ci=%0b => S=%0b Co=%0b", A,B,Ci,S,Co);
    end
  end

  // Simple endpoint coverage
  always_comb begin
    cover ({A,B,Ci} == 3'b000 && {Co,S} == 2'b00);
    cover ({A,B,Ci} == 3'b111 && {Co,S} == 2'b11);
  end
endmodule


module rca_4bit_sva (
  input  [3:0] A,
  input  [3:0] B,
  input        Ci,
  input  [3:0] S,
  input        Co,
  input  [3:1] CTMP
);
  // Local carry-in per stage
  wire [3:0] c_in;
  assign c_in[0] = Ci;
  assign c_in[1] = CTMP[1];
  assign c_in[2] = CTMP[2];
  assign c_in[3] = CTMP[3];

  // Top-level functional equivalence and X-prop
  always_comb begin
    if (!$isunknown({A,B,Ci})) begin
      assert (!$isunknown({S,Co}))
        else $error("RCA_4bit X/Z on outputs with known inputs");
      assert ({Co,S} === A + B + Ci)
        else $error("RCA_4bit sum mismatch: A=%0h B=%0h Ci=%0b => S=%0h Co=%0b", A,B,Ci,S,Co);
    end
  end

  // Per-bit sum checks
  genvar i;
  generate
    for (i = 0; i < 4; i++) begin: g_sum
      always_comb begin
        if (!$isunknown({A[i],B[i],c_in[i],S[i]})) begin
          assert (S[i] === (A[i] ^ B[i] ^ c_in[i]))
            else $error("Bit %0d sum mismatch", i);
        end
      end
    end
  endgenerate

  // Carry chain checks for internal CTMP[1..3]
  generate
    for (i = 0; i < 3; i++) begin: g_carry_mid
      wire expected_c = (A[i] & B[i]) | (A[i] & c_in[i]) | (B[i] & c_in[i]);
      always_comb begin
        if (!$isunknown({A[i],B[i],c_in[i],CTMP[i+1]})) begin
          assert (CTMP[i+1] === expected_c)
            else $error("CTMP[%0d] mismatch", i+1);
        end
      end
    end
  endgenerate

  // Final carry-out check
  always_comb begin
    if (!$isunknown({A[3],B[3],c_in[3],Co})) begin
      assert (Co === ((A[3] & B[3]) | (A[3] & c_in[3]) | (B[3] & c_in[3])))
        else $error("Final Co mismatch");
    end
  end

  // Full functional coverage of all 32 sum values
  generate
    genvar v;
    for (v = 0; v < 32; v++) begin: g_sumcov
      localparam logic [4:0] SUMVAL = v[4:0];
      always_comb cover ({Co,S} === SUMVAL);
    end
  endgenerate

  // Coverage: internal carries exercise 0 and 1
  genvar j;
  generate
    for (j = 1; j <= 3; j++) begin: g_ctmpcov
      always_comb begin
        cover (CTMP[j] == 1'b0);
        cover (CTMP[j] == 1'b1);
      end
    end
  endgenerate

  // Coverage: full carry propagate chain
  always_comb begin
    cover (((A ^ B) == 4'hF) && (Ci == 1'b0) && (Co == 1'b0));
    cover (((A ^ B) == 4'hF) && (Ci == 1'b1) && (Co == 1'b1));
  end
endmodule


// Bind the SVA modules to the DUTs
bind FA_1    fa_1_sva     u_fa_1_sva (.*);
bind RCA_4bit rca_4bit_sva u_rca_4bit_sva (.A(A), .B(B), .Ci(Ci), .S(S), .Co(Co), .CTMP(CTMP));

verilog_code:
module priority_encoder (
    input [3:0] in1,
    input [3:0] in2,
    output [3:0] priority_output
);

    assign priority_output = (in1 > in2) ? in1 : in2;

endmodule

module final_output_generator (
    input [3:0] in1,
    input [3:0] in2,
    output reg [3:0] final_output
);

    wire [3:0] priority_output;
    priority_encoder encoder(in1, in2, priority_output);

    always @* begin
        case (priority_output)
            4'b0001: final_output = in1;
            4'b0010: final_output = in2;
            4'b0100: final_output = {in1[3:1], in2[0]};
            4'b1000: final_output = {in2[3:1], in1[0]};
            default: final_output = 4'b0000;
        endcase
    end

endmodule

sva_code:
// SVA for priority_encoder and final_output_generator
// Concise, high-quality checks with targeted coverage

module sva_priority_encoder(
  input logic [3:0] in1,
  input logic [3:0] in2,
  input logic [3:0] priority_output
);
  default clocking cb @($global_clock); endclocking

  let p = (in1 > in2) ? in1 : in2;

  // Functional correctness
  a_pe_func:  assert property (priority_output == p)
    else $error("priority_output mismatch");

  // No X/Z propagation when inputs are clean
  a_pe_no_x:  assert property (!$isunknown({in1,in2}) |-> !$isunknown(priority_output))
    else $error("priority_output has X/Z with clean inputs");

  // Coverage: all compare outcomes
  c_pe_gt:    cover property (in1 > in2);
  c_pe_lt:    cover property (in1 < in2);
  c_pe_eq:    cover property (in1 == in2);
endmodule


module sva_final_output_generator(
  input logic [3:0] in1,
  input logic [3:0] in2,
  input logic [3:0] priority_output,
  input logic [3:0] final_output
);
  default clocking cb @($global_clock); endclocking

  let p = (in1 > in2) ? in1 : in2;
  let f = (p==4'b0001) ? in1
        : (p==4'b0010) ? in2
        : (p==4'b0100) ? {in1[3:1], in2[0]}
        : (p==4'b1000) ? {in2[3:1], in1[0]}
        :                 4'b0000;

  // End-to-end functional correctness of final_output behavior
  a_fog_func: assert property (final_output == f)
    else $error("final_output mismatch");

  // No X/Z propagation when inputs are clean
  a_fog_no_x: assert property (!$isunknown({in1,in2}) |-> !$isunknown({priority_output,final_output}))
    else $error("priority_output/final_output has X/Z with clean inputs");

  // Coverage: hit each case item and default
  c_fog_case1:    cover property (p==4'b0001);
  c_fog_case2:    cover property (p==4'b0010);
  c_fog_case4:    cover property (p==4'b0100);
  c_fog_case8:    cover property (p==4'b1000);
  c_fog_default:  cover property (!(p inside {4'b0001,4'b0010,4'b0100,4'b1000}));
endmodule

// Bind assertions to DUTs
bind priority_encoder        sva_priority_encoder        pe_sva  (.*);
bind final_output_generator  sva_final_output_generator  fog_sva (.*);

