module top_module (
    input [3:0] A, B,
    input [2:0] OP,
    input [3:0] a, b,
    output [1:0] final_output
);

    wire [3:0] alu_result;
    wire [2:0] comparison_result;

    alu alu_inst (
        .A(A),
        .B(B),
        .OP(OP),
        .P(alu_result)
    );

    mag_comp_priority_encoder mag_comp_inst (
        .a(a),
        .b(b),
        .comparison_result(comparison_result)
    );

    assign final_output = (comparison_result == 3 && alu_result == 0) ? 2'b10 :
                          (comparison_result == 2) ? 2'b01 :
                          (comparison_result == 1) ? 2'b00 :
                          2'b11;

endmodule

module alu (
    input [3:0] A, B,
    input [2:0] OP,
    output reg [3:0] P
);

    always @(*) begin
        case (OP)
            3'b000: P = A & B;
            3'b001: P = A | B;
            3'b010: P = A + B;
            3'b011: P = A - B;
            3'b100: P = A ^ B;
            3'b101: P = ~A;
            3'b110: P = A << 1;
            3'b111: P = A >> 1;
            default: P = 4'bxxxx;
        endcase
    end

endmodule

module mag_comp_priority_encoder (
    input [3:0] a, b,
    output reg [2:0] comparison_result
);

    always @(*) begin
        if (a > b) begin
            comparison_result = 3'b010;
        end else if (a < b) begin
            comparison_result = 3'b001;
        end else begin
            comparison_result = 3'b000;
        end
    end

endmodule

sva_code:
// SVA for the given design. Concise, bound to DUT modules. No TB code.

// Assertions for ALU
module alu_sva (
  input logic [3:0] A, B,
  input logic [2:0] OP,
  input logic [3:0] P
);
  default clocking cb @(*); endclocking

  // Functional correctness per OP
  a_and:  assert property (OP==3'b000 |-> P == (A & B));
  a_or:   assert property (OP==3'b001 |-> P == (A | B));
  a_add:  assert property (OP==3'b010 |-> P == (A + B));
  a_sub:  assert property (OP==3'b011 |-> P == (A - B));
  a_xor:  assert property (OP==3'b100 |-> P == (A ^ B));
  a_not:  assert property (OP==3'b101 |-> P == (~A));
  a_sll1: assert property (OP==3'b110 |-> P == (A << 1));
  a_srl1: assert property (OP==3'b111 |-> P == (A >> 1));

  // No X on output for any legal OP
  a_nox:  assert property (!$isunknown(P));

  // Coverage: hit all ops
  cover property (OP==3'b000);
  cover property (OP==3'b001);
  cover property (OP==3'b010);
  cover property (OP==3'b011);
  cover property (OP==3'b100);
  cover property (OP==3'b101);
  cover property (OP==3'b110);
  cover property (OP==3'b111);
endmodule

// Assertions for comparator/priority encoder
module comp_sva (
  input logic [3:0] a, b,
  input logic [2:0] comparison_result
);
  default clocking cb @(*); endclocking

  c_gt:    assert property ((a > b) |-> comparison_result == 3'b010);
  c_lt:    assert property ((a < b) |-> comparison_result == 3'b001);
  c_eq:    assert property ((a == b) |-> comparison_result == 3'b000);

  // Only 000/001/010 are allowed encodings
  c_valid: assert property (comparison_result inside {3'b000,3'b001,3'b010});

  // No X on output
  c_nox:   assert property (!$isunknown(comparison_result));

  // Coverage: hit all 3 relations and codes
  cover property (a > b && comparison_result == 3'b010);
  cover property (a < b && comparison_result == 3'b001);
  cover property (a == b && comparison_result == 3'b000);
endmodule

// Assertions for top mapping to final_output
module top_sva (
  input logic [3:0] alu_result,
  input logic [2:0] comparison_result,
  input logic [1:0] final_output
);
  default clocking cb @(*); endclocking

  // Exact functional equivalence to RTL expression
  t_eq: assert property (
    final_output == ((comparison_result == 3'b011 && alu_result == 4'b0000) ? 2'b10 :
                     (comparison_result == 3'b010) ? 2'b01 :
                     (comparison_result == 3'b001) ? 2'b00 :
                     2'b11)
  );

  // Given comparator encoding, 2'b10 should be unreachable
  t_no10: assert property (final_output != 2'b10);

  // Sanity: no X on output
  t_nox: assert property (!$isunknown(final_output));

  // Coverage: observe all reachable final_output values
  cover property (final_output == 2'b00);
  cover property (final_output == 2'b01);
  cover property (final_output == 2'b11);
  // Optional: attempt to cover unreachable 2'b10 (expected 0 hits)
  cover property (final_output == 2'b10);
endmodule

// Bind assertions to DUT
bind alu                        alu_sva alu_sva_i (.*);
bind mag_comp_priority_encoder  comp_sva comp_sva_i (.*);
bind top_module                 top_sva  top_sva_i  (.alu_result(alu_result),
                                                     .comparison_result(comparison_result),
                                                     .final_output(final_output));

// SVA for counter_4bit
module counter_4bit_sva (
  input logic       clk,
  input logic       rst,
  input logic       en,
  input logic [3:0] out
);
  default clocking @(posedge clk); endclocking

  // Reset clears on next cycle (synchronous reset, priority over en)
  property p_reset_clears; rst |=> (out == 4'h0); endproperty
  assert property (p_reset_clears) else $error("out not cleared after rst");

  // Hold when disabled (no change if rst=0 and en=0)
  property p_hold_when_disabled; (!rst && !en) |=> (out == $past(out)); endproperty
  assert property (p_hold_when_disabled) else $error("out changed while en=0");

  // Increment by 1 when enabled (no wrap case)
  property p_inc_when_enabled_no_wrap;
    (!rst && en && $past(out) != 4'hF) |=> (out == $past(out) + 4'd1);
  endproperty
  assert property (p_inc_when_enabled_no_wrap) else $error("out failed +1 increment");

  // Wrap from 0xF to 0 when enabled
  property p_wrap_when_enabled_on_F;
    (!rst && en && $past(out) == 4'hF) |=> (out == 4'h0);
  endproperty
  assert property (p_wrap_when_enabled_on_F) else $error("out failed wrap 0xF->0");

  // Out changes only due to prior rst or prior en
  property p_only_changes_on_en_or_rst;
    $changed(out) |-> ($past(rst) || (!$past(rst) && $past(en)));
  endproperty
  assert property (p_only_changes_on_en_or_rst) else $error("out changed without rst/en cause");

  // Coverage: observe reset effect, normal increment, wrap, and hold
  cover property (rst |=> out == 4'h0);
  cover property (!rst && en && $past(out) != 4'hF |=> out == $past(out) + 4'd1);
  cover property (!rst && en && $past(out) == 4'hF |=> out == 4'h0);
  cover property (!rst && !en |=> out == $past(out));

  // Coverage: full 16-count cycle under continuous enable (after a reset to 0)
  sequence s_full_cycle;
    rst ##1 (out == 4'h0) ##1 en[*16] ##1 (out == 4'h0);
  endsequence
  cover property (s_full_cycle);

endmodule

// Bind into DUT
bind counter_4bit counter_4bit_sva u_counter_4bit_sva (.clk(clk), .rst(rst), .en(en), .out(out));

