module zero_to_one_counter (
    input clk,
    input reset, // Synchronous active-high reset
    input [15:0] in, // 16-bit input
    output reg out // Output
);

    always @(posedge clk) begin
        if (reset) begin
            out <= 1'b0;
        end else if (in == 16'hFFFF) begin
            out <= 1'b1;
        end else begin
            out <= out + 1'b1;
        end
    end

endmodule

module adder_4bit_cin_cout (
    input [3:0] A, // 4-bit input A
    input [3:0] B, // 4-bit input B
    input CIN, // Carry-in
    output [3:0] S, // 4-bit output sum
    output COUT // Carry-out
);

    assign {COUT, S} = A + B + CIN;

endmodule

module top_module (
    input clk,
    input reset, // Synchronous active-high reset
    input [3:0] A, // 4-bit input for the adder
    input [3:0] B, // 4-bit input for the adder
    input CIN, // Carry-in for the adder
    input [15:0] in, // 16-bit input for the zero-to-one counter
    output [3:0] S // 4-bit output for the final sum
);

    wire [3:0] adder_out;
    wire zero_to_one_out;

    adder_4bit_cin_cout adder_inst (
        .A(A),
        .B(B),
        .CIN(CIN),
        .S(adder_out),
        .COUT()
    );

    zero_to_one_counter zero_to_one_inst (
        .clk(clk),
        .reset(reset),
        .in(in),
        .out(zero_to_one_out)
    );

    assign S = adder_out + zero_to_one_out;

endmodule

sva_code:
// SVA for zero_to_one_counter
module sva_zero_to_one_counter (
  input logic clk,
  input logic reset,
  input logic [15:0] in,
  input logic out
);
  default clocking @(posedge clk); endclocking

  // Knownness
  assert property (disable iff (reset) !$isunknown(out));

  // Next-state functional checks (use $past to avoid NBA race)
  assert property ($past(reset) |-> out == 1'b0);
  assert property ($past(!reset && in == 16'hFFFF) |-> out == 1'b1);
  assert property ($past(!reset && in != 16'hFFFF) |-> out == ~$past(out));

  // Covers
  cover property ($past(!reset && in != 16'hFFFF && $past(out)==1'b0) && out==1'b1); // 0->1 toggle
  cover property ($past(!reset && in != 16'hFFFF && $past(out)==1'b1) && out==1'b0); // 1->0 toggle
  cover property ($past(!reset && in == 16'hFFFF) && out==1'b1);                     // force-1 path
  cover property ($rose(reset));                                                     // see reset happen
endmodule

// SVA for adder_4bit_cin_cout (combinational)
module sva_adder_4bit_cin_cout (
  input  logic [3:0] A,
  input  logic [3:0] B,
  input  logic       CIN,
  input  logic [3:0] S,
  input  logic       COUT
);
  // Functional equivalence
  assert property ( {COUT,S} == (A + B + CIN) );

  // Knownness propagation: known inputs imply known outputs
  assert property ( (!$isunknown({A,B,CIN})) |-> (!$isunknown({S,COUT})) );

  // Covers
  cover property (CIN==1'b0 && COUT==1'b1); // carry generated
  cover property (CIN==1'b1 && COUT==1'b1); // carry with CIN
  cover property (S==4'h0);                 // sum wrap to 0
endmodule

// SVA for top_module
module sva_top_module (
  input  logic        clk,
  input  logic        reset,
  input  logic [3:0]  A,
  input  logic [3:0]  B,
  input  logic        CIN,
  input  logic [15:0] in,
  input  logic [3:0]  S,
  input  logic        zero_to_one_out
);
  default clocking @(posedge clk); endclocking

  // Top-level functional relationship holds at all times
  assert property ( S == (A + B + CIN + zero_to_one_out)[3:0] );

  // Knownness: known inputs imply known S
  assert property ( (!$isunknown({A,B,CIN,zero_to_one_out})) |-> (!$isunknown(S)) );

  // Covers
  // - S toggles when adder inputs are stable and counter path is in toggle mode
  cover property ( $stable(A) && $stable(B) && $stable(CIN) &&
                   $past(!reset && in!=16'hFFFF) && (!reset && in!=16'hFFFF) &&
                   (S != $past(S)) );

  // - Wrap-around at 0xF + carry-in from counter
  cover property ( (((A + B + CIN) & 4'hF) == 4'hF) && zero_to_one_out==1'b1 && S==4'h0 );

  // - Force-one from counter affects S
  cover property ( $past(!reset && in==16'hFFFF) && (S == (A + B + CIN + 1)[3:0]) );
endmodule

// Bind the SVA to the DUTs
bind zero_to_one_counter     sva_zero_to_one_counter z2o_sva   (.clk(clk), .reset(reset), .in(in), .out(out));
bind adder_4bit_cin_cout     sva_adder_4bit_cin_cout add_sva   (.A(A), .B(B), .CIN(CIN), .S(S), .COUT(COUT));
bind top_module              sva_top_module          top_sva   (.clk(clk), .reset(reset), .A(A), .B(B), .CIN(CIN), .in(in), .S(S), .zero_to_one_out(zero_to_one_out));

// SVA for binary_adder
module binary_adder_sva (
  input logic [7:0] A,
  input logic [7:0] B,
  input logic       C,
  input logic [7:0] S
);
  logic [8:0] add9, sub9;
  logic [7:0] expS;

  always_comb begin
    add9 = {1'b0, A} + {1'b0, B};
    sub9 = {1'b0, A} - {1'b0, B};
    expS = C ? sub9[7:0] : add9[7:0];

    // Functional correctness and X-prop (sample after comb settles)
    if (!$isunknown({A,B,C})) begin
      assert #0 (S === expS)
        else $error("binary_adder mismatch: C=%0b A=%0h B=%0h S=%0h exp=%0h", C,A,B,S,expS);
      assert #0 (!$isunknown(S))
        else $error("binary_adder X/Z on S with known inputs: C=%0b A=%0h B=%0h S=%0h", C,A,B,S);
    end

    // Concise functional coverage (key modes and corner cases)
    cover #0 (C==1'b0);                    // add mode hit
    cover #0 (C==1'b1);                    // sub mode hit
    cover #0 (C==1'b0 && add9[8]);         // add overflow
    cover #0 (C==1'b1 && (A < B));         // sub underflow (borrow)
    cover #0 (A==8'h00 && B==8'h00);       // both zero
    cover #0 (A==8'hFF && B==8'h00);
    cover #0 (A==8'h00 && B==8'hFF);
    cover #0 (A==8'hFF && B==8'hFF);       // max - max / max + max
    cover #0 (C==1'b0 && S==8'h00);        // zero sum
    cover #0 (C==1'b1 && S==8'h00);        // zero diff
  end
endmodule

bind binary_adder binary_adder_sva sva_inst(.A(A), .B(B), .C(C), .S(S));

