endspecify
`endif
`ifdef arriav
specify
    if (ENA && ACLR !== 1'b0 && !SCLR && !SLOAD) (posedge CLK => (Q : DATAIN)) = 470;
    if (ENA && SCLR) (posedge CLK => (Q : 1'b0)) = 633;
