// SVA for Mux_3x1_W11
// Bind this file alongside the DUT

module Mux_3x1_W11_sva (
  input [1:0]  ctrl,
  input [10:0] D0,
  input [10:0] D1,
  input [10:0] D2,
  input [10:0] S
);
  default clocking cb @(*); endclocking

  // Functional equivalence (4-state accurate)
  a_func: assert property (S === (ctrl==2'b00 ? D0 :
                                  ctrl==2'b01 ? D1 :
                                  ctrl==2'b10 ? D2 : 11'b0));

  // Default path for all non-00/01/10 encodings (including X/Z)
  a_default: assert property ((ctrl!=2'b00 && ctrl!=2'b01 && ctrl!=2'b10) |-> (S === 11'b0));

  // No X/Z on S when selected input is known
  a_known_d0: assert property ((ctrl==2'b00 && !$isunknown(D0)) |-> (!$isunknown(S) && S==D0));
  a_known_d1: assert property ((ctrl==2'b01 && !$isunknown(D1)) |-> (!$isunknown(S) && S==D1));
  a_known_d2: assert property ((ctrl==2'b10 && !$isunknown(D2)) |-> (!$isunknown(S) && S==D2));

  // Non-interference: unselected inputs must not affect S
  a_nonint_00_d1: assert property ((ctrl==2'b00 && $changed(D1)) |-> $stable(S));
  a_nonint_00_d2: assert property ((ctrl==2'b00 && $changed(D2)) |-> $stable(S));
  a_nonint_01_d0: assert property ((ctrl==2'b01 && $changed(D0)) |-> $stable(S));
  a_nonint_01_d2: assert property ((ctrl==2'b01 && $changed(D2)) |-> $stable(S));
  a_nonint_10_d0: assert property ((ctrl==2'b10 && $changed(D0)) |-> $stable(S));
  a_nonint_10_d1: assert property ((ctrl==2'b10 && $changed(D1)) |-> $stable(S));

  // Coverage: hit all selections and default, and observe data pass-through activity
  c_sel_00: cover property (ctrl==2'b00 && S===D0);
  c_sel_01: cover property (ctrl==2'b01 && S===D1);
  c_sel_10: cover property (ctrl==2'b10 && S===D2);
  c_def:    cover property ((ctrl!=2'b00 && ctrl!=2'b01 && ctrl!=2'b10) && S===11'b0);

  c_pass_d0: cover property (ctrl==2'b00 && $changed(D0) && $changed(S) && S===D0);
  c_pass_d1: cover property (ctrl==2'b01 && $changed(D1) && $changed(S) && S===D1);
  c_pass_d2: cover property (ctrl==2'b10 && $changed(D2) && $changed(S) && S===D2);

endmodule

bind Mux_3x1_W11 Mux_3x1_W11_sva i_Mux_3x1_W11_sva (.ctrl(ctrl), .D0(D0), .D1(D1), .D2(D2), .S(S));

// SVA for module adder
module adder_sva #(parameter W=16)
(
  input  logic                     clk,
  input  logic                     rst,
  input  logic signed [W-1:0]      a,
  input  logic signed [W-1:0]      b,
  input  logic signed [W-1:0]      sum
);

  default clocking cb @(posedge clk); endclocking

  function automatic signed [W-1:0] add_s(input signed [W-1:0] x, input signed [W-1:0] y);
    add_s = x + y; // 2's complement wrap (matches RTL)
  endfunction

  // Assertions

  // Synchronous reset: next-cycle output is zero
  ap_rst_nxt_zero:        assert property ( $past(rst) |-> sum == '0 );

  // Functional correctness: registered 1-cycle sum when not in reset previous cycle
  ap_sum_correct:         assert property ( !$past(rst) |-> sum == add_s($past(a), $past(b)) );

  // First cycle after reset deassert: compute from deassertion-cycle inputs
  ap_first_after_reset:   assert property ( $fell(rst) |=> sum == add_s($past(a), $past(b)) );

  // Output should never be X/Z once there is at least one cycle of history
  ap_no_x_sum:            assert property ( $past(1'b1) |-> !$isunknown(sum) );

  // While reset remains asserted across cycles, sum stays zero
  ap_hold_zero_while_rst: assert property ( $past(rst) && rst |-> sum == '0 );

  // Coverage

  // See both reset edges
  cv_reset_assert:  cover property ( $rose(rst) );
  cv_reset_release: cover property ( $fell(rst) );

  // Normal operation exercised
  cv_oper:          cover property ( !$past(rst) && sum == add_s($past(a), $past(b)) );

  // Positive overflow (pos + pos -> neg)
  cv_pos_overflow:  cover property ( !$past(rst) && ($past(a[W-1])==0) && ($past(b[W-1])==0) && sum[W-1]==1 );

  // Negative overflow (neg + neg -> pos)
  cv_neg_overflow:  cover property ( !$past(rst) && ($past(a[W-1])==1) && ($past(b[W-1])==1) && sum[W-1]==0 );

  // Zero result (e.g., b == -a)
  cv_zero_sum:      cover property ( !$past(rst) && sum == '0 );

endmodule

// Bind into DUT
bind adder adder_sva #(.W(16)) u_adder_sva (.*);

verilog_code:
module carry_lookahead_multiplier (
    input [7:0] a,
    input [7:0] b,
    input clk,
    input reset,
    output reg [15:0] result
);

    wire [7:0] p [7:0];
    wire [7:0] g [7:0];
    wire [7:0] c [8:0];

    assign p[0] = a & b[0];
    assign g[0] = a | b[0];

    genvar i;
    generate
        for (i = 1; i < 8; i = i + 1) begin
            assign p[i] = a & b[i];
            assign g[i] = a | b[i];
            assign c[i] = g[i-1] & c[i-1] | p[i-1];
        end
        assign c[8] = g[7] & c[7] | p[7];
    endgenerate

    always @(posedge clk) begin
        if (reset) begin
            result <= 0;
        end else begin
            result <= {8'b0, a} + ({8'b0, b} << 8);
        end
    end

endmodule

sva_code:
// SVA for carry_lookahead_multiplier
// Bind this file to the DUT: bind carry_lookahead_multiplier cla_mult_sva;

module cla_mult_sva;

  // Reset behavior (must zero result on any cycle reset is 1)
  assert property (@(posedge clk) reset |-> result == 16'h0000)
    else $error("Result not cleared on reset");

  // Use a default clock and disable assertions during reset for the rest
  default clocking cb @(posedge clk); endclocking
  default disable iff (reset);

  // Sanity: no X/Z on key IOs when not in reset
  assert property (!$isunknown({a,b,reset}))
    else $error("X/Z on inputs");

  // No X/Z on result when not in reset
  assert property (!$isunknown(result))
    else $error("X/Z on result");

  // Core functionality: sequential concatenation (1-cycle latency)
  // Guard with $past(!reset) to avoid first-cycle $past hazards
  assert property ((!reset && $past(!reset)) |-> result == { $past(b), $past(a) })
    else $error("Result != {b,a} from prior cycle");

  // Arithmetic form equivalence (as implemented)
  assert property ((!reset && $past(!reset)) |-> result == ($past({8'h00,a}) + ($past({8'h00,b}) << 8)))
    else $error("Result != zero-extended add/shift form from prior cycle");

  // Structural sanity on partial products and generates (width/replication correctness)
  // These catch common width/replication bugs like using a & b[i] instead of a & {8{b[i]}}
  genvar gi;
  generate
    for (gi = 0; gi < 8; gi++) begin : P_G_CHECKS
      assert property (p[gi] == (a & {8{b[gi]}}))
        else $error("p[%0d] mismatch: expect a & {8{b[%0d]}}", gi, gi);
      assert property (g[gi] == (a | {8{b[gi]}}))
        else $error("g[%0d] mismatch: expect a | {8{b[%0d]}}", gi, gi);
    end
  endgenerate

  // Carry chain knownness (c[0] must be driven; propagates to all)
  generate
    for (genvar cj = 0; cj <= 8; cj++) begin : C_KNOWN
      assert property (!$isunknown(c[cj]))
        else $error("c[%0d] has X/Z", cj);
    end
  endgenerate

  // Lightweight coverage
  cover property ($fell(reset));                                    // reset deassertion seen
  cover property ((!reset && $past(!reset)) && result == { $past(b), $past(a) }); // normal update
  cover property ((!reset && $past(!reset)) && $past(a)==8'h00 && $past(b)==8'h00 && result==16'h0000);
  cover property ((!reset && $past(!reset)) && $past(a)==8'hFF && $past(b)==8'hFF && result==16'hFFFF);
  cover property ((!reset && $past(!reset)) && $past(a)==8'h01 && $past(b)==8'h80 && result==16'h8001);

endmodule

bind carry_lookahead_multiplier cla_mult_sva;

// Bindable SVA for calculator
module calc_sva(
  input logic        clk,
  input logic        rst,
  input logic [1:0]  op,
  input logic [3:0]  num1,
  input logic [3:0]  num2,
  input logic [3:0]  result,
  input logic        overflow
);

  default clocking @(posedge clk); endclocking
  default disable iff (rst);

  // Golden, width-safe intermediates
  let sum5  = {1'b0, num1} + {1'b0, num2};        // 5-bit add
  let diff5 = {1'b0, num1} - {1'b0, num2};        // 5-bit sub (MSB=borrow)
  let prod8 = num1 * num2;                        // 8-bit mul

  // Arithmetic correctness (lower 4 bits)
  assert property (op==2'b00 |-> result == sum5[3:0])  else $error("ADD result mismatch");
  assert property (op==2'b01 |-> result == diff5[3:0]) else $error("SUB result mismatch");
  assert property (op==2'b10 |-> result == prod8[3:0]) else $error("MUL result mismatch");
  assert property ((op==2'b11) && (num2!=0) |-> result == (num1 / num2)) else $error("DIV result mismatch");

  // Overflow/exception semantics
  assert property (op==2'b00 |-> overflow == sum5[4])                       else $error("ADD overflow mismatch");
  assert property (op==2'b01 |-> overflow == (num1 < num2))                 else $error("SUB underflow mismatch");
  assert property (op==2'b10 |-> overflow == (|prod8[7:4]))                 else $error("MUL overflow mismatch");
  assert property ((op==2'b11) && (num2!=0) |-> overflow == 1'b0)           else $error("DIV overflow should be 0 when denom!=0");
  assert property ((op==2'b11) && (num2==0) |-> overflow == 1'b1)           else $error("DIV by zero must flag overflow");

  // X-propagation/clean outputs (except div-by-zero case)
  assert property (!$isunknown({op,num1,num2}) && !(op==2'b11 && num2==0)
                   |-> !$isunknown({result,overflow}))
    else $error("Unexpected X/Z on outputs with valid inputs");

  // Basic op legality (op is 2 bits; ensure no X)
  assert property (!$isunknown(op)) else $error("op contains X/Z");

  // Functional coverage
  cover property (op==2'b00 && (sum5[4]==0)); // add no carry
  cover property (op==2'b00 && (sum5[4]==1)); // add carry
  cover property (op==2'b01 && !(num1<num2)); // sub no borrow
  cover property (op==2'b01 &&  (num1<num2)); // sub borrow
  cover property (op==2'b10 && (|prod8[7:4])==0); // mul no overflow
  cover property (op==2'b10 && (|prod8[7:4])==1); // mul overflow
  cover property (op==2'b11 && (num2!=0)); // normal division
  cover property (op==2'b11 && (num2==0)); // divide by zero

endmodule

// Bind into DUT
bind calculator calc_sva u_calc_sva(.clk(clk), .rst(rst), .op(op), .num1(num1), .num2(num2), .result(result), .overflow(overflow));

// SVA for binary_counter: concise, high-quality checks and coverage

module binary_counter_sva #(parameter COUNTER_WIDTH=8)
(
  input logic                     clk,
  input logic                     rst,
  input logic [COUNTER_WIDTH-1:0] count
);

  default clocking cb @(posedge clk); endclocking

  // Track past-valid to safely use $past
  logic past_valid;
  initial past_valid = 1'b0;
  always @(posedge clk) past_valid <= 1'b1;

  localparam logic [COUNTER_WIDTH-1:0] MAX = {COUNTER_WIDTH{1'b1}};

  // Sanity: no X/Z on key signals
  a_no_x_rst:   assert property (! $isunknown(rst));
  a_no_x_count: assert property (! $isunknown(count));

  // Single functional next-state check (captures reset and increment w/ wrap)
  // count_next == (rst_prev ? 0 : count_prev + 1)
  a_functional: assert property ( disable iff (!past_valid)
                                  count == ( $past(rst) ? '0 : $past(count) + 1 ) );

  // Coverage: reset clears, normal increment, and wrap-around observed
  c_reset_clear: cover property ( $rose(rst) ##1 (count == '0) );
  c_increment:   cover property ( disable iff (!past_valid || rst)
                                  count == $past(count) + 1 );
  c_wrap:        cover property ( disable iff (!past_valid || rst)
                                  ($past(count) == MAX) && (count == '0) );

endmodule

// Bind to DUT
bind binary_counter
  binary_counter_sva #(.COUNTER_WIDTH(COUNTER_WIDTH))
  binary_counter_sva_i (.clk(clk), .rst(rst), .count(count));

// SVA checker for decoder_4_to_16
module decoder_4_to_16_sva (
  input logic [1:0]  AB,
  input logic [15:0] Y
);

  // Inputs/outputs must be 2-state
  assert property (@(AB or Y) !$isunknown(AB)) else $error("AB has X/Z");
  assert property (@(AB or Y) !$isunknown(Y))  else $error("Y has X/Z");

  // Output shape: only one of Y[3:0] is 1, upper bits must be 0
  assert property (@(AB or Y) 1'b1 |-> ##0 $onehot(Y[3:0]))
    else $error("Y[3:0] not onehot");
  assert property (@(AB or Y) 1'b1 |-> ##0 (Y[15:4] == '0))
    else $error("Y[15:4] not zero");

  // Forward decode: AB -> Y
  assert property (@(AB or Y) (AB==2'b00) |-> ##0 (Y==16'h0001))
    else $error("AB=00 did not produce Y=0001");
  assert property (@(AB or Y) (AB==2'b01) |-> ##0 (Y==16'h0002))
    else $error("AB=01 did not produce Y=0002");
  assert property (@(AB or Y) (AB==2'b10) |-> ##0 (Y==16'h0004))
    else $error("AB=10 did not produce Y=0004");
  assert property (@(AB or Y) (AB==2'b11) |-> ##0 (Y==16'h0008))
    else $error("AB=11 did not produce Y=0008");

  // Reverse decode: Y -> AB (no aliasing)
  assert property (@(AB or Y) (Y==16'h0001) |-> ##0 (AB==2'b00))
    else $error("Y=0001 not paired with AB=00");
  assert property (@(AB or Y) (Y==16'h0002) |-> ##0 (AB==2'b01))
    else $error("Y=0002 not paired with AB=01");
  assert property (@(AB or Y) (Y==16'h0004) |-> ##0 (AB==2'b10))
    else $error("Y=0004 not paired with AB=10");
  assert property (@(AB or Y) (Y==16'h0008) |-> ##0 (AB==2'b11))
    else $error("Y=0008 not paired with AB=11");

  // Coverage: all decode cases observed
  cover property (@(AB or Y) (AB==2'b00) ##0 (Y==16'h0001));
  cover property (@(AB or Y) (AB==2'b01) ##0 (Y==16'h0002));
  cover property (@(AB or Y) (AB==2'b10) ##0 (Y==16'h0004));
  cover property (@(AB or Y) (AB==2'b11) ##0 (Y==16'h0008));

endmodule

// Bind into DUT
bind decoder_4_to_16 decoder_4_to_16_sva dec_sva (.AB(AB), .Y(Y));

