module adder_mux (
    input [3:0] a,
    input [3:0] b,
    input control,
    output [3:0] sum
);

    wire [3:0] sum1, sum2;

    // First 4-bit adder
    four_bit_adder adder1(.a(a), .b(b), .sum(sum1));

    // Second 4-bit adder
    four_bit_adder adder2(.a(a), .b(b), .sum(sum2));

    // 2-to-1 multiplexer
    assign sum = control ? sum2 : sum1;

endmodule

module four_bit_adder (
    input [3:0] a,
    input [3:0] b,
    output [3:0] sum
);

    wire c1, c2, c3;

    full_adder adder0(.a(a[0]), .b(b[0]), .cin(0), .sum(sum[0]), .cout(c1));
    full_adder adder1(.a(a[1]), .b(b[1]), .cin(c1), .sum(sum[1]), .cout(c2));
    full_adder adder2(.a(a[2]), .b(b[2]), .cin(c2), .sum(sum[2]), .cout(c3));
    full_adder adder3(.a(a[3]), .b(b[3]), .cin(c3), .sum(sum[3]), .cout());

endmodule

module full_adder (
    input a,
    input b,
    input cin,
    output sum,
    output cout
);

    assign sum = a ^ b ^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);

endmodule

sva_code:
// SVA checkers and binds for adder_mux design
// Focused, concise, and with key functional coverage

// Checker for top-level adder_mux (checks muxing and end-to-end sum)
module adder_mux_sva (
  input  logic [3:0] a,
  input  logic [3:0] b,
  input  logic       control,
  input  logic [3:0] sum,
  input  logic [3:0] sum1,
  input  logic [3:0] sum2
);
  logic [4:0] exp;
  always_comb begin
    exp = a + b;

    // Functional correctness
    assert (#0 (sum1 === exp[3:0])) else $error("adder_mux: sum1 != a+b");
    assert (#0 (sum2 === exp[3:0])) else $error("adder_mux: sum2 != a+b");
    assert (#0 (sum1 === sum2))     else $error("adder_mux: sum1 != sum2");
    assert (#0 (sum  === (control ? sum2 : sum1))) else $error("adder_mux: mux select mismatch");
    assert (#0 (sum  === exp[3:0])) else $error("adder_mux: sum != a+b");

    // X-propagation sanity
    if (!$isunknown({a,b,control})) assert (#0 !$isunknown(sum)) else $error("adder_mux: known inputs -> X/Z sum");

    // Coverage
    cover (control == 0);
    cover (control == 1);
    cover (exp[4] == 1'b1);       // overflow occurred
    cover (exp[3:0] == 4'h0);     // zero result
    cover (exp[3:0] == 4'hF);     // max result
  end
endmodule

// Checker for four_bit_adder (end-to-end and ripple-carry bit relations)
module four_bit_adder_sva (
  input  logic [3:0] a,
  input  logic [3:0] b,
  input  logic [3:0] sum,
  input  logic       c1,
  input  logic       c2,
  input  logic       c3
);
  logic [4:0] exp;
  logic       c1_exp, c2_exp, c3_exp;
  always_comb begin
    exp    = a + b;
    c1_exp = a[0] & b[0];
    c2_exp = (a[1] & b[1]) | (a[1] & c1_exp) | (b[1] & c1_exp);
    c3_exp = (a[2] & b[2]) | (a[2] & c2_exp) | (b[2] & c2_exp);

    // End-to-end
    assert (#0 (sum === exp[3:0])) else $error("four_bit_adder: sum != a+b");

    // Ripple-carry structure
    assert (#0 (sum[0] === (a[0] ^ b[0]))) else $error("four_bit_adder: sum[0] mismatch");
    assert (#0 (c1     === c1_exp))        else $error("four_bit_adder: c1 mismatch");
    assert (#0 (sum[1] === (a[1] ^ b[1] ^ c1))) else $error("four_bit_adder: sum[1] mismatch");
    assert (#0 (c2     === c2_exp))        else $error("four_bit_adder: c2 mismatch");
    assert (#0 (sum[2] === (a[2] ^ b[2] ^ c2))) else $error("four_bit_adder: sum[2] mismatch");
    assert (#0 (c3     === c3_exp))        else $error("four_bit_adder: c3 mismatch");
    assert (#0 (sum[3] === (a[3] ^ b[3] ^ c3))) else $error("four_bit_adder: sum[3] mismatch");

    // X-propagation sanity
    if (!$isunknown({a,b})) assert (#0 !$isunknown(sum)) else $error("four_bit_adder: known inputs -> X/Z sum");

    // Coverage
    cover (exp[4] == 1'b1);       // overflow out of MSB
    cover (exp[3:0] == 4'h0);
    cover (exp[3:0] == 4'hF);
  end
endmodule

// Checker for full_adder (truth table and X checks)
module full_adder_sva (
  input  logic a,
  input  logic b,
  input  logic cin,
  input  logic sum,
  input  logic cout
);
  always_comb begin
    // Functional truth
    assert (#0 (sum  === (a ^ b ^ cin)))                       else $error("full_adder: sum mismatch");
    assert (#0 (cout === ((a & b) | (a & cin) | (b & cin))))   else $error("full_adder: cout mismatch");

    // X-propagation sanity
    if (!$isunknown({a,b,cin})) assert (#0 !$isunknown({sum,cout})) else $error("full_adder: known inputs -> X/Z outputs");

    // Coverage: all 8 input combinations
    cover ({a,b,cin} == 3'b000);
    cover ({a,b,cin} == 3'b001);
    cover ({a,b,cin} == 3'b010);
    cover ({a,b,cin} == 3'b011);
    cover ({a,b,cin} == 3'b100);
    cover ({a,b,cin} == 3'b101);
    cover ({a,b,cin} == 3'b110);
    cover ({a,b,cin} == 3'b111);
  end
endmodule

// Bind the checkers into the DUT hierarchy
bind adder_mux     adder_mux_sva      u_adder_mux_sva      (.a(a), .b(b), .control(control), .sum(sum), .sum1(sum1), .sum2(sum2));
bind four_bit_adder four_bit_adder_sva u_four_bit_adder_sva (.a(a), .b(b), .sum(sum), .c1(c1), .c2(c2), .c3(c3));
bind full_adder    full_adder_sva     u_full_adder_sva     (.a(a), .b(b), .cin(cin), .sum(sum), .cout(cout));

// SVA for mux4to1
module mux4to1_sva (
  input  in0, in1, in2, in3,
  input  sel0, sel1,
  input  out,
  inout  VPWR, VGND, VPB, VNB
);

  default clocking cb @(*); endclocking

  wire power_good = (VPWR===1'b1) && (VGND===1'b0) && (VPB===1'b1) && (VNB===1'b0);

  // Functional correctness when all relevant signals are known
  assert property (power_good && !$isunknown({sel1,sel0,in0,in1,in2,in3}) |->
                   out == (sel1 ? (sel0 ? in0 : in1) : (sel0 ? in2 : in3)));

  // Output maps to selected input (redundant but debuggable per case)
  assert property (power_good &&  sel1 &&  sel0 && !$isunknown(in0) |->
                   out == in0);
  assert property (power_good &&  sel1 && !sel0 && !$isunknown(in1) |->
                   out == in1);
  assert property (power_good && !sel1 &&  sel0 && !$isunknown(in2) |->
                   out == in2);
  assert property (power_good && !sel1 && !sel0 && !$isunknown(in3) |->
                   out == in3);

  // Output is not X/Z unless some input/select is X/Z
  assert property (power_good && $isunknown(out) |->
                   $isunknown({sel1,sel0,in0,in1,in2,in3}));

  // Out changes only due to a data/select change (no spurious glitches)
  assert property (power_good && $changed(out) |->
                   $changed(sel0) || $changed(sel1) ||
                   $changed(in0)  || $changed(in1)  ||
                   $changed(in2)  || $changed(in3));

  // Unselected inputs do not influence output
  assert property (power_good &&  sel1 &&  sel0 &&
                   ($changed(in1) || $changed(in2) || $changed(in3)) &&
                   $stable(sel1) && $stable(sel0) && $stable(in0) |->
                   $stable(out));
  assert property (power_good &&  sel1 && !sel0 &&
                   ($changed(in0) || $changed(in2) || $changed(in3)) &&
                   $stable(sel1) && $stable(sel0) && $stable(in1) |->
                   $stable(out));
  assert property (power_good && !sel1 &&  sel0 &&
                   ($changed(in0) || $changed(in1) || $changed(in3)) &&
                   $stable(sel1) && $stable(sel0) && $stable(in2) |->
                   $stable(out));
  assert property (power_good && !sel1 && !sel0 &&
                   ($changed(in0) || $changed(in1) || $changed(in2)) &&
                   $stable(sel1) && $stable(sel0) && $stable(in3) |->
                   $stable(out));

  // Coverage: each select combination seen
  cover property (power_good &&  sel1 &&  sel0);
  cover property (power_good &&  sel1 && !sel0);
  cover property (power_good && !sel1 &&  sel0);
  cover property (power_good && !sel1 && !sel0);

  // Coverage: propagation when selected input toggles
  cover property (power_good &&  sel1 &&  sel0 ##1 $changed(in0) && $stable(sel1) && $stable(sel0) ##0 out==in0);
  cover property (power_good &&  sel1 && !sel0 ##1 $changed(in1) && $stable(sel1) && $stable(sel0) ##0 out==in1);
  cover property (power_good && !sel1 &&  sel0 ##1 $changed(in2) && $stable(sel1) && $stable(sel0) ##0 out==in2);
  cover property (power_good && !sel1 && !sel0 ##1 $changed(in3) && $stable(sel1) && $stable(sel0) ##0 out==in3);

endmodule

bind mux4to1 mux4to1_sva mux4to1_sva_i (.*);

