// SVA for counter
module counter_sva #(parameter WIDTH=4) (
  input clk,
  input reset,
  input [WIDTH-1:0] count
);
  default clocking cb @(posedge clk); endclocking

  // No X/Z on key signals
  a_no_x: assert property (!$isunknown({reset, count}));

  // Synchronous reset drives zero each cycle it's asserted (and while held)
  a_sync_reset_zero: assert property (reset |-> (count == '0));
  a_reset_hold_zero: assert property (reset && $past(reset,1,1'b0) |-> (count == '0));

  // Increment by 1 when not in reset (with wrap)
  a_inc_or_wrap: assert property ($past(!reset,1,1'b0) && !reset |-> 
                                  ((count == $past(count,1,'0) + 1) ||
                                   ($past(count,1,'0) == {WIDTH{1'b1}} && count == '0)));

  // First cycle after reset deasserts -> count is 1
  a_post_reset_one: assert property ($past(reset,1,1'b0) && !reset |-> 
                                     (count == {{(WIDTH-1){1'b0}},1'b1}));

  // Coverage: observe wraparound
  c_wrap: cover property ($past(!reset,1,1'b0) && $past(count,1,'0) == {WIDTH{1'b1}} && count == '0);
endmodule


// SVA for counter_top
module counter_top_sva (
  input clk,
  input reset,
  input [4:0] count,
  input [3:0] count1,
  input [3:0] count2
);
  default clocking cb @(posedge clk); endclocking

  a_no_x: assert property (!$isunknown({reset, count1, count2, count}));

  // Top-level count equals previous-cycle sum of sub-counters (due to NBA ordering)
  a_sum_prev: assert property (count == $past(count1,1,4'h0) + $past(count2,1,4'h0));

  // Legal range: sum of two 4-bit counters never exceeds 30
  a_range: assert property (count <= 5'd30);

  // Coverage: both counters wrap (sum=30), and both at zero (sum=0)
  c_both_wrap_to_30: cover property ($past(count1,1,4'h0)==4'hF && $past(count2,1,4'h0)==4'hF && count==5'd30);
  c_both_zero_to_zero: cover property ($past(count1,1,4'h0)==4'h0 && $past(count2,1,4'h0)==4'h0 && count==5'd0);
endmodule


// Bind SVA into DUTs
bind counter     counter_sva    #(.WIDTH(4)) counter_sva_b     (.clk(clk), .reset(reset), .count(count));
bind counter_top counter_top_sva               counter_top_sva_b(.clk(clk), .reset(reset), .count(count), .count1(count1), .count2(count2));

// SVA for four_input_nand and nand4bb
package four_input_nand_sva_pkg;

  // Leaf-cell checker
  module nand4bb_sva (
    input logic A_N, B_N, C, D, Y, VPWR, VGND
  );
    wire pwr_good = (VPWR===1'b1 && VGND===1'b0);

    // Functional equivalence and X-prop sanity under good power
    assert property (@(A_N or B_N or C or D or VPWR or VGND)
      pwr_good |-> (Y === ~(A_N & B_N & C & D)));

    assert property (@(A_N or B_N or C or D or VPWR or VGND)
      pwr_good && !$isunknown({A_N,B_N,C,D}) |-> !$isunknown(Y));

    // Simple output-state coverage
    cover property (@(A_N or B_N or C or D or VPWR or VGND) pwr_good && (Y==1'b1));
    cover property (@(A_N or B_N or C or D or VPWR or VGND) pwr_good && (Y==1'b0));
  endmodule

  // Top-level checker (binds to internal temps)
  module four_input_nand_sva (
    input logic A_N, B_N, C, D, Y, VPWR, VGND,
    input logic temp1, temp2, temp3
  );
    wire pwr_good = (VPWR===1'b1 && VGND===1'b0);

    // Full chain correctness and simplified function (Y == A_N & B_N & C & D)
    assert property (@(A_N or B_N or C or D or VPWR or VGND or temp1 or temp2 or temp3)
      pwr_good |->
        (temp1 === ~(A_N & B_N & C & D)) &&
        (temp2 === ~temp1) &&
        (temp3 === ~temp2) &&
        (Y     === ~temp3) &&
        (Y     === (A_N & B_N & C & D)));

    // Known-in -> known-out
    assert property (@(A_N or B_N or C or D or VPWR or VGND)
      pwr_good && !$isunknown({A_N,B_N,C,D}) |-> !$isunknown(Y));

    // Input toggle coverage
    cover property (@(A_N) pwr_good && $rose(A_N));
    cover property (@(A_N) pwr_good && $fell(A_N));
    cover property (@(B_N) pwr_good && $rose(B_N));
    cover property (@(B_N) pwr_good && $fell(B_N));
    cover property (@(C)   pwr_good && $rose(C));
    cover property (@(C)   pwr_good && $fell(C));
    cover property (@(D)   pwr_good && $rose(D));
    cover property (@(D)   pwr_good && $fell(D));

    // Full 16-combo input coverage (concise)
    covergroup cg_inputs @(A_N or B_N or C or D);
      option.per_instance = 1;
      A: coverpoint A_N iff (pwr_good) { bins b0 = {0}; bins b1 = {1}; }
      B: coverpoint B_N iff (pwr_good) { bins b0 = {0}; bins b1 = {1}; }
      Cc: coverpoint C   iff (pwr_good) { bins b0 = {0}; bins b1 = {1}; }
      Dd: coverpoint D   iff (pwr_good) { bins b0 = {0}; bins b1 = {1}; }
      AXBXCXD: cross A, B, Cc, Dd;
    endgroup
    cg_inputs cg = new();

    // Power-good observed at least once
    cover property (@(VPWR or VGND) pwr_good);
  endmodule

endpackage

// Bind checkers
bind nand4bb       four_input_nand_sva_pkg::nand4bb_sva        u_nand4bb_sva (.*);
bind four_input_nand four_input_nand_sva_pkg::four_input_nand_sva u_four_input_nand_sva (.*);

// SVA for DLATCHR
module DLATCHR_sva (
  input logic D,
  input logic nCLK,
  input logic nRST,
  input logic INIT,
  input logic Q
);

  default clocking cb @(posedge nCLK); endclocking

  // Functional correctness: Q equals the mux of prior-cycle inputs
  assert property ($past(1'b1) |-> (Q == $past(nRST ? D : INIT)));

  // Inputs known at sampling; Q known after first sampled cycle
  assert property (!$isunknown({nRST, D, INIT}));
  assert property ($past(1'b1) |-> !$isunknown(Q));

  // Q changes only on clock edges (no glitches)
  property q_changes_only_on_clk;
    @(posedge nCLK or posedge Q or negedge Q)
      $changed(Q) |-> $rose(nCLK);
  endproperty
  assert property (q_changes_only_on_clk);

  // Coverage: exercise reset load, data capture, and reset release then capture
  cover property (!nRST ##1 (Q == $past(INIT)));
  cover property ( nRST ##1 (Q == $past(D)));
  cover property (!nRST ##1 nRST ##1 (Q == $past(D)));

endmodule

bind DLATCHR DLATCHR_sva sva_i (.D(D), .nCLK(nCLK), .nRST(nRST), .INIT(INIT), .Q(Q));

