module test(
    input a1,
    input s1,
    input s2,
    input s3,
    output i1,
    output i2,
    output i3,
    output i4,
    output i5,
    output i6,
    output i7,
    output i8
);

// Logic to generate the outputs based on the inputs
assign i1 = a1 & s1;
assign i2 = a1 & s2;
assign i3 = a1 & s3;
assign i4 = ~a1 & s1;
assign i5 = ~a1 & s2;
assign i6 = ~a1 & s3;
assign i7 = s1 & s2 & s3;
assign i8 = ~a1 & ~s1 & ~s2 & ~s3;

endmodule

sva_code:
// SVA bind module for test
module test_sva(
  input logic a1, s1, s2, s3,
  input logic i1, i2, i3, i4, i5, i6, i7, i8
);

  // Functional equivalence (golden equations)
  always_comb begin
    assert (i1 === (a1 &  s1)) else $error("i1 mismatch");
    assert (i2 === (a1 &  s2)) else $error("i2 mismatch");
    assert (i3 === (a1 &  s3)) else $error("i3 mismatch");
    assert (i4 === (~a1 & s1)) else $error("i4 mismatch");
    assert (i5 === (~a1 & s2)) else $error("i5 mismatch");
    assert (i6 === (~a1 & s3)) else $error("i6 mismatch");
    assert (i7 === (s1 & s2 & s3)) else $error("i7 mismatch");
    assert (i8 === (~a1 & ~s1 & ~s2 & ~s3)) else $error("i8 mismatch");
  end

  // Pair coherence: for each sN, exactly one of the pair is 1 when sN==1, else both 0
  always_comb begin
    assert (s1 ? (i1 ^ i4) : !(i1 || i4)) else $error("s1/i1/i4 coherence");
    assert (s2 ? (i2 ^ i5) : !(i2 || i5)) else $error("s2/i2/i5 coherence");
    assert (s3 ? (i3 ^ i6) : !(i3 || i6)) else $error("s3/i3/i6 coherence");
  end

  // Global sanity
  always_comb begin
    assert (!(i7 && i8)) else $error("i7 and i8 cannot be 1 together");
  end

  // Optional X/Z check on outputs once inputs are known
  always_comb begin
    if (!$isunknown({a1,s1,s2,s3})) begin
      assert (!$isunknown({i1,i2,i3,i4,i5,i6,i7,i8})) else $error("X/Z on outputs");
    end
  end

  // Coverage: hit every output high, all-zeros case, and i7 with both a1 polarities
  always_comb begin
    cover (i1); cover (i2); cover (i3); cover (i4); cover (i5); cover (i6); cover (i7); cover (i8);
    cover (!i1 && !i2 && !i3 && !i4 && !i5 && !i6 && !i7 && !i8); // a1=1,s1=s2=s3=0
    cover (i7 &&  a1);
    cover (i7 && !a1);
  end

endmodule

// Bind into DUT
bind test test_sva u_test_sva (.*);

// SVA for reg32_async_reset_load
// Bind this file to the DUT for checks and coverage

module reg32_async_reset_load_sva (
  input clk,
  input reset,
  input load,
  input [31:0] data_in,
  input [31:0] data_out
);

  default clocking cb @(posedge clk); endclocking

  // Asynchronous reset drives 0 immediately
  property p_async_reset_immediate;
    @(negedge reset) data_out == 32'h0;
  endproperty
  assert property (p_async_reset_immediate);

  // While in reset, next sampled value is 0 (covers posedge clk during reset)
  assert property (@(posedge clk) !reset |=> data_out == 32'h0);

  // Reset dominates load at clock edge
  assert property (@(posedge clk) (!reset && load) |=> data_out == 32'h0);

  // Synchronous load capture when out of reset
  assert property (@(posedge clk) disable iff (!reset)
                   load |=> data_out == $past(data_in));

  // Hold when no load and out of reset
  assert property (@(posedge clk) disable iff (!reset)
                   !load |=> data_out == $past(data_out));

  // Output is known when out of reset
  assert property (@(posedge clk) reset |-> !$isunknown(data_out));

  // Inputs are known at sampling
  assert property (@(posedge clk) !$isunknown({reset,load}));

  // On reset release, first sampled value remains 0
  assert property (@(posedge clk) $rose(reset) |-> data_out == 32'h0);

  // Coverage
  cover property (@(negedge reset) 1);                                  // reset asserted
  cover property (@(posedge clk) !reset ##1 reset);                      // reset release
  cover property (@(posedge clk) disable iff (!reset) load);             // a write
  cover property (@(posedge clk) disable iff (!reset) load ##1 load);    // back-to-back writes
  cover property (@(posedge clk) disable iff (!reset) !load [*2]);       // hold for 2+ cycles
  cover property (@(posedge clk) disable iff (!reset)
                  load && data_in == 32'hFFFF_FFFF);                     // write max
  cover property (@(posedge clk) disable iff (!reset)
                  load && data_in == 32'hA5A5_A5A5);                     // write pattern

endmodule

bind reg32_async_reset_load reg32_async_reset_load_sva sva_inst (.*);

