// SVA for pulse_detection
module pulse_detection_sva #(
  parameter int unsigned CNT_HIT = 32'd100000000,
  parameter int unsigned DIV     = 32'd100000
)(
  input logic               clk,
  input logic               reset,
  // DUT I/Os and internals (bind by name)
  input logic [31:0]        in,
  input logic [15:0]        threshold,
  input logic [15:0]        frequency,
  input logic               threshold_exceeded,
  input logic [31:0]        count,
  input logic [3:0]         prescaler,
  input logic [31:0]        prev_in,
  input logic [31:0]        curr_in
);

  default clocking cb @(posedge clk); endclocking
  default disable iff (reset)

  // Shorthands
  let sample = (prescaler == 4'd0);                // sampling cycle
  let rise   = (prev_in == 32'd0 && curr_in == 32'd1); // rising detect per RTL

  // Async reset clears (checked during reset)
  assert property (@(posedge clk) reset |-> (count==0 && prescaler==0 && prev_in==0 && curr_in==0 && frequency==0 && threshold_exceeded==0));

  // Prescaler range and behavior
  assert property (prescaler inside {[4'd0:4'd15]});
  assert property ( sample  |=> prescaler == 4'd15);
  assert property (!sample  |=> prescaler == $past(prescaler) - 4'd1);
  assert property ( sample  |-> !sample[*15] ##1 sample); // exactly 16-cycle period between samples

  // Sampling of inputs
  assert property ( sample  |=> (prev_in == $past(curr_in) && curr_in == $past(in)));
  assert property (!sample  |=> (prev_in == $past(prev_in) && curr_in == $past(curr_in)));

  // Count progression (no threshold event this cycle)
  assert property ( (count < CNT_HIT && sample && rise)         |=> count == $past(count) + 32'd1 );
  assert property ( (count < CNT_HIT && !(sample && rise))      |=> count == $past(count)        );

  // Threshold event: uses pre-state count per RTL, resets count and updates frequency
  assert property ( (count >= CNT_HIT) |=> (count == 0) );
  assert property ( (count >= CNT_HIT) |=> (frequency == ($past(count) / DIV)) );
  // threshold_exceeded is driven from pre-update frequency per RTL
  assert property ( (count >= CNT_HIT) |=> (threshold_exceeded == ($past(frequency) > threshold)) );

  // No spurious updates when no threshold event
  assert property ( (count < CNT_HIT) |=> (frequency == $past(frequency)) );
  assert property ( (count < CNT_HIT) |=> (threshold_exceeded == $past(threshold_exceeded)) );

  // Any count change must be a valid increment or a threshold reset
  assert property (
    (count != $past(count)) |->
      ( ($past(count) < CNT_HIT && sample && rise && count == $past(count)+32'd1)
        || ($past(count) >= CNT_HIT && count == 32'd0) )
  );

  // Coverage
  cover property (sample && rise);                        // a detected pulse at a sample
  cover property (sample ##[15:15] sample);               // prescaler wrap period observed
  cover property ((count >= CNT_HIT));                    // threshold event occurs
  cover property ((count >= CNT_HIT) ##1 !threshold_exceeded); // threshold_exceeded=0 path
  cover property ((count >= CNT_HIT) ##1  threshold_exceeded); // threshold_exceeded=1 path

endmodule

bind pulse_detection pulse_detection_sva sva_inst (.*);

// SVA for adder — concise, high-quality checks and coverage
// Bind this to the DUT: bind adder adder_sva #(8) sva_i (.*);

module adder_sva #(parameter int W = 8)
(
  input  logic signed [W-1:0] A,
  input  logic signed [W-1:0] B,
  input  logic signed [W-1:0] sum,
  input  logic                C
);

  // Helper constants for coverage
  localparam logic signed [W-1:0] MAX = {1'b0, {(W-1){1'b1}}}; // +2^(W-1)-1
  localparam logic signed [W-1:0] MIN = {1'b1, {(W-1){1'b0}}}; // -2^(W-1)

  // 1) Outputs are fully determined by inputs (no X/Z when inputs known)
  ap_known_out: assert property (@(A or B)
                                 !$isunknown({A,B}) |-> ##0 !$isunknown({sum,C}))
    else $error("adder: X/Z on outputs with known inputs");

  // 2) Functional correctness: 9-bit packed sum must equal signed A+B
  ap_full_sum:  assert property (@(A or B)
                                 !$isunknown({A,B}) |-> ##0 {C,sum} == ($signed(A)+$signed(B)))
    else $error("adder: {C,sum} != signed(A)+signed(B)");

  // 3) Signed-overflow relationship: C^sum[MSB] indicates overflow for signed add
  ap_sovf_rel:  assert property (@(A or B)
                                 !$isunknown({A,B}) |-> ##0
                                 (C ^ sum[W-1]) == (( A[W-1] &  B[W-1] & ~sum[W-1]) |
                                                    (~A[W-1] & ~B[W-1] &  sum[W-1])))
    else $error("adder: signed-overflow relation violated");

  // Optional sanity: opposite-sign add implies no signed overflow
  ap_opp_sign_no_ovf: assert property (@(A or B)
                                       !$isunknown({A,B}) |-> ##0
                                       (A[W-1] ^ B[W-1]) |-> (C == sum[W-1]))
    else $error("adder: opposite-sign add should not overflow");

  // -------- Coverage --------
  // Positive overflow: + + -> negative result bit
  cv_pos_ovf:  cover property (@(A or B) !$isunknown({A,B}) ##0
                               ( A[W-1]==0 && B[W-1]==0 && sum[W-1]==1 ));

  // Negative overflow: - - -> positive result bit
  cv_neg_ovf:  cover property (@(A or B) !$isunknown({A,B}) ##0
                               ( A[W-1]==1 && B[W-1]==1 && sum[W-1]==0 ));

  // Opposite-sign addition (no overflow expected)
  cv_opp_sign: cover property (@(A or B) !$isunknown({A,B}) ##0
                               ( A[W-1]^B[W-1] && (C==sum[W-1]) ));

  // Zero result case
  cv_zero:     cover property (@(A or B) !$isunknown({A,B}) ##0 (sum== '0));

  // Edge cases
  cv_max_plus1: cover property (@(A or B) !$isunknown({A,B}) ##0 (A==MAX && B==1));
  cv_min_minus1:cover property (@(A or B) !$isunknown({A,B}) ##0 (A==MIN && B==-1));

endmodule

// Example bind (uncomment in your TB or a bind file):
// bind adder adder_sva #(8) sva_i (.*);

// SVA for binary_counter
module binary_counter_sva #(parameter WIDTH=4)
(
  input  wire              CLK,
  input  wire              RST,
  input  wire              COUNT_EN,
  input  wire [WIDTH-1:0]  Q
);

  default clocking cb @(posedge CLK); endclocking

  // Sanity: no X/Z on key signals
  a_no_x:         assert property (!$isunknown({RST, COUNT_EN, Q}));

  // Synchronous reset: next cycle must be zero
  a_rst_sync:     assert property (RST |=> Q == '0);

  // Hold when disabled (and not in reset)
  a_hold:         assert property (!RST && !COUNT_EN |=> Q == $past(Q));

  // Increment by 1 mod 2**WIDTH when enabled (and not in reset)
  a_inc:          assert property (!RST && COUNT_EN |=> Q == (($past(Q)+1) % (1<<WIDTH)));

  // Any change must be caused by either reset or enable in prior cycle
  a_change_gated: assert property ((Q != $past(Q)) |-> ($past(RST) || $past(COUNT_EN)));

  // Glitch-free between clocks (output stable away from posedge updates)
  a_no_glitch:    assert property (@(negedge CLK) $stable(Q));

  // Coverage
  c_reset:        cover property (RST |=> Q == '0);
  c_wrap:         cover property (!RST && COUNT_EN && Q == {WIDTH{1'b1}} |=> Q == '0);
  c_inc:          cover property (!RST && COUNT_EN |=> Q == (($past(Q)+1) % (1<<WIDTH)));
  c_en_burst:     cover property (!RST ##1 COUNT_EN[*4]);

endmodule

bind binary_counter binary_counter_sva #(.WIDTH(4)) u_binary_counter_sva (.*);

