  ap_and_dom:  assert property ( (A1 & A2 & A3 & A4) |-> (Y == 1'b0) ) else $error("AND4 dominance fail");
  ap_pass:     assert property ( (!B1 && !(A1 & A2 & A3 & A4)) |-> (Y == 1'b1) ) else $error("pass-through fail");

