  assert property ((C === 1'b0) |-> ##0 (Z === 1'b0))
    else $error("OAI21B2HD4X: C=0 must force Z=0");
  assert property ((C===1'b1 && AN===1'b1 && BN===1'b1) |-> ##0 (Z===1'b0))
