  cover property (@(A or B or C or D) !$isunknown({A,B,C,D}) && $countones({A,B,C,D}) == 1);
  cover property (@(A or B or C or D) !$isunknown({A,B,C,D}) && $countones({A,B,C,D}) == 2);
