  // sel[3]==1 picks din9
  assert property ( sel[3] |-> (dout == din9) );

  // sel[3]==0 selects among din1..din8 via sel[2:0]
  assert property ( !sel[3] && !sel[2] && !sel[1] |-> (dout == (sel[0] ? din2 : din1)) );
  assert property ( !sel[3] && !sel[2] &&  sel[1] |-> (dout == (sel[0] ? din4 : din3)) );
