module RegisterAdd_6
   (add_overflow_flag,
    E,
    O,
    CLK,
    AR);
  output add_overflow_flag;
  input [0:0]E;
  input [0:0]O;
  input CLK;
  input [0:0]AR;

  wire [0:0]AR;
  wire CLK;
  wire [0:0]E;
  wire [0:0]O;
  wire add_overflow_flag;

  reg [0:0] Q_reg;
  always @(posedge CLK or negedge AR)
  begin
    if (!AR)
      Q_reg <= 1'b0;
