module dff_posedge_reset(CLK, D, reset, Q);
input CLK, D, reset;
output Q;
reg Q;

always @(posedge CLK or posedge reset) begin
    if (reset) begin
        Q <= 0;
    end else begin
        Q <= D;
    end
end

endmodule

sva_code:
// SVA for dff_posedge_reset
module dff_posedge_reset_sva(input logic CLK, D, reset, Q);

  // Sample on all controlling events so we can relate reset deassert to next clk
  default clocking cb @(posedge CLK or posedge reset or negedge reset); endclocking

  // Async reset clears immediately and dominates
  ap_async_rst_clear: assert property ( $rose(reset) |-> ##0 (Q == 1'b0) );

  // While reset is asserted, Q stays low (checked at all controlling events)
  ap_q_low_during_reset: assert property ( reset |-> (Q == 1'b0) );

  // On posedge CLK when not in reset, Q reflects the previously-sampled D
  ap_capture_d: assert property ( ($rose(CLK) && !reset) |-> (Q == $past(D)) );

  // After reset deasserts, Q must remain 0 until the next posedge CLK
  ap_hold_zero_until_clk_after_deassert:
    assert property ( $fell(reset) |-> (Q == 1'b0) until_with $rose(CLK) );

  // Basic X checks around controlling events
  ap_q_known_after_events:
    assert property ( (($rose(CLK) && !reset) || $rose(reset)) |-> ##0 !$isunknown(Q) );
  ap_d_known_when_sampled:
    assert property ( ($rose(CLK) && !reset) |-> !$isunknown(D) );

  // Coverage
  cp_reset_pulse:           cover property ( $rose(reset) ##[1:$] $fell(reset) );
  cp_normal_capture:        cover property ( ($rose(CLK) && !reset) && (Q == $past(D)) );
  cp_clk_and_reset_same_ts: cover property ( $rose(reset) && $rose(CLK) );

endmodule

// Example bind (optional):
// bind dff_posedge_reset dff_posedge_reset_sva sva_inst(.CLK(CLK), .D(D), .reset(reset), .Q(Q));

// SVA for counter
module counter_sva (input clk, input rst, input [3:0] count);
  default clocking cb @(posedge clk); endclocking

  bit past_valid, seen_reset;
  initial begin past_valid = 0; seen_reset = 0; end
  always @(posedge clk) begin
    past_valid <= 1'b1;
    if (rst) seen_reset <= 1'b1;
  end

  // Reset behavior
  ap_rst_forces_zero: assert property (past_valid && $past(rst) |-> count == 4'd0);

  // Increment by 1 mod-16 when not in reset
  ap_inc_no_rst: assert property (past_valid && !$past(rst) && !rst |-> count == $past(count + 4'd1));

  // Explicit wrap check (15 -> 0) without reset
  ap_wrap: assert property (past_valid && !$past(rst) && !rst && $past(count)==4'hF |-> count==4'h0);

  // No X/Z on count after a reset has been seen at least once
  ap_no_x_after_reset: assert property (seen_reset |-> !$isunknown(count));

  // Coverage
  cp_reset_assert:  cover property (past_valid && $rose(rst));
  cp_reset_release: cover property (past_valid && $fell(rst));
  cp_wrap_seq:      cover property (disable iff (rst) (count==4'hE ##1 count==4'hF ##1 count==4'h0));
endmodule

bind counter counter_sva sva_i (.*);

verilog_code:
module SimpleCalculator(
    input [3:0] a,
    input [3:0] b,
    input op,
    output [3:0] result
);

    reg [3:0] temp_result;

    always @(*) begin
        if (op == 0) // addition
            temp_result = a + b;
        else // subtraction
            temp_result = a - b;
    end

    assign result = temp_result;

endmodule

sva_code:
// SVA for SimpleCalculator
module SimpleCalculator_sva (
  input  logic [3:0] a,
  input  logic [3:0] b,
  input  logic       op,
  input  logic [3:0] result
);

  // Functional equivalence (combinational correctness)
  // Evaluate after updates (##0) on any relevant change
  assert property (@(a or b or op or result)
                   1'b1 |-> ##0 (result == (op ? (a - b) : (a + b))))
    else $error("Functional mismatch: result != (op ? a-b : a+b)");

  // No spurious output changes when inputs are stable
  assert property (@(a or b or op or result)
                   $stable({a,b,op}) |-> $stable(result))
    else $error("Output changed without input change");

  // X/Z checks: inputs known, and if inputs known then output known
  assert property (@(a or b or op or result)
                   !$isunknown({a,b,op}))
    else $error("Inputs contain X/Z");
  assert property (@(a or b or op or result)
                   (!$isunknown({a,b,op})) |-> !$isunknown(result))
    else $error("Output X/Z with known inputs");

  // Coverage
  // - Both ops seen
  cover property (@(a or b or op) (op == 1'b0));
  cover property (@(a or b or op) (op == 1'b1));
  // - Addition overflow/no-overflow
  cover property (@(a or b or op) (op==1'b0) &&  ({1'b0,a}+{1'b0,b})[4]);
  cover property (@(a or b or op) (op==1'b0) && !({1'b0,a}+{1'b0,b})[4]);
  // - Subtraction underflow/no-underflow
  cover property (@(a or b or op) (op==1'b1) && (a <  b));
  cover property (@(a or b or op) (op==1'b1) && (a >= b));

endmodule

// Bind to DUT
bind SimpleCalculator SimpleCalculator_sva u_simplecalculator_sva (
  .a(a), .b(b), .op(op), .result(result)
);

// SVA checker for mux4x1
module mux4x1_sva(
  input logic A,
  input logic B,
  input logic C,
  input logic D,
  input logic [1:0] S,
  input logic Y
);

  // Functional equivalence (4-state)
  assert property (@(*)
    Y === (S[1] ? (S[0] ? D : C) : (S[0] ? B : A))
  );

  // Correctness when all inputs/select are known (2-state check)
  assert property (@(*)
    !$isunknown({A,B,C,D,S}) |-> (Y == (S[1] ? (S[0] ? D : C) : (S[0] ? B : A)))
  );

  // Per-select mapping (also checks X-propagation from selected input)
  assert property (@(*) (S===2'b00) |-> (Y===A));
  assert property (@(*) (S===2'b01) |-> (Y===B));
  assert property (@(*) (S===2'b10) |-> (Y===C));
  assert property (@(*) (S===2'b11) |-> (Y===D));

  // Non-selected inputs do not affect Y when S is stable
  property nonsel_stable(bit [1:0] sel, logic n1, logic n2, logic n3);
    @(*) (S===sel && $stable(S) && ($changed(n1) || $changed(n2) || $changed(n3))) |-> $stable(Y);
  endproperty
  assert property (nonsel_stable(2'b00, B, C, D));
  assert property (nonsel_stable(2'b01, A, C, D));
  assert property (nonsel_stable(2'b10, A, B, D));
  assert property (nonsel_stable(2'b11, A, B, C));

  // Y follows selected input when S is stable
  property sel_follow(bit [1:0] sel, logic si);
    @(*) (S===sel && $stable(S) && $changed(si)) |-> (Y===si);
  endproperty
  assert property (sel_follow(2'b00, A));
  assert property (sel_follow(2'b01, B));
  assert property (sel_follow(2'b10, C));
  assert property (sel_follow(2'b11, D));

  // Coverage: hit each select, select switches, selected-input propagation, and immunity to non-selected changes
  cover property (@(*) S===2'b00);
  cover property (@(*) S===2'b01);
  cover property (@(*) S===2'b10);
  cover property (@(*) S===2'b11);

  cover property (@(*) !$isunknown(S) && $changed(S));

  cover property (@(*) (S===2'b00 && $stable(S) && $changed(A) && (Y===A)));
  cover property (@(*) (S===2'b01 && $stable(S) && $changed(B) && (Y===B)));
  cover property (@(*) (S===2'b10 && $stable(S) && $changed(C) && (Y===C)));
  cover property (@(*) (S===2'b11 && $stable(S) && $changed(D) && (Y===D)));

  cover property (@(*) (
      (S===2'b00 && $stable(S) && ($changed(B)||$changed(C)||$changed(D)) && $stable(Y)) ||
      (S===2'b01 && $stable(S) && ($changed(A)||$changed(C)||$changed(D)) && $stable(Y)) ||
      (S===2'b10 && $stable(S) && ($changed(A)||$changed(B)||$changed(D)) && $stable(Y)) ||
      (S===2'b11 && $stable(S) && ($changed(A)||$changed(B)||$changed(C)) && $stable(Y))
  ));

endmodule

// Bind into DUT
bind mux4x1 mux4x1_sva u_mux4x1_sva (.A(A), .B(B), .C(C), .D(D), .S(S), .Y(Y));

verilog_code:
module comparator_block #(
  parameter n = 8 // number of bits in input signals
)(
  input [n-1:0] a,
  input [n-1:0] b,
  output gt,
  output lt,
  output eq
);

  wire [n:0] a_ext, b_ext;
  assign a_ext = {1'b0, a};
  assign b_ext = {1'b0, b};

  wire [n:0] a_gt_b, a_lt_b, a_eq_b;
  genvar i;
  generate
    for (i = 0; i <= n; i = i + 1) begin : compare_bits
      assign a_gt_b[i] = a_ext[i] & ~b_ext[i];
      assign a_lt_b[i] = ~a_ext[i] & b_ext[i];
      assign a_eq_b[i] = a_ext[i] == b_ext[i];
    end
  endgenerate

  assign gt = |a_gt_b;
  assign lt = |a_lt_b;
  assign eq = &a_eq_b;

endmodule

sva_code:
// SVA for comparator_block: concise, bindable, and comprehensive

module comparator_block_sva #(
  parameter int N = 8
)(
  input  logic [N-1:0] a,
  input  logic [N-1:0] b,
  input  logic         gt,
  input  logic         lt,
  input  logic         eq
);

  // Parameter sanity
  initial assert (N >= 1)
    else $error("comparator_block_sva: N must be >= 1");

  // Combinational checks guarded against X/Z on inputs
  always_comb begin
    if (!$isunknown({a,b})) begin
      // No X/Z on outputs when inputs are known
      assert (!$isunknown({gt,lt,eq}))
        else $error("Outputs contain X/Z with known inputs");

      // Functional correctness
      assert (eq == (a == b))
        else $error("eq mismatch: expected (a==b)");
      assert (gt == |(a & ~b))
        else $error("gt mismatch: expected |(a & ~b)");
      assert (lt == |(~a & b))
        else $error("lt mismatch: expected |(~a & b)");

      // Relationship among outputs: eq iff neither gt nor lt
      assert (eq == ~(gt | lt))
        else $error("eq must be the inverse of (gt|lt)");

      // Key scenario coverage
      cover (a == b               &&  eq && !gt && !lt); // equality
      cover ((a & ~b) != '0       &&  gt && !lt && !eq); // gt only
      cover ((~a & b) != '0       &&  lt && !gt && !eq); // lt only
      cover ((a & ~b) != '0 && (~a & b) != '0 && gt && lt && !eq); // both gt and lt

      // Boundary/value coverage
      cover (a == '0              && b == '0              && eq);
      cover (a == {N{1'b1}}       && b == '0              && gt && !lt);
      cover (a == '0              && b == {N{1'b1}}       && lt && !gt);
    end
  end

endmodule

// Bind to all instances of comparator_block; inherit the DUT parameter n
bind comparator_block comparator_block_sva #(.N(n)) u_comparator_block_sva (.*);

verilog_code:
module four_way_min (
    input [7:0] a, b, c, d,
    output [7:0] min);

    wire [7:0] ab_min, cd_min, abcd_min;

    assign ab_min = (a < b) ? a : b;
    assign cd_min = (c < d) ? c : d;
    assign abcd_min = (ab_min < cd_min) ? ab_min : cd_min;
    assign min = abcd_min;

endmodule

sva_code:
// SVA checker for four_way_min (bindable, clockless, concise yet thorough)
module four_way_min_sva
  #(parameter WIDTH=8)
  (input  logic [WIDTH-1:0] a, b, c, d,
   input  logic [WIDTH-1:0] min,
   input  logic [WIDTH-1:0] ab_min, cd_min, abcd_min);

  // 2-way and 4-way mins (use 4-state-aware '<'; gated by known inputs)
  function automatic logic [WIDTH-1:0] f_min2 (input logic [WIDTH-1:0] x, y);
    return (x < y) ? x : y;
  endfunction
  function automatic logic [WIDTH-1:0] f_min4 (input logic [WIDTH-1:0] w, x, y, z);
    return f_min2(f_min2(w, x), f_min2(y, z));
  endfunction

  // End-to-end correctness when inputs are known
  property p_min_correct;
    @(a or b or c or d or min)
      !$isunknown({a,b,c,d}) |-> (min == f_min4(a,b,c,d));
  endproperty
  assert property (p_min_correct);

  // Stage-wise correctness (also gated for known operands)
  assert property (@(a or b or ab_min)           !$isunknown({a,b})           |-> (ab_min   == f_min2(a,b)));
  assert property (@(c or d or cd_min)           !$isunknown({c,d})           |-> (cd_min   == f_min2(c,d)));
  assert property (@(ab_min or cd_min or abcd_min) !$isunknown({ab_min,cd_min}) |-> (abcd_min == f_min2(ab_min,cd_min)));
  assert property (@(abcd_min or min)            !$isunknown(abcd_min)        |-> (min      == abcd_min));

  // Sanity: min is no greater than each input when inputs are known
  assert property (@(a or b or c or d or min)
                   !$isunknown({a,b,c,d}) |-> (min <= a && min <= b && min <= c && min <= d));

  // ----------------------------------
  // Coverage (branching, winners, ties)
  // ----------------------------------

  // Pairwise comparator branching
  cover property (@(a or b) !$isunknown({a,b}) && (a <  b));
  cover property (@(a or b) !$isunknown({a,b}) && (a >= b));
  cover property (@(c or d) !$isunknown({c,d}) && (c <  d));
  cover property (@(c or d) !$isunknown({c,d}) && (c >= d));

  // Second-stage comparator outcomes
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) &&
                  (f_min2(a,b) <  f_min2(c,d)));
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) &&
                  (f_min2(a,b) == f_min2(c,d)));
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) &&
                  (f_min2(a,b) >  f_min2(c,d)));

  // Unique winners (strict minima)
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (a<b && a<c && a<d) && (min==a));
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (b<a && b<c && b<d) && (min==b));
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (c<a && c<b && c<d) && (min==c));
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (d<a && d<b && d<c) && (min==d));

  // Tie behaviors per implementation (< prefers right operand on tie)
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (a==b) && (a<c) && (a<d) && (min==b)); // ab tie -> pick b
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (c==d) && (c<a) && (c<b) && (min==d)); // cd tie -> pick d

  // All equal
  cover property (@(a or b or c or d) !$isunknown({a,b,c,d}) && (a==b && b==c && c==d) && (min==a));

endmodule

// Bind into the DUT; connects to internals by name
bind four_way_min four_way_min_sva #(.WIDTH(8)) four_way_min_sva_i (.*);

verilog_code:
module AddressGenerator(input clk, input ce,
                        input [4:0] Operation, 
                        input [1:0] MuxCtrl,
                        input [7:0] DataBus, T, X, Y,
                        output [15:0] AX,
                        output Carry);
  // Actual contents of registers
  reg [7:0] AL, AH;
  // Last operation generated a carry?
  reg SavedCarry;
  assign AX = {AH, AL};

  wire [2:0] ALCtrl = Operation[4:2];
  wire [1:0] AHCtrl = Operation[1:0];

  // Possible new value for AL.
  wire [7:0] NewAL;
  assign {Carry,NewAL} = {1'b0, (MuxCtrl[1] ? T : AL)} + {1'b0, (MuxCtrl[0] ? Y : X)};

  // The other one
  wire TmpVal = (!AHCtrl[1] | SavedCarry);
  wire [7:0] TmpAdd = (AHCtrl[1] ? AH : AL) + {7'b0, TmpVal};

  always @(posedge clk) if (ce) begin
    SavedCarry <= Carry;
    if (ALCtrl[2])
      case(ALCtrl[1:0])
      0: AL <= NewAL;
      1: AL <= DataBus;
      2: AL <= TmpAdd;
      3: AL <= T;
      endcase

    case(AHCtrl[1:0])
    0: AH <= AH;
    1: AH <= 0;
    2: AH <= TmpAdd;
    3: AH <= DataBus;
    endcase
  end
endmodule

sva_code:
// Bindable SVA for AddressGenerator
module AddressGenerator_sva
(
  input  logic        clk,
  input  logic        ce,
  input  logic [4:0]  Operation,
  input  logic [1:0]  MuxCtrl,
  input  logic [7:0]  DataBus, T, X, Y,
  input  logic [15:0] AX,
  input  logic        Carry,
  // Internal DUT state
  input  logic [7:0]  AL, AH,
  input  logic        SavedCarry
);

  default clocking cb @(posedge clk); endclocking

  // Past-valid guard
  logic past_valid;
  always_ff @(posedge clk) past_valid <= 1'b1;

  // Decodes and combinational helpers (current cycle)
  let ALCtrl = Operation[4:2];
  let AHCtrl = Operation[1:0];
  let sum9   = {1'b0, (MuxCtrl[1] ? T  : AL)} + {1'b0, (MuxCtrl[0] ? Y : X)};
  let tmpval = (!AHCtrl[1] | SavedCarry);
  let tmpadd = (AHCtrl[1] ? AH : AL) + {7'b0, tmpval};

  // Structural correctness
  assert property (AX == {AH, AL});
  assert property (Carry == sum9[8]);

  // State hold when ce==0
  assert property (past_valid && !ce |=> (AL == $past(AL) && AH == $past(AH) && SavedCarry == $past(SavedCarry)));

  // SavedCarry update
  assert property (past_valid && ce |=> SavedCarry == $past(Carry));

  // AL update behavior
  // Hold when ALCtrl[2]==0
  assert property (past_valid && ce && !$past(Operation[4]) |=> AL == $past(AL));
  // ALCtrl[2:0] == 3'b100: AL <= NewAL (sum9[7:0])
  assert property (past_valid && ce && $past(Operation[4:2]) == 3'b100 |=> 
                   AL == ({1'b0, ($past(MuxCtrl[1]) ? $past(T)  : $past(AL))} + 
                          {1'b0, ($past(MuxCtrl[0]) ? $past(Y) : $past(X))})[7:0]);
  // 3'b101: AL <= DataBus
  assert property (past_valid && ce && $past(Operation[4:2]) == 3'b101 |=> AL == $past(DataBus));
  // 3'b110: AL <= TmpAdd
  assert property (past_valid && ce && $past(Operation[4:2]) == 3'b110 |=> 
                   AL == (( $past(Operation[1]) ? $past(AH) : $past(AL)) + 
                          {7'b0, (! $past(Operation[1]) | $past(SavedCarry))}));
  // 3'b111: AL <= T
  assert property (past_valid && ce && $past(Operation[4:2]) == 3'b111 |=> AL == $past(T));

  // AH update behavior (always under ce)
  // 2'b00: hold
  assert property (past_valid && ce && $past(Operation[1:0]) == 2'b00 |=> AH == $past(AH));
  // 2'b01: zero
  assert property (past_valid && ce && $past(Operation[1:0]) == 2'b01 |=> AH == 8'h00);
  // 2'b10: TmpAdd
  assert property (past_valid && ce && $past(Operation[1:0]) == 2'b10 |=> 
                   AH == (( $past(Operation[1]) ? $past(AH) : $past(AL)) + 
                          {7'b0, (! $past(Operation[1]) | $past(SavedCarry))}));
  // 2'b11: DataBus
  assert property (past_valid && ce && $past(Operation[1:0]) == 2'b11 |=> AH == $past(DataBus));

  // Functional coverage (concise)
  // AL write select cases
  cover property (ce && ALCtrl[2] && (ALCtrl[1:0] == 2'b00));
  cover property (ce && ALCtrl[2] && (ALCtrl[1:0] == 2'b01));
  cover property (ce && ALCtrl[2] && (ALCtrl[1:0] == 2'b10));
  cover property (ce && ALCtrl[2] && (ALCtrl[1:0] == 2'b11));
  cover property (ce && !ALCtrl[2]); // AL hold via control

  // AH write select cases
  cover property (ce && (AHCtrl == 2'b00));
  cover property (ce && (AHCtrl == 2'b01));
  cover property (ce && (AHCtrl == 2'b10));
  cover property (ce && (AHCtrl == 2'b11));

  // MuxCtrl combinations exercised
  cover property (MuxCtrl == 2'b00);
  cover property (MuxCtrl == 2'b01);
  cover property (MuxCtrl == 2'b10);
  cover property (MuxCtrl == 2'b11);

  // Carry generation/no-carry observed
  cover property (Carry == 1'b1);
  cover property (Carry == 1'b0);

  // TmpAdd path exercised with/without SavedCarry contribution
  cover property (ce && (AHCtrl == 2'b10) && (SavedCarry == 1'b1));
  cover property (ce && (AHCtrl == 2'b10) && (SavedCarry == 1'b0));

  // Global hold via ce==0
  cover property (!ce);

endmodule

// Example bind (connects to internals AL/AH/SavedCarry)
bind AddressGenerator AddressGenerator_sva sva_addrgen (
  .clk(clk), .ce(ce), .Operation(Operation), .MuxCtrl(MuxCtrl),
  .DataBus(DataBus), .T(T), .X(X), .Y(Y), .AX(AX), .Carry(Carry),
  .AL(AL), .AH(AH), .SavedCarry(SavedCarry)
);

