// SVA for RegisterAdd
`ifndef REGISTERADD_SVA
`define REGISTERADD_SVA

module RegisterAdd_sva (
  input  logic        clk_IBUF_BUFG,
  input  logic        FSM_selector_C,
  input  logic        AR,
  input  logic [1:0]  FSM_sequential_state_reg_reg
);

  default clocking @(posedge clk_IBUF_BUFG); endclocking

  bit past_valid;
  always @(posedge clk_IBUF_BUFG) past_valid <= 1'b1;

  // Sanity: no X/Z on controls and state
  assert property ( !$isunknown(FSM_selector_C) && !$isunknown(AR) )
    else $error("X/Z detected on control inputs");
  assert property ( !$isunknown(FSM_sequential_state_reg_reg) )
    else $error("X/Z detected on state");

  // Synchronous clear has priority
  assert property ( disable iff (!past_valid)
                    FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00) );

  // Next-state function when not clearing: state = prev_state + AR (mod 4)
  assert property ( disable iff (!past_valid)
                    !FSM_selector_C |=> (FSM_sequential_state_reg_reg
                                         == $past(FSM_sequential_state_reg_reg) + $past(AR)) );

  // Coverage: clear, hold, increment, and wrap-around
  cover property ( disable iff (!past_valid)
                   FSM_selector_C |=> (FSM_sequential_state_reg_reg == 2'b00) );
  cover property ( disable iff (!past_valid)
                   !FSM_selector_C &&  AR |=> (FSM_sequential_state_reg_reg
                                               == $past(FSM_sequential_state_reg_reg) + 2'd1) );
  cover property ( disable iff (!past_valid)
                   !FSM_selector_C && !AR |=> (FSM_sequential_state_reg_reg
                                               == $past(FSM_sequential_state_reg_reg)) );
  cover property ( disable iff (!past_valid)
                   $past(FSM_sequential_state_reg_reg)==2'b11 && !FSM_selector_C && AR
                   |=> (FSM_sequential_state_reg_reg == 2'b00) );

  // Hit all 2-bit states
  cover property (FSM_sequential_state_reg_reg == 2'b00);
  cover property (FSM_sequential_state_reg_reg == 2'b01);
  cover property (FSM_sequential_state_reg_reg == 2'b10);
  cover property (FSM_sequential_state_reg_reg == 2'b11);

endmodule

bind RegisterAdd RegisterAdd_sva
(
  .clk_IBUF_BUFG(clk_IBUF_BUFG),
  .FSM_selector_C(FSM_selector_C),
  .AR(AR),
  .FSM_sequential_state_reg_reg(FSM_sequential_state_reg_reg)
);

`endif

// SVA checker for fifo_counter
module fifo_counter_sva (
  input  logic        empty,
  input  logic        ge2_free,
  input  logic        ge3_free,
  input  logic [1:0]  input_tm_cnt,
  input  logic [4:0]  fifo_cnt_inc
);
  default clocking cb @($global_clock); endclocking

  function automatic [4:0] exp_cnt (
    input logic       empty_i,
    input logic       ge2_i,
    input logic       ge3_i,
    input logic [1:0] c
  );
    if (empty_i)                           exp_cnt = {3'b000, c};
    else if (ge3_i && (c == 2'b11))        exp_cnt = 5'd2;
    else if (ge2_i && (c >= 2))            exp_cnt = 5'd1;
    else if (c >= 1)                       exp_cnt = 5'd0;
    else                                   exp_cnt = 5'd31;
  endfunction

  // Functional equivalence and X-robustness
  assert property (!$isunknown({empty,ge2_free,ge3_free,input_tm_cnt})
                   |-> (fifo_cnt_inc == exp_cnt(empty,ge2_free,ge3_free,input_tm_cnt)));
  assert property (!$isunknown({empty,ge2_free,ge3_free,input_tm_cnt})
                   |-> !$isunknown(fifo_cnt_inc));

  // Output domain when not empty; and 31 only when !empty && input_tm_cnt==0
  assert property (!empty |-> (fifo_cnt_inc inside {5'd0,5'd1,5'd2,5'd31}));
  assert property ((fifo_cnt_inc == 5'd31) |-> (!empty && input_tm_cnt == 2'd0));

  // Coverage: all branches and key corners
  cover property (empty && (input_tm_cnt==2'd0) && (fifo_cnt_inc==5'd0));
  cover property (empty && (input_tm_cnt==2'd1) && (fifo_cnt_inc==5'd1));
  cover property (empty && (input_tm_cnt==2'd2) && (fifo_cnt_inc==5'd2));
  cover property (empty && (input_tm_cnt==2'd3) && (fifo_cnt_inc==5'd3));

  cover property (!empty && ge3_free && (input_tm_cnt==2'd3) && (fifo_cnt_inc==5'd2));

  cover property (!empty && !ge3_free && ge2_free && (input_tm_cnt==2'd2) && (fifo_cnt_inc==5'd1));
  cover property (!empty && !ge3_free && ge2_free && (input_tm_cnt==2'd3) && (fifo_cnt_inc==5'd1));

  cover property (!empty && (input_tm_cnt==2'd1) && (fifo_cnt_inc==5'd0));
  cover property (!empty && !ge2_free && (input_tm_cnt==2'd2) && (fifo_cnt_inc==5'd0));
  cover property (!empty && !ge3_free && !ge2_free && (input_tm_cnt==2'd3) && (fifo_cnt_inc==5'd0));

  cover property (!empty && (input_tm_cnt==2'd0) && (fifo_cnt_inc==5'd31));
endmodule

bind fifo_counter fifo_counter_sva sva_i (.*);

// SVA for up_counter
module up_counter_sva #(parameter WIDTH=4)
(
  input logic              clk,
  input logic              rst,   // active-low
  input logic [WIDTH-1:0]  count
);

  default clocking cb @(posedge clk); endclocking

  // Sanity: no X/Z on outputs
  a_no_x_count: assert property (!$isunknown(count));

  // While reset is asserted, count must be zero
  a_hold_zero_in_reset: assert property (!rst |-> count == '0);

  // After reset deasserts, first counted value is 1
  a_first_after_deassert: assert property ($rose(rst) |=> count == 'd1);

  // Increment by 1 every cycle when out of reset (handles wrap-around by width)
  a_inc_when_running: assert property (rst && $past(rst) |-> count == $past(count) + 'd1);

  // Explicit wrap check from all-ones to zero
  a_wrap_to_zero: assert property (rst && $past(rst) && ($past(count) == {WIDTH{1'b1}}) |-> count == '0);

  // Coverage: see reset assert/deassert activity
  c_reset_cycle: cover property ($fell(rst) ##[1:$] $rose(rst));

  // Coverage: observe wrap-around
  c_wrap: cover property (rst && $past(rst) && ($past(count)=={WIDTH{1'b1}}) && (count=='0));

  // Coverage: hit every count value while running
  genvar i;
  generate
    for (i = 0; i < (1<<WIDTH); i++) begin : CVALS
      c_val: cover property (rst && (count == i[WIDTH-1:0]));
    end
  endgenerate

endmodule

// Bind to DUT
bind up_counter up_counter_sva #(.WIDTH(4)) up_counter_sva_b (.clk(clk), .rst(rst), .count(count));

